 const supplierPendingNew=journal.list().filter(x=>x.kind==='productionSupplier').map(x=>`<div class="ux6-alert">Fason işleminin sonucu doğrulanmalı. <button class="btn" onclick="RitimPremiumAPI.poSupplierRetry(${jsArg(x.id)})">Aynı işlemle tekrar dene</button></div>`).join('');
 const boardPending=journal.list().filter(x=>['machinePlanning','machineBatch','machineCreate','machineCalendar'].includes(x.kind)).map(x=>'<div class="ux6-alert">Makine planlama işleminin sonucu doğrulanmalı. <button class="btn" onclick="RitimPremiumAPI.boardRetry(\''+x.id+'\')">Aynı işlemle tekrar dene</button></div>').join('');
 const workflowDone=resume&&resume.steps.order==='committed'&&['committed','skipped'].includes(resume.steps.route)&&['committed','skipped'].includes(resume.steps.plan);const toolsPending=journal.list().filter(x=>['workspacePreference','routeTemplate'].includes(x.kind)).map(x=>`<div class="ux6-alert">${x.kind==='routeTemplate'?'Rota şablonu':'Görünüm tercihi'} işlemi doğrulanmalı. <button class="btn" onclick="RitimPremiumAPI.retryWorkspaceTool(${jsArg(x.id)})">Aynı işlemi doğrula</button></div>`).join('');const pending=toolsPending+boardPending+supplierPendingNew+productionPending+masterPending+routePending+supplierPending+operationPending+workflowPending+looseHtml+(resume?`<div class="ux6-alert"><b>${workflowDone?'Sipariş kaydedildi':'Tamamlanmamış sipariş akışı'}:</b> ${h(resume.order.orderNumber)} · Sipariş ${h(stageLabel(resume.steps.order))} · Rota ${h(stageLabel(resume.steps.route))} · İş emri ${h(stageLabel(resume.steps.plan))} <button class="btn" onclick="RitimPremiumAPI.${workflowDone?'finish':'resume'}()">${workflowDone?'Siparişi görüntüle':'Devam et'}</button></div>`:'');
