 if(page==='orders')return `${pending}<div class="toolbar"><input id="api-search" class="input" aria-label="Sipariş ara" placeholder="Sipariş, müşteri veya parça ara"><button class="btn primary" onclick="openWizard()" ${capable('orders.write')?'':'disabled'}>Yeni Sipariş</button></div><div class="ux-order-results"><span class="tiny" id="api-count">${orders.length} sonuç</span><button class="btn sm" onclick="RitimPremiumAPI.clearSearch()">Filtreleri Temizle</button></div><div class="order-list-v4 ux-order-list"><div class="ux-order-heading" aria-hidden="true"><span>Müşteri / Parça</span><span>Miktar</span><span>Termin</span><span>Durum</span><span>Net sevkiyat</span><span>Sonraki adım</span></div>${orders.map(o=>{const percent=o.orderedQuantity?Math.min(100,Math.max(0,100*o.netShipped/o.orderedQuantity)):0;return `<button type="button" class="order-card-v4 ux-order-row" data-search="${h((o.orderNumber+' '+o.customer+' '+o.partName+' '+o.partNumber).toLocaleLowerCase('tr-TR'))}" onclick="RitimPremiumAPI.openOrder(${jsArg(o.id)})"><span class="ux-order-name"><strong>${h(o.customer)}</strong><small>${h(o.partName)} · ${h(o.partNumber||'—')} · ${h(o.orderNumber)}</small></span><span><small class="ux-mobile-label">Miktar</small>${o.orderedQuantity} adet</span><span><small class="ux-mobile-label">Termin</small>${h(o.dueDate||'—')}</span><span class="oc-status">${h(o.status==='open'?'Açık':o.status)}</span><span class="ux-order-progress"><small>Net sevkiyat · ${o.netShipped} / ${o.orderedQuantity} (%${Math.round(percent*100)/100})</small><span class="oc-track"><span class="oc-fill" style="width:${percent}%"></span></span></span><span class="ux-order-next">Siparişi incele ›</span></button>`}).join('')||'<p>Sipariş bulunamadı.</p>'}</div>`;
