 if(page==='rework')return pending+operationsRework(`<section class="card pad" aria-label="Tamir işleri"><h2>Tamir işleri</h2><nav class="flow-filters" aria-label="Tamir durumu"><button class="btn" aria-pressed="${!reworkHistory}" onclick="RitimPremiumAPI.reworkHistory(false)">Aktif tamirler</button><button class="btn" aria-pressed="${reworkHistory}" onclick="RitimPremiumAPI.reworkHistory(true)">Tümü / geçmiş</button></nav>${reworkOrderId?`<p>Seçili siparişin tamirleri <button class="btn sm" onclick="RitimPremiumAPI.navigate('rework')">Tüm tamirleri göster</button></p>`:''}<button class="btn" onclick="RitimPremiumAPI.refreshRework()">Yenile</button>${operationsReworkRows().slice(0,operationsLimits.rework).map(d=>`<article class="card pad"><h3>${h(d.orderNumber)} · ${h(d.partName||d.partNumber)}</h3><p>Kaynak iş ${h(d.workOrderNumber)} · Çıktı lotu ${h(d.outputLotId||'Tarihsel iz doğrulanamadı')}</p>${d.outputLotId?`<button class="btn sm" onclick="RitimPremiumAPI.openLotTrace(${jsArg(d.outputLotId)})">Lot izini aç</button>`:''}<p>Karar ${d.quantity} · Tahsisli ${d.allocated} · Kullanılabilir ${d.available}</p>${d.available&&d.outputLotId?`<label class="formfield">Tahsis miktarı<input class="input" type="number" min="1" max="${d.available}" id="rw-qty-${h(d.id)}"></label><button class="btn primary" onclick="RitimPremiumAPI.allocateRework(${jsArg(d.id)})">Tamire ayır</button>`:''}${d.allocations.map(a=>`<div><p>${a.status==='complete'?'Tamamlanan':'Tamire ayrılan'} ${a.outstanding} adet · ${a.workOrderId?`İş emri ${h(a.workOrderNumber)} · ${h(displayStatus(a.status))} · Girdi lotu ${h(a.inputLotId)}`:'İş emri bekliyor'}</p>${a.workOrderId?`<button class="btn" onclick="RitimPremiumAPI.openJob(${jsArg(a.workOrderId)},${jsArg(d.orderId)})">İş emrini ve atamayı aç</button><button class="btn" onclick="RitimPremiumAPI.openQualityJob(${jsArg(a.workOrderId)},${jsArg(d.orderId)})">Yeniden kontrol</button>`:a.outstanding?`<label class="formfield">Tamir iş emri numarası<input class="input" id="rw-number-${h(a.id)}"></label><button class="btn" onclick="RitimPremiumAPI.createReworkJob(${jsArg(d.id)},${jsArg(a.id)})">İş emri oluştur</button>`:''}</div>`).join('')}</article>`).join('')||'<p>Bu görünümde tamir işi yok. Tamamlanan kayıtlar için Tümü / geçmiş görünümünü açabilirsiniz.</p>'}</section>`);
 if(page==='quality')return `${pending}${qualityScreen()}`;
 if(page==='jobs')return pending+worklistContent();
 if(page==='job'){const j=jobs.find(x=>x.id===jobSelected);return j?`${pending}${j.productionOrderId?`<button class="btn sm" onclick="RitimPremiumAPI.poOpen(${jsArg(j.productionOrderId)})">← Bağlı üretim emri</button>`:''}<div class="card pad"><header class="job-studio-heading"><div><span class="flow-eyebrow">${h(detail.orderNumber)} · ${h(detail.customer)}</span><h2>${h(detail.partName)}</h2><p>${h(orderSummary?.jobs.find(x=>x.id===j.id)?.operation||detail.route?.find(op=>op.id===j.operationId)?.name||j.operationName||'İş emri')} · <button class="job-reference" title="İş emri numarasını kopyala" onclick="RitimPremiumAPI.copyJobReference(${jsArg(j.workOrderNumber)})">${h(j.workOrderNumber)} ⧉</button></p></div><span class="pill" data-state="${h(j.status)}">${h(displayStatus(j.status))}</span></header><div class="job-studio-totals"><span>Hedef <b>${j.plannedQuantity} adet</b></span><span>İşlenen <b>${j.recordedProduction||0}</b></span><span>Hurda <b>${j.recordedScrap||0}</b></span></div><div class="job-studio-grid">${assignmentPanel(j)}<div>${managerJobSummary(j)}${drawingPanel()}</div></div><details class="card pad"><summary>Malzeme ve depo</summary><p>Fiziksel malzeme girişlerini ve teslimlerini depodan takip edin.</p><button class="btn" onclick="RitimPremiumAPI.navigate('inventory')">Depoyu aç</button></details>${historyPanel()}</div>`:'<p>İş emri bulunamadı.</p>'}
