 function drawingPanel(){if(!drawingInfo?.required)return '';if(drawingInfo.unpublished)return '<section class="card pad"><h3>Teknik Çizim</h3><p>Eski çizim henüz güvenilir biçimde yayınlanmadı. Üretim kapalıdır.</p></section>';return `<section class="card pad"><h3>Teknik Çizim · Revizyon ${h(drawingInfo.revision)}</h3>${drawingNotice?`<p class="ux6-alert" role="status">${h(drawingNotice)}</p>`:''}<p>${drawingInfo.acknowledged?'Bu revizyonu onayladınız.':'Bu revizyon için açık onayınız gerekli.'}</p><button class="btn" onclick="RitimPremiumAPI.openDrawing()">Güncel Çizimi Aç</button> <button class="btn primary" onclick="RitimPremiumAPI.ackDrawing()" ${drawingInfo.acknowledged||!isOperator()||!capable('production.write')||drawingViewed!==drawingInfo.publicationId?'disabled':''}>Bu çizimi inceledim</button><dialog id="api-drawing-dialog" aria-labelledby="api-drawing-title" style="width:min(850px,calc(100vw - 24px));max-width:calc(100vw - 24px)"><h2 id="api-drawing-title">Teknik Çizim · ${h(drawingInfo.revision)}</h2>${drawingDocument?`<iframe title="Teknik çizim PDF" onload="RitimPremiumAPI.drawingLoaded(this,${jsArg(drawingInfo.publicationId)})" src="data:application/pdf;base64,${drawingDocument}#view=FitH" style="width:100%;height:55vh;border:0"></iframe><a class="btn" href="data:application/pdf;base64,${drawingDocument}" download="teknik-cizim.pdf">PDF indir veya cihazınızda aç</a>`:''}<button class="btn" onclick="document.getElementById('api-drawing-dialog').close()">Kapat</button></dialog></section>`}
 function operatorPanel(j){if(!productionView||!qualityView)return '<p>Üretim mutabakatı gerekli; kayıt işlemleri kapalıdır.</p>';const p=productionView,a=p.attention,q=qualityView,own=scope.roles?.includes('operator'),action={waiting:'start',running:'results',paused:'resume'}[j.status],text={start:'İşi başlat',results:'Üretim bildir',resume:'Devam et'}[action],lots=p.lots.filter(x=>x.available>0),first=lots[0],complete=a?.completion,pending=journal.list().filter(x=>x.kind==='production'&&x.body.workOrderId===j.id);return `<section class="card pad flow-production-panel"><div class="flow-heading"><div><h3>Üretim bildirimi</h3><p>${h(a?.reason||poStatus(j.status))}</p></div><span class="pill" data-state="${h(j.status)}">${h(poStatus(j.status))}</span></div>${pending.map(x=>`<div class="ux6-alert">Kayıt sonucu doğrulanmalı. <button class="btn" onclick="RitimPremiumAPI.retryOperation(${jsArg(x.id)})">Aynı işlemle tekrar dene</button></div>`).join('')}<div class="flow-metrics">${flowMetric('Alınan girdi',p.inputQuantity)}${flowMetric('İşlenen girdi',p.consumedQuantity)}${flowMetric('Kalan girdi',p.remainingUsableInput)}</div>${own?`${action==='results'?`<div class="formgrid"><label class="formfield">Girdi lotu<select id="api-input-lot" class="select" onchange="RitimPremiumAPI.productionLotChanged()">${lots.map(l=>`<option value="${h(l.lotId)}">${h(l.label||shortReference(l.lotId))} · ${l.available} adet</option>`).join('')}</select></label><label class="formfield">İşlenen adet<input id="api-production-qty" class="input" type="number" min="1" max="${first?.available||0}" step="1" inputmode="numeric" required></label><label class="formfield">Sonuç<select id="api-production-kind" class="select"><option value="pending">Kalite kontrolüne gönder</option><option value="scrap">Hurda</option><option value="setup_scrap">Ayar hurdası</option>${scope.roles?.some(r=>['manager','tenant_admin','superadmin'].includes(r))?'<option value="good">Sağlam · yetkili öz kontrol</option>':''}</select></label></div>`:''}${action?`<button class="btn primary flow-primary" onclick="RitimPremiumAPI.productionAction(${jsArg(action)})" ${busy||(action==='results'?!lots.length:!a?.ready)?'disabled':''}>${text}</button>`:''}${j.status==='running'?`<details class="flow-details"><summary>İşi duraklat</summary><label class="formfield">Duraklatma nedeni<select id="api-pause-category" class="select"><option>Malzeme bekleniyor</option><option>Takım değişimi</option><option>Makine arızası</option><option>Kalite bekleniyor</option><option>Vardiya sonu</option><option>Diğer</option></select></label><label class="formfield">Açıklama <small>İsteğe bağlı</small><input id="api-pause-reason" class="input" maxlength="80"></label><button class="btn" onclick="RitimPremiumAPI.productionAction('pause')">Duraklat</button></details>`:''}${['running','paused'].includes(j.status)?`<div class="flow-finish"><b>İşi bitirme kontrolü</b>${complete&&!complete.ready?`<ul>${complete.reasons.map(x=>`<li>${h(x)}</li>`).join('')||'<li>Açık işlemler sunucuda kontrol edilecek.</li>'}</ul>`:'<p>Son miktar ve açık işlem kontrolleri kayıtta yapılır.</p>'}<button class="btn" onclick="RitimPremiumAPI.productionAction('complete')" ${complete&&!complete.ready?'disabled':''}>İşi bitir</button></div>`:''}`:'<p>Üretim bildirimi atanan operatör tarafından yapılır. Bu görünümden işin durumunu ve miktarlarını takip edebilirsiniz.</p>'}<details class="flow-details"><summary>Kalite özeti</summary>${q.outputs.map(o=>`<p>Onay ${o.approved} · Ret ${o.rejected} · Tamir bekleyen ${o.reworkPending??o.rework} · Karar bekleyen ${o.unresolved}</p>`).join('')||'<p>Henüz üretim çıktısı yok.</p>'}${capable('quality.write')?`<button class="btn" onclick="RitimPremiumAPI.openQualityJob(${jsArg(j.id)},${jsArg(detail.id)})">Kalite kontrolünü aç</button>`:''}</details></section>`}
 function outsourcingContent(){const v=outsourcingView;return `<section class="card pad"><h2>Fason</h2><p>Yalnız kalite onaylı fiziksel dönüş sonraki iç operasyona teslim edilebilir.</p><h3>1. Fason operasyonunu seç</h3>${orderChoiceSearch()}<label class="formfield">Sipariş<select class="select" id="fason-order" onchange="RitimPremiumAPI.selectOutsourcingOrder()"><option value="">Seçin</option>${orders.map(o=>`<option value="${h(o.id)}" ${o.id===outsourcingOrder?'selected':''}>${h(o.orderNumber)} · ${h(o.customer)}</option>`).join('')}</select></label><details><summary>Tedarikçi kaydı</summary>${outsourcingSuppliers.map(x=>`<p>${h(x.code)} · ${h(x.name)}</p>`).join('')||'<p>Tedarikçi yok.</p>'}<label class="formfield">Tedarikçi kodu<input class="input" id="fason-code"></label><label class="formfield">Tedarikçi adı<input class="input" id="fason-name"></label><button class="btn" ${capable('stock.write')?'':'disabled'} onclick="RitimPremiumAPI.createSupplier()">Tedarikçi ekle</button></details>${v?(v.supported?`<h3>2. Tedarikçi ve kaynak · ${h(v.operation?.name||'Fason operasyonu')}</h3><label class="formfield">Tedarikçi<select class="select" id="fason-supplier">${outsourcingSuppliers.map(x=>`<option value="${h(x.id)}">${h(x.name)}</option>`).join('')}</select></label><button class="btn" ${capable('planning.write')?'':'disabled'} onclick="RitimPremiumAPI.outsource('outsourcingJob','')">Fason işi oluştur</button><label class="formfield">Fason işi<select class="select" id="fason-job">${v.jobs.filter(x=>!logisticsRecord||logisticsRecord.kind!=='outsourcing'||x.id===logisticsRecord.id).map(x=>`<option value="${h(x.id)}" ${logisticsRecord?.kind==='outsourcing'&&logisticsRecord.id===x.id?'selected':''}>${h(outsourcingSuppliers.find(s=>s.id===x.supplierId)?.name||x.id)}</option>`).join('')}</select></label><label class="formfield">Onaylı kaynak lot<select class="select" id="fason-lot">${v.lots.filter(x=>x.availableApproved>0).map(x=>`<option value="${h(x.lotId)}">${h(x.lotId)} · ${x.availableApproved} adet</option>`).join('')}</select></label><h3>3. Tedarikçiye gönder</h3><label class="formfield">Gönderim miktarı<input class="input" id="fason-send-qty" type="number" min="1"></label><button class="btn primary" ${capable('stock.write')?'':'disabled'} onclick="RitimPremiumAPI.outsource('outsourcingDispatch',document.getElementById('fason-job').value)">Tedarikçiye gönder</button><h3>4. Kısmi dönüş ve giriş kontrolü</h3>${v.dispatches.filter(d=>!logisticsRecord||logisticsRecord.kind!=='outsourcing'||d.jobId===logisticsRecord.id).map(d=>`<article class="card pad"><p>Gönderilen ${d.quantity} · Dönen ${d.returned} · Dışarıda ${d.outstanding}</p><p class="tiny">Beklenen dönüş: ${h(d.expectedReturnDate||'Belirlenmedi')}${d.outstanding&&d.expectedReturnDate&&d.expectedReturnDate<new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/Istanbul',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date())?' · Dönüş gecikmiş':''}</p><details><summary>Fiziksel dönüş kaydet</summary><label class="formfield">Dönüş miktarı<input class="input" type="number" min="1" id="fason-return-${h(d.id)}"></label><button class="btn" ${capable('stock.write')?'':'disabled'} onclick="RitimPremiumAPI.outsource('outsourcingReturn',${jsArg(d.id)})">Fiziksel dönüş al</button></details>${d.returns.map(r=>`<div><p>Lot ${h(r.lotId)} · Onay ${r.approved} · Ret ${r.rejected} · Kontrol bekleyen ${r.pending} · Teslim edilebilir ${r.availableApproved} · Teslim edilen ${r.released}</p><button class="btn sm" onclick="RitimPremiumAPI.openLotTrace(${jsArg(r.lotId)})">Lot izini aç</button><details><summary>Kontrol geçmişi</summary>${(r.history||[]).map(x=>`<p>${x.outcome==='approved'?'Onay':'Ret'} · ${x.quantity} · ${h(x.evidence)} · ${h(x.createdAt)}</p>`).join('')||'<p>Henüz kontrol yok.</p>'}</details><details><summary>Giriş kontrolü yap</summary><label class="formfield">Karar<select class="select" id="fason-outcome-${h(r.id)}"><option value="approved">Onay</option><option value="rejected">Ret</option></select></label><label class="formfield">Miktar<input class="input" type="number" min="1" id="fason-inspect-${h(r.id)}"></label><label class="formfield">Kontrol kanıtı<input class="input" id="fason-evidence-${h(r.id)}"></label><button class="btn" ${capable('quality.write')?'':'disabled'} onclick="RitimPremiumAPI.outsource('outsourcingInspect',${jsArg(r.id)})">Giriş kontrolü kaydet</button></details><details><summary>Sonraki işe teslim et</summary><label class="formfield">Sonraki iş emri numarası<input class="input" id="fason-wo-${h(r.id)}"></label><label class="formfield">Teslim ve plan miktarı<input class="input" type="number" min="1" id="fason-plan-${h(r.id)}"></label><button class="btn" ${capable('planning.write')&&r.availableApproved>0?'':'disabled'} onclick="RitimPremiumAPI.outsource('outsourcingPlan',${jsArg(r.id)})">Planla ve fiziksel teslim al</button></details></div>`).join('')}</article>`).join('')}`:'<p>Yalnız iç → fason → iç rotası desteklenir.</p>'):''}</section>`}
 function qualityScreenOriginal(){if(!qualityView)return '<p>Kalite bilgisi yükleniyor.</p>';return `<section class="card pad"><h2>Kalite Kontrol · ${h(jobs.find(j=>j.id===jobSelected)?.workOrderNumber||'İş emri')}</h2><p>Onaylanmamış çıktı sonraki işe sevk edilmez. Tamir için kalite kuyruğundan iş emri oluşturun.</p><h3>Kontrol bekleyenler</h3>${qualityView.outputs.map((o,i)=>o.unresolved?`<article class="card pad"><p>Çıktı lotu ${h(o.outputLotId||'Tarihsel iz doğrulanamadı')} · Üretim ${h(o.eventId)}</p>${o.outputLotId?`<button class="btn sm" onclick="RitimPremiumAPI.openLotTrace(${jsArg(o.outputLotId)})">Lot izini aç</button>`:''}<p>Onay ${o.approved} · Ret ${o.rejected} · Tamir bekleyen ${o.reworkPending??o.rework} · Karar bekleyen ${o.unresolved}</p>${o.unresolved?`<button class="btn primary" onclick="RitimPremiumAPI.openQualityDialog(${i})" ${capable('quality.write')?'':'disabled'}>Karar ver</button>`:''}</article>`:'').join('')||(qualityView.unavailable?'<p>Tarihsel üretim mutabakatı gerekli; kontrol miktarları doğrulanamadı.</p>':'<p>Kontrol bekleyen üretim yok.</p>')}${qualityView.outputs.some(o=>(o.reworkPending??o.rework)>0)?'<button class="btn" onclick="RitimPremiumAPI.openRepair()">Tamir işlerini aç</button>':''}${capable('quality.write')||capable('planning.write')?`<button class="btn" onclick="RitimPremiumAPI.openRecovery(${jsArg(detail.id)})">Kayıplar ve telafi işlemleri</button>`:''}<h3>Tamir bekleyenler</h3>${qualityView.outputs.filter(o=>(o.reworkPending??o.rework)>0).map(o=>`<p>Çıktı ${h(o.outputLotId||'Tarihsel iz doğrulanamadı')} · Tamir bekleyen ${o.reworkPending??o.rework} · Kuyruktan iş emri oluşturulabilir</p>`).join('')||'<p>Tamir bekleyen yok.</p>'}<details class="flow-details"><summary>Tamamlanan kontroller ve geçmiş</summary><h3>Tamamlanan kontroller</h3>${qualityView.outputs.filter(o=>!o.unresolved&&!(o.reworkPending??o.rework)).map(o=>`<p>Çıktı ${h(o.outputLotId||'Tarihsel iz doğrulanamadı')} · Onay ${o.approved} · Ret ${o.rejected} · Tamir bekleyen ${o.reworkPending??o.rework}</p>`).join('')||'<p>Tamamlanan kontrol yok.</p>'}<h3>Üretim geçmişi</h3>${(extras.productionHistory?.events||[]).map(e=>`<p>${h(displayStatus(e.kind))} · ${e.quantity} · ${h(e.provenanceStatus==='historical_unreconciled'?'Tarihsel iz doğrulanamadı':e.outputLotId||'Çıktı lotu yok')}</p>`).join('')}<h3>Karar geçmişi</h3>${(extras.qualityHistory?.decisions||[]).map(d=>`<p>${h(displayStatus(d.outcome))} · ${d.quantity} · ${h(d.evidence)} · ${h(d.outputLotId||'Tarihsel iz doğrulanamadı')}</p>`).join('')||'<p>Henüz karar yok.</p>'}</details><dialog id="api-quality-dialog" aria-labelledby="api-quality-title" style="width:min(520px,calc(100vw - 32px));max-width:calc(100vw - 32px);border:0;border-radius:16px"><h2 id="api-quality-title">Kalite kararı</h2><p id="quality-dialog-context"></p><label class="formfield">Karar<select id="quality-dialog-kind" class="select"><option value="approved">Onay</option><option value="rejected">Ret / hurda</option><option value="rework">Tamir gerekli</option></select></label><label class="formfield">Miktar<input id="quality-dialog-quantity" type="number" min="1" class="input"></label><label class="formfield">Kontrol kanıtı<input id="quality-dialog-evidence" class="input"></label><p role="alert" id="quality-dialog-error"></p><button class="btn" type="button" onclick="document.getElementById('api-quality-dialog').close()">İptal</button><button class="btn primary" type="button" onclick="RitimPremiumAPI.submitQualityDialog()">Kararı Kaydet</button></dialog></section>`}
 function managerJobSummary(j){const p=productionView,a=p?.attention,reason=a?.reason||'',assignmentReason=/makine|operatör/i.test(reason);return `<section class="job-readiness"><h3>Girdi miktarları</h3><div class="job-input-metrics">${[['Alınan',p?.inputQuantity],['İşlenen',p?.consumedQuantity],['Kalan',p?.remainingUsableInput]].map(([label,value])=>`<div><small>${label}</small><b>${value??'—'}</b></div>`).join('')}</div>${reason&&!assignmentReason?`<p>${h(reason)}</p>`:''}${capable('quality.write')&&(qualityView?.outputs||[]).length?`<button class="btn sm" onclick="RitimPremiumAPI.openQualityJob(${jsArg(j.id)},${jsArg(detail.id)})">Kalite sonuçları</button>`:''}</section>`}

 function assignmentPanel(j){const a=extras.assignment;if(!a)return '';const current=a.assignments.find(x=>!x.releasedAt),operator=a.operators.find(x=>x.id===current?.operatorId),machine=a.machines.find(x=>x.id===current?.machineId),disabled=!['waiting','paused'].includes(j.status);return `<section class="card pad assignment-panel assignment-studio"><h3>Makine ve operatör</h3>${disabled?'<p>Atamayı değiştirmek için çalışan işi duraklatın.</p>':''}<div class="assignment-studio-grid"><div><small>Operatör</small><input type="hidden" id="assign-operator" value="${h(current?.operatorId||'')}"><button class="resource-choice" id="assign-operator-choice" onclick="RitimPremiumAPI.chooseResource('operator')" ${disabled?'disabled':''}>${navigationIcon('production')}<span>${h(operator?.displayName||'Operatör seç')}</span></button></div><div><small>Makine</small><input type="hidden" id="assign-machine" value="${h(current?.machineId||'')}"><button class="resource-choice" id="assign-machine-choice" data-missing="${!current?.machineId}" onclick="RitimPremiumAPI.chooseResource('machine')" ${disabled?'disabled':''}>${navigationIcon('planning')}<span>${h(machine?.code||'Makine seç')}</span></button>${!current?.machineId?'<small class="assignment-warning">⚠ Makine atanmadı</small>':''}</div></div><details class="assignment-note"><summary>İşlem notu ekle · isteğe bağlı</summary><input class="input" aria-label="İşlem notu" id="assign-reason" maxlength="120" placeholder="Atama düzenlemesi"></details><div class="assignment-footer" id="assignment-savebar" hidden><span>Kaydedilmemiş seçimler</span><button class="btn primary" id="assign-handover" onclick="RitimPremiumAPI.assignmentTransfer()" disabled>Atamayı kaydet</button></div></section>`}

 function materialPanel(j){const m=extras.material;if(!m)return '';return `<details class="card pad"><summary>Malzeme · KURGUSAL GELİŞTİRME VERİSİ</summary><p>Kayıt, tahsis ve fiziksel kabul ayrı işlemlerdir.</p><label class="formfield">Kurgusal tedarikçi<input id="material-supplier" class="input"></label><label class="formfield">Kurgusal belge<input id="material-document" class="input"></label><label class="formfield">Adet<input id="material-quantity" class="input" type="number" min="1"></label><button class="btn" onclick="RitimPremiumAPI.material('materialReceipt')" ${capable('stock.write')?'':'disabled'}>Kurgusal malzeme kaydet</button><label class="formfield">Malzeme lotu<select id="material-lot" class="select">${m.materials.map(x=>`<option value="${h(x.lotId)}">${h(x.documentRef)} · ${x.available} uygun</option>`).join('')}</select></label><label class="formfield">Tahsis adedi<input id="allocation-quantity" class="input" type="number" min="1"></label><button class="btn" onclick="RitimPremiumAPI.material('allocation')" ${capable('orders.write')?'':'disabled'}>İş emrine tahsis et</button><label class="formfield">Tahsis<select id="material-allocation" class="select">${m.allocations.filter(x=>x.workOrderId===j.id).map(x=>`<option value="${h(x.id)}">${x.received} / ${x.quantity} fiziksel kabul</option>`).join('')}</select></label><label class="formfield">Fiziksel kabul adedi<input id="receipt-quantity" class="input" type="number" min="1"></label><button class="btn" onclick="RitimPremiumAPI.material('physicalReceipt')" ${capable('orders.write')?'':'disabled'}>Fiziksel kabul et</button></details>`}
 function historyPanel(){return `<details class="card pad"><summary>Üretim ve kalite geçmişi</summary>${(extras.productionHistory?.events||[]).map(e=>`<p>${h(displayStatus(e.kind))} · ${e.quantity} · Girdi ${h(e.inputLotId||'bilinmiyor')} · Çıktı ${h(e.outputLotId||'yok')} ${e.provenanceStatus==='historical_unreconciled'?'· Tarihsel iz doğrulanamadı':''}</p>${e.outputLotId?`<button class="btn sm" onclick="RitimPremiumAPI.openLotTrace(${jsArg(e.outputLotId)})">Lot izini aç</button>`:''}`).join('')||'<p>Üretim kaydı yok.</p>'}${(extras.qualityHistory?.decisions||[]).map(e=>`<p>${h(displayStatus(e.outcome))} · ${e.quantity} · ${h(e.evidence)}</p>`).join('')}</details>`}
 function downstreamPanel(){const d=extras.downstream;if(!d)return '<p>Sonraki operasyon bilgisi yüklenmedi.</p>';return `<section class="card pad"><h3>Sonraki iç operasyon</h3>${d.supported?`<p>${h(d.nextOperation.name)} · Rezervasyon fiziksel kabul değildir.</p><label class="formfield">Onaylı çıktı lotu<select id="down-lot" class="select">${d.outputs.map(x=>`<option value="${h(x.lotId)}">${h(x.lotId)} · ${x.availableApproved} uygun</option>`).join('')}</select></label><label class="formfield">İş emri numarası<input id="down-number" class="input"></label><label class="formfield">Planlanan adet<input id="down-qty" class="input" type="number" min="1"></label><button class="btn primary" onclick="RitimPremiumAPI.downstream('downstreamPlan')" ${capable('planning.write')?'':'disabled'}>Sonraki işi planla ve ayır</button><label class="formfield">Hedef iş emri<select id="down-job" class="select">${d.workOrders.map(x=>`<option value="${h(x.id)}">${h(x.number)} · ${x.plannedQuantity}</option>`).join('')}</select></label><label class="formfield">Ek rezervasyon adedi<input id="reserve-qty" class="input" type="number" min="1"></label><button class="btn" onclick="RitimPremiumAPI.downstream('reserve')" ${capable('planning.write')?'':'disabled'}>Ek rezervasyon</button>${d.outputs.flatMap(o=>o.reservations.map(r=>{const dispatched=d.dispatches.filter(x=>x.reservationId===r.id).reduce((n,x)=>n+x.quantity,0),remaining=r.outstanding-dispatched,valid=Number.isSafeInteger(remaining)&&remaining>=0;return `<div class="card pad"><p>Rezervasyon ${h(r.id)} · Toplam ayrılmış ${r.outstanding} · Sevk edilen ${dispatched} · Sevk edilebilir ${valid?remaining:'Doğrulanamadı'}</p>${!valid?'<p role="alert">Miktarlar doğrulanamadı; işlemler kapalı.</p>':''}<label class="formfield">Adet<input class="input" type="number" min="1" ${valid?`max="${remaining}"`:''} id="reservation-${h(r.id)}"></label><button class="btn" onclick="RitimPremiumAPI.movement('release',${jsArg(r.id)})" ${capable('planning.write')&&valid&&remaining>0?'':'disabled'}>Rezervasyon bırak</button><button class="btn" onclick="RitimPremiumAPI.movement('dispatch',${jsArg(r.id)})" ${capable('stock.write')&&valid&&remaining>0?'':'disabled'}>Fiziksel sevk</button></div>`})).join('')}${d.dispatches.map(x=>`<div class="card pad"><p>Sevk ${x.quantity} · Yolda ${x.inTransit} · Kabul ${x.received}</p><label class="formfield">Kabul adedi<input class="input" type="number" min="1" id="dispatch-${h(x.id)}"></label><button class="btn" onclick="RitimPremiumAPI.movement('receive',${jsArg(x.id)})" ${capable('stock.write')?'':'disabled'}>Hedefte kabul et</button></div>`).join('')}${d.receipts.map(x=>`<p>Fiziksel kabul ${x.quantity} · Girdi lotu ${h(x.inputLotId)}</p>`).join('')}`:`<p>${h(d.reason||'Desteklenmeyen rota')}</p>`}</section>`}
 async function loadJobViews(order,id){drawingInfo=await api.readOperation('drawing',order,id);drawingDocument=null;drawingViewed=null;try{productionView=await api.production(order,id);qualityView=await api.quality(order,id);await loadExtras()}catch(e){if(!['PRODUCTION_RECONCILIATION_REQUIRED','INTEGRITY_ERROR'].includes(e.code))throw e;productionView=null;qualityView={unavailable:true,outputs:[]};extras={productionHistory:await api.readOperation('productionHistory',order,id),qualityHistory:await api.readOperation('qualityHistory',order,id)};error='Tarihsel kayıt mutabakatı gerekli; üretim ve kalite yazma işlemleri kapalı.'}}
 async function loadExtras(){if(!detail)return;extras.material=await api.readOperation('material',detail.id);extras.downstream=await api.readOperation('downstream',detail.id);if(jobSelected){extras.handoff=isOperator()?await api.readOperation('handoff',detail.id,jobSelected):null;if(capable('orders.write'))extras.assignment=await api.readOperation('assignment',detail.id,jobSelected);else extras.assignment=null;extras.productionHistory=await api.readOperation('productionHistory',detail.id,jobSelected);extras.qualityHistory=await api.readOperation('qualityHistory',detail.id,jobSelected)}}
 async function loadQualityQueue(){const originScope=scope;qualityQueue=[];qualityQueueErrors=[];for(let i=0;i<jobs.length;i+=8){const batch=jobs.slice(i,i+8);const results=await Promise.allSettled(batch.map(j=>api.quality(j.orderId,j.id)));if(scope!==originScope)return;for(let k=0;k<batch.length;k++){const result=results[k],job=batch[k];if(result.status==='rejected'){qualityQueueErrors.push({job,message:result.reason?.message||'Kalite durumu alınamadı'});continue}for(const output of result.value.outputs||[]){if(!Number.isSafeInteger(output.unresolved)||output.unresolved<0){qualityQueueErrors.push({job,message:'Kalite miktarı doğrulanamadı'});continue}if(output.unresolved>0)qualityQueue.push({job,output})}}}}
 async function loadRework(more=false){const origin=scope,query=repairQuery,order=reworkOrderId,state=reworkHistory?'all':'active',result=await api.reworkDecisions(more?repairCursor:null,{limit:20,q:query,state,...order?{orderId:order}:{}});if(scope!==origin)return;const rows=result.decisions;reworkDecisions=more?[...new Map(reworkDecisions.concat(rows).map(x=>[x.id,x])).values()]:rows;repairCursor=result.nextAfter;repairTotal=result.total??reworkDecisions.length;operationsLimits.rework=more?operationsLimits.rework+20:20}
 async function sendOperation(command,resourceId,payload){const unresolved=journal.list().find(x=>x.kind==='operation'&&x.actorId===scope.actorId&&x.tenantId===scope.tenantId&&x.siteId===scope.siteId&&x.body.orderId===detail.id&&x.body.command===command&&x.body.resourceId===(resourceId||'')&&JSON.stringify(x.body.payload)!==JSON.stringify(payload));if(unresolved)throw Error('Önce aynı işlemdeki belirsiz sonucu doğrulayın.');const row=await journal.begin({...scope,kind:'operation',target:resourceId||detail.id,body:{orderId:detail.id,resourceId:resourceId||'',command,payload}});try{await journal.execute(row,r=>api.writeOperation(r.body.command,r.body.orderId,r.body.resourceId,r.body.payload,r.id))}catch(e){if(command==='machine'&&capable('orders.write')){try{extras.assignment=await api.readOperation('assignment',detail.id,jobSelected)}catch{}}throw e}await loadDetail(detail.id);await loadExtras();if(jobSelected&&command!=='drawingAck'){productionView=await api.production(detail.id,jobSelected);qualityView=await api.quality(detail.id,jobSelected)}}
 function fieldError(id,message){const field=el(id);if(!field)return;field.setAttribute('aria-invalid','true');let note=el(id+'-error');if(!note){note=document.createElement('p');note.id=id+'-error';note.className='field-error';note.setAttribute('role','alert');field.insertAdjacentElement('afterend',note)}note.textContent=message;field.setAttribute('aria-describedby',note.id);field.focus();field.addEventListener('input',()=>{field.removeAttribute('aria-invalid');note.remove()},{once:true})}
 function validAmount(id,max){const n=Number(el(id)?.value);if(!Number.isSafeInteger(n)||n<1||!Number.isSafeInteger(max)||n>max){fieldError(id,'1–'+Math.max(0,max)+' arasında tam adet girin.');return false}return true}
 function shippingAvailable(){const v=shippingView,val=id=>el('ship-'+id)?.value||'',events=v.events||[];if(shippingTask==='allocate'){const release=val('return-release');return release?(v.returnedLots||[]).find(x=>x.releaseId===release.split('|')[0])?.availableToShip||0:v.lots.find(x=>x.lotId===val('lot'))?.availableToShip||0}const source=events.find(x=>x.id===val(shippingTask==='dispatch'?'allocation':'dispatch'));if(!source)return 0;const used=events.filter(x=>x.type===(shippingTask==='dispatch'?'dispatch':'deliver')&&x[shippingTask==='dispatch'?'allocationId':'dispatchId']===source.id).reduce((n,x)=>n+x.quantity,0);return Math.max(0,source.quantity-used)}
 function shippingBindings(){const input=el('ship-quantity');if(!input)return;input.max=shippingAvailable();for(const field of document.querySelectorAll('.flow-shipping-step select'))field.onchange=shippingBindings;const button=document.querySelector('.flow-shipping-step .btn.primary');if(button)button.disabled=busy||!capable('shipment.write')||orders.find(x=>x.id===selected)?.status!=='open'||shippingAvailable()<1}
 function thisInventoryBindings(){layoutInventoryPanels();applyStockFilters();const field=el('inv-balance');if(field){field.addEventListener('change',()=>RitimPremiumAPI.inventoryBalanceChanged());RitimPremiumAPI.inventoryBalanceChanged()}}
 let handoffDraft=null;
 let notificationTimer=null,notificationLoading=false;
 function workflowDialog(title,body){el('workflow-dialog')?.remove();const d=document.createElement('dialog');d.id='workflow-dialog';d.className='workflow-dialog';d.innerHTML=`<header><h2>${h(title)}</h2><button class="btn" aria-label="Kapat" onclick="this.closest('dialog').close()">×</button></header>${body}`;document.body.append(d);d.showModal();return d}
