 function rmaContentOriginal(){const v=rmaView,opts=shippingReady.map(o=>`<option value="${h(o.id)}" ${o.id===selected?'selected':''}>${h(o.orderNumber)} · ${h(o.customer)}</option>`).join('');return `<section class="card pad"><h2>Müşteri İadeleri</h2><p>İade edilen ürünler karantinadadır; onay otomatik sevk hakkı vermez.</p>${orderChoiceSearch()}<label class="formfield">Sipariş<select class="select" id="rma-order" onchange="RitimPremiumAPI.selectRmaOrder()">${opts}</select></label>${v?`<details class="flow-details" ${logisticsRecord||v?.returns?.length?'':'open'}><summary>Yeni iade yetkilendir</summary><h3>1. Teslimatı seç ve iade oluştur</h3><label class="formfield">Teslimat<select class="select" id="rma-delivery">${v.deliveries.map(d=>`<option value="${h(d.id)}">${h(shortReference(d.id))} · Teslim ${d.delivered} · İade yetkisi kalan ${d.available}</option>`).join('')}</select></label><label class="formfield">İade numarası<input class="input" id="rma-number"></label><label class="formfield">Müşteri gerekçesi<input class="input" id="rma-reason"></label><label class="formfield">Yetkilendirilecek adet<input class="input" type="number" min="1" id="rma-qty"></label><button class="btn primary" ${capable('shipment.write')?'':'disabled'} onclick="RitimPremiumAPI.rmaAction('rmaAuthorize','')">İadeyi yetkilendir</button></details><h3>Fiziksel dönüş ve karantina</h3>${v.returns.filter(a=>!logisticsRecord||logisticsRecord.kind!=='returns'||a.id===logisticsRecord.id).map(a=>`<article class="card pad"><h3>${h(a.number)}</h3><p>${h(a.reason)}</p><div class="flow-metrics">${flowMetric('Yetkilendirilen',a.authorized)}${flowMetric('Fiziksel alınan',a.received)}${flowMetric('Dönüş bekleyen',a.outstanding)}${flowMetric('Karantinada',a.receipts.reduce((n,r)=>n+r.quarantined,0))}${flowMetric('Serbest bırakılan',a.receipts.reduce((n,r)=>n+r.released,0))}</div><details ${a.outstanding?'':'class="completed-action"'}><summary>${a.outstanding?'İade kabulünü kaydet':'Fiziksel kabul tamamlandı'}</summary><label class="formfield">Fiziksel dönüş adedi<input class="input" type="number" min="1" max="${a.outstanding}" id="rma-receive-${h(a.id)}"></label><button class="btn" ${capable('stock.write')&&a.outstanding>0?'':'disabled'} onclick="RitimPremiumAPI.rmaAction('rmaReceipt',${jsArg(a.id)})">Karantinaya kabul et</button></details>${a.receipts.map(r=>`<div><p>Lot <abbr title="${h(r.lotId)}">${h(shortReference(r.lotId))}</abbr> · Alınan ${r.quantity} · Karantina ${r.quarantined} · Hurda ${r.scrap} · Onaylı ${r.approved} · Serbest ${r.released} · Tamir ${r.rework}</p><button class="btn sm" onclick="RitimPremiumAPI.openLotTrace(${jsArg(r.lotId)})">Lot izini aç</button><details><summary>İade kontrolünü kaydet</summary><label class="formfield">Kontrol adedi<input class="input" type="number" min="1" max="${Math.max(0,r.quantity-r.inspections.reduce((n,i)=>n+i.quantity,0))}" id="rma-inspect-${h(r.id)}"></label><label class="formfield">Kontrol kanıtı<input class="input" id="rma-evidence-${h(r.id)}"></label><button class="btn" ${capable('quality.write')&&r.quantity>r.inspections.reduce((n,i)=>n+i.quantity,0)?'':'disabled'} onclick="RitimPremiumAPI.rmaAction('rmaInspect',${jsArg(r.id)})">Kontrol kaydet</button></details>${r.inspections.map(i=>`<div><p>Kontrol ${i.quantity} · Kararsız ${i.undecided} · ${h(i.evidence)}</p><details><summary>İade kararı ver</summary><label class="formfield">Karar<select class="select" id="rma-outcome-${h(i.id)}"><option value="rework">Yeniden işleme</option><option value="scrap">Hurda</option><option value="approved">Onay · karantinada kalır</option></select></label><label class="formfield">Karar adedi<input class="input" type="number" min="1" max="${i.undecided}" id="rma-decision-${h(i.id)}"></label><button class="btn" ${capable('quality.write')&&i.undecided>0?'':'disabled'} onclick="RitimPremiumAPI.rmaAction('rmaDisposition',${jsArg(i.id)})">İade kararı kaydet</button></details>${i.decisions.map(d=>`<p>${h(({rework:'Yeniden işleme',scrap:'Hurda',approved:'Onaylı'})[d.outcome]||d.outcome)} · ${d.quantity} ${d.workOrderId?'· İş emri '+h(shortReference(d.workOrderId)):''}</p>${d.outcome==='scrap'&&capable('quality.write')?`<button class="btn sm" onclick="RitimPremiumAPI.openRecovery(${jsArg(selected)})">Telafi işlemlerini aç</button>`:''}${d.workOrderId?`<button class="btn sm" onclick="RitimPremiumAPI.openJob(${jsArg(d.workOrderId)},${jsArg(selected)})">Tamir işini aç</button>`:''}${d.outcome==='approved'&&d.quantity>d.released?`<label class="formfield">Serbest bırakılacak adet<input class="input" type="number" id="rma-release-qty-${h(d.id)}"></label><label class="formfield">Yönetici gerekçesi<input class="input" id="rma-release-reason-${h(d.id)}"></label><button class="btn" ${capable('orders.write')?'':'disabled'} onclick="RitimPremiumAPI.rmaAction('rmaRelease',${jsArg(d.id)})">Onaylı iadeyi serbest bırak</button>`:''}${d.outcome==='rework'&&!d.workOrderId?`<label class="formfield">Tamir iş emri<input class="input" id="rma-work-${h(d.id)}"></label><button class="btn" onclick="RitimPremiumAPI.rmaAction('rmaRework',${jsArg(d.id)})">Tamir işi aç</button>`:''}`).join('')}</div>`).join('')}</div>`).join('')}</article>`).join('')}`:'<p>Teslimatlı sipariş yok.</p>'}</section>`}
 function shippingContentOriginal(){const v=shippingView,opts=shippingReady.map(o=>`<option value="${h(o.id)}" ${o.id===selected?'selected':''}>${h(o.orderNumber)} · ${h(o.customer)}</option>`).join(''),shippingOrders=logisticsRecord?.kind==='shipping'?v.shippingOrders.filter(x=>x.id===logisticsRecord.id):v.shippingOrders,active=shippingOrders.find(x=>x.id===shippingSelectedId)||shippingOrders[0],events=v.events.filter(x=>x.shippingOrderId===active?.id),sum=(type,field,id)=>events.filter(x=>x.type===type&&x[field]===id).reduce((n,x)=>n+x.quantity,0),allocations=events.filter(x=>x.type==='allocate').map(x=>({...x,remaining:x.quantity-sum('dispatch','allocationId',x.id)})).filter(x=>x.remaining>0),dispatches=events.filter(x=>x.type==='dispatch').map(x=>({...x,remaining:x.quantity-sum('deliver','dispatchId',x.id)})).filter(x=>x.remaining>0),w=capable('shipment.write')&&orders.find(o=>o.id===selected)?.status==='open',ready=v.lots.filter(x=>x.availableToShip>0);return `<section class="card pad flow-shipping"><div class="flow-heading"><div><h2>Sevkiyat</h2><p>Uygun ürünü ayırın, fiziksel çıkışı ve teslimatı ayrı doğrulayın.</p></div><button class="btn" onclick="RitimPremiumAPI.selectShippingOrder()">Yenile</button></div>${orderChoiceSearch()}<label class="formfield">Sipariş<select id="ship-order" class="select" onchange="RitimPremiumAPI.selectShippingOrder()">${opts}</select></label>${selected?`<div class="flow-metrics">${flowMetric('Sevke uygun',v.totals?.availableToShip??'—')}${flowMetric('Çıkış bekleyen',v.totals?.awaitingDispatch??'—')}${flowMetric('Yolda',v.totals?.inTransit??'—')}${flowMetric('Teslim edilen',v.totals?.delivered??'—')}</div><button class="btn ${active?'':'primary'}" ${w?'':'disabled'} onclick="RitimPremiumAPI.shippingAction('order')">${active?'Yeni sevkiyat hazırla':'Sevkiyat hazırla'}</button>${active?`<label class="formfield">Sevkiyat<select class="select" id="ship-shipping-order" onchange="RitimPremiumAPI.shippingSelect(this.value)">${shippingOrders.map((x,i)=>`<option value="${h(x.id)}" ${x.id===active.id?'selected':''}>Sevkiyat ${i+1} · ${h(displayStatus(x.status))}</option>`).join('')}</select></label><details class="shipping-operation" ${active.status==='delivered'?'':'open'}><summary>${active.status==='delivered'?'Teslimat tamamlandı · işlem ayrıntıları':'Sevkiyat işlemleri'}</summary><nav class="flow-filters" aria-label="Sevkiyat adımları">${[['allocate','1 · Ürünleri ayır'],['dispatch','2 · Çıkış yap'],['deliver','3 · Teslimatı doğrula']].map(([id,label])=>`<button class="btn" aria-pressed="${shippingTask===id}" onclick="RitimPremiumAPI.shippingTask(${jsArg(id)})">${label}</button>`).join('')}</nav><div class="flow-shipping-step"><h3>${shippingTask==='allocate'?'Sevke uygun ürünleri ayır':shippingTask==='dispatch'?'Hazırlanan ürünlerin çıkışını yap':'Fiziksel teslimatı doğrula'}</h3>${shippingTask==='allocate'?`<label class="formfield">Onaylı üretim lotu<select id="ship-lot" class="select">${ready.map((l,i)=>`<option value="${h(l.lotId)}">${h(l.lotCode||'Onaylı lot '+(i+1))} · ${l.availableToShip} adet</option>`).join('')}</select></label><details><summary>Serbest bırakılmış müşteri iadesinden sevk et</summary><select id="ship-return-release" class="select"><option value="">Normal onaylı üretim</option>${(v.returnedLots||[]).filter(l=>l.availableToShip>0).map((l,i)=>`<option value="${h(l.releaseId)}|${h(l.lotId)}">Onaylı iade ${i+1} · ${l.availableToShip} adet</option>`).join('')}</select></details>`:shippingTask==='dispatch'?`<label class="formfield">Hazırlanan ürün<select id="ship-allocation" class="select">${allocations.map((x,i)=>`<option value="${h(x.id)}">Hazırlık ${i+1} · Çıkış bekleyen ${x.remaining} adet</option>`).join('')}</select></label>`:`<label class="formfield">Yoldaki sevkiyat<select id="ship-dispatch" class="select">${dispatches.map((x,i)=>`<option value="${h(x.id)}">Çıkış ${i+1} · Teslim bekleyen ${x.remaining} adet</option>`).join('')}</select></label>`}<label class="formfield">İşlem adedi<input class="input" id="ship-quantity" type="number" min="1" step="1" inputmode="numeric" required></label><button class="btn primary" ${w?'':'disabled'} onclick="RitimPremiumAPI.shippingAction(${jsArg(shippingTask)})">${shippingTask==='allocate'?'Ürünleri sevkiyat için ayır':shippingTask==='dispatch'?'Fiziksel çıkışı kaydet':'Teslimatı kaydet'}</button></div></details>`:'<p>Başlamak için sevkiyat hazırlayın.</p>'}<details class="flow-details"><summary>Sevkiyat hareket geçmişi</summary>${v.events.map(x=>`<p>${h(({allocate:'Ürün ayrıldı',dispatch:'Çıkış yapıldı',deliver:'Teslim edildi'})[x.type])} · ${x.quantity} adet · ${h(x.createdAt||'')}</p>`).join('')||'<p>Hareket bulunmuyor.</p>'}</details>`:'<p>Henüz sevke uygun veya geçmiş sevkiyatı olan sipariş bulunmuyor.</p>'}${journal.list().filter(x=>x.kind==='shipping').map(x=>`<p>İşlem sonucu doğrulanmalı. <button class="btn" onclick="RitimPremiumAPI.retryShipping(${jsArg(x.id)})">Aynı işlemle tekrar dene</button></p>`).join('')}</section>`}
 async function loadLogisticsQueue(kind,after=null,query=logisticsQueue.kind===kind?logisticsQueue.query||'':''){if(!after)logisticsQueue={kind,query,items:[],nextAfter:null,error:''};try{const originScope=scope,result=await api.logisticsQueue(kind,after,query,logisticsStatus),items=result.items;for(let i=0;i<items.length;i+=6){const batch=items.slice(i,i+6);const details=await Promise.allSettled(batch.map(x=>kind==='shipping'?api.shippingRead(x.orderId):kind==='outsourcing'?api.outsourcingRead(x.orderId):api.rmaRead(x.orderId)));if(scope!==originScope)return;for(let k=0;k<batch.length;k++){const item=batch[k],detail=details[k];if(detail.status==='rejected'){item.summary='Durum sunucudan alınamadı';continue}const view=detail.value;if(kind==='shipping'){const x=view.shippingOrders?.find(y=>y.id===item.id);item.summary=x?`${displayStatus(x.status)} · Tahsis ${x.allocated} · Çıkış ${x.dispatched} · Teslim ${x.delivered}`:'Kayıt ayrıntısı alınamadı'}else if(kind==='returns'){const x=view.returns?.find(y=>y.id===item.id);item.summary=x?`Yetkili ${x.authorized} · Alınan ${x.received} · Beklenen ${x.outstanding}`:'Kayıt ayrıntısı alınamadı'}else{const x=view.jobs?.find(y=>y.id===item.id),dispatches=(view.dispatches||[]).filter(y=>y.jobId===item.id);item.summary=x?(dispatches.map(d=>`Gönderilen ${d.quantity} · Dönen ${d.returned} · Dışarıda ${d.outstanding}`).join(' / ')||'Henüz gönderim yok'):'Kayıt ayrıntısı alınamadı'}}}logisticsQueue={kind,query,items:after?logisticsQueue.items.concat(items):items,nextAfter:result.nextAfter,error:''}}catch(e){logisticsQueue={kind,items:[],nextAfter:null,error:'Kuyruk sunucudan alınamadı: '+e.message}}}
 function logisticsQueueContent(){if(logisticsQueue.kind!==page)return '';return `<details class="logistics-history" open><summary>${page==='returns'?'İade':page==='outsourcing'?'Fason':'Sevkiyat'} kuyruğu · ${logisticsQueue.items.length} kayıt</summary>${logisticsRecord?`<section class="card pad"><h2>Kayıt detayı · ${h(shortReference(logisticsRecord.id))}</h2><p>İşlemler seçili kayıt için gösterilir.</p><button class="btn" onclick="RitimPremiumAPI.clearLogisticsRecord()">Tüm kayıtlara dön</button></section>`:''}<section class="card pad"><h2>${page==='returns'?'İade kayıtları':page==='outsourcing'?'Fason kayıtları':'Sevkiyat kayıtları'}</h2><nav class="flow-filters" aria-label="Kayıt durumu"><button class="btn" aria-pressed="${logisticsStatus==='active'}" onclick="RitimPremiumAPI.logisticsState('active')">İşlem bekleyenler</button><button class="btn" aria-pressed="${logisticsStatus==='all'}" onclick="RitimPremiumAPI.logisticsState('all')">Tüm kayıtlar / geçmiş</button></nav><form class="workspace-logistics-search" onsubmit="event.preventDefault();RitimPremiumAPI.searchLogistics()"><label class="formfield">Kayıtlarda ara<input class="input" id="logistics-filter" maxlength="120" value="${h(logisticsQueue.query||'')}" oninput="RitimPremiumAPI.filterLogistics()"></label><button class="btn" type="submit">Tüm kayıtlarda ara</button><small>Yazarken yüklenen kayıtlar daralır. Arama düğmesi tüm sunucu kayıtlarını tarar.</small></form><p class="tiny">${logisticsQueue.items.length} kayıt yüklendi${logisticsQueue.nextAfter?' · Daha fazla kayıt var':''}.</p>${logisticsQueue.error?`<p role="alert">${h(logisticsQueue.error)}</p>`:logisticsQueue.items.map(x=>`<p data-logistics-search="${h((String(x.rmaNumber||x.id)+' '+x.orderNumber+' '+String(x.summary||'')).toLocaleLowerCase('tr-TR'))}"><button class="btn" onclick="RitimPremiumAPI.openLogisticsRecord(${jsArg(page)},${jsArg(x.orderId)},${jsArg(x.id)})">${h(x.rmaNumber||shortReference(x.id))} · ${h(x.orderNumber)}</button> · ${h(x.summary||'Durum bilinmiyor')}</p>`).join('')||'<p>Kayıt yok.</p>'}${logisticsQueue.nextAfter?'<button class="btn" onclick="RitimPremiumAPI.moreLogisticsRecords()">Sonraki kayıtlar</button>':''}</section></details>`}
 async function loadShippingChoices(){shippingReady=orders;if(!shippingReady.some(o=>o.id===selected))selected=shippingReady[0]?.id||null;shippingView=selected?await api.shippingRead(selected):{lots:[],events:[],shippingOrders:[]}}

 function orderChoiceSearch(){return `<form class="context-search" onsubmit="event.preventDefault();RitimPremiumAPI.searchOrderChoices()"><label class="formfield">Sipariş bul<input id="context-order-query" type="search" class="input" maxlength="120" value="${h(orderChoicesView.query||'')}" placeholder="Sipariş, müşteri veya parça"></label><button class="btn" type="submit">Ara</button>${orderChoicesView.nextAfter?'<button class="btn" type="button" onclick="RitimPremiumAPI.moreOrderChoices()">Daha fazla sipariş</button>':''}<small>${orderChoicesView.total} eşleşme · ${orders.length} seçenek</small></form>`}
 async function refreshOrderChoices(more=false){const query=el('context-order-query')?.value.trim()||orderChoicesView.query||'',result=await api.orderChoices({q:query,limit:30,include:selected||'',...(more&&orderChoicesView.nextAfter?{after:orderChoicesView.nextAfter}:{})});const items=more?orders.concat(result.items):result.items;orders=[...new Map(items.map(x=>[x.id,x])).values()];if(result.selected&&!orders.some(x=>x.id===result.selected.id))orders.unshift(result.selected);orderChoicesView={...result,query};shippingReady=orders}
 async function loadQualityPage(more=false){if(api.qualityQueue){const origin=scope,result=await api.qualityQueue({limit:20,q:qualityQuery,...more&&qualityCursor?{after:qualityCursor}:{}});if(scope!==origin)return;qualityQueue=more?[...new Map(qualityQueue.concat(result.items).map(x=>[x.output.eventId,x])).values()]:result.items;qualityQueueErrors=[];qualityCursor=result.nextAfter;qualityTotal=result.workOrderTotal;qualityOutputTotal=result.total;jobs=[...new Map(qualityQueue.map(x=>[x.job.id,x.job])).values()];operationsLimits.quality=more?operationsLimits.quality+20:20;return}const result=await api.jobWorklist({queue:'quality',status:'all',limit:25,...more&&qualityCursor?{after:qualityCursor}:{}});const rows=result.items.map(x=>({...x,workOrderNumber:x.number,plannedQuantity:x.quantity}));qualityCursor=result.nextAfter;qualityTotal=result.total;jobs=more?jobs.concat(rows):rows;await loadQualityQueue()}
 async function loadInventoryJobs(more=false){const result=await api.jobWorklist({queue:'material',q:inventoryJobsQuery,status:'active',limit:50,...(more&&inventoryJobsCursor?{after:inventoryJobsCursor}:{})});const rows=result.items.filter(x=>x.kind==='internal').map(x=>({...x,workOrderNumber:x.number,plannedQuantity:x.quantity}));inventoryJobsCursor=result.nextAfter;inventoryView.jobs=more?inventoryView.jobs.concat(rows):rows}
 async function reloadOrders(){const result=await api.orderChoices({include:selected||'',limit:30});orderChoicesView={...result,query:''};orders=result.items;if(result.selected&&!orders.some(x=>x.id===result.selected.id))orders=[result.selected,...orders];if(page==='orders'&&api.orderWorkspace)ordersWorkspace=await api.orderWorkspace(orderListFilters());resume=workflow?.read()||null}
 const routePages=new Set(['order-edit','batch-create','po-edit','production-monitor','machine-planning','production-supplier','production-orders','production-order','production-create','master','overview','orders','jobs','planning','operator','quality-list','rework','inventory','shipping','outsourcing','returns','compensations','detail','job','quality','trace']);
 function allowedPage(v){return routePages.has(v)&&((v!=='operator'||isOperator())&&(!['quality-list','rework','quality'].includes(v)||capable('quality.write'))&&(v!=='outsourcing'||capable('stock.write')||capable('quality.write')||capable('planning.write'))&&(v!=='returns'||capable('stock.write')||capable('quality.write')||capable('shipment.write')))}
 function routeUrl(v,orderId=null,jobId=null,recordId=null){const u=new URL(location.href);u.searchParams.set('view',v);u.searchParams.delete('order');u.searchParams.delete('job');u.searchParams.delete('lot');u.searchParams.delete('record');u.searchParams.delete('delivery');['category','q','status','machineId','operatorId','sort','direction','page','dueFrom','dueTo','allocation','source','state'].forEach(k=>u.searchParams.delete(k));if(recordId)u.searchParams.set('record',recordId);if(v==='trace'&&orderId){u.searchParams.set('lot',orderId);orderId=null}if(orderId)u.searchParams.set('order',orderId);if(jobId)u.searchParams.set('job',jobId);return u.pathname+u.search+u.hash}
 function setLogisticsRecord(kind,orderId,id){const view=kind==='shipping'?shippingView:kind==='outsourcing'?outsourcingView:rmaView;const records=kind==='shipping'?view?.shippingOrders:kind==='outsourcing'?view?.jobs:view?.returns;if(!records?.some(x=>x.id===id))throw Error('Kayıt bu siparişte bulunamadı veya erişiminiz yok.');logisticsRecord={kind,orderId,id}}
 async function loadPage(v,options={}){if(v!=='machine-planning'){boardTimeEdit=null;boardDrawer=null;boardBulk=null}preferenceNotice='';logisticsRecord=null;if(!allowedPage(v))throw Error('Bu ekrana erişim yetkiniz yok.');if(v==='trace'){const id=new URLSearchParams(location.search).get('lot');if(!id)throw Error('Lot bağlantısı eksik.');traceData=await api.traceLot(id);traceLotId=id;traceGraph=null;page=v;return}if(['detail','job','quality'].includes(v)){const p=new URLSearchParams(location.search),orderId=p.get('order'),id=p.get('job');if(!orderId||(v!=='detail'&&!id))throw Error('Kayıt bağlantısı eksik.');await loadDetail(orderId);if(v==='detail'){orderRecovery=await api.compensationOptions(orderId);orderClosing=await api.orderClosing(orderId)}if(v!=='detail'){if(!jobs.some(j=>j.id===id))throw Error('İş emri bu siparişte bulunamadı.');jobSelected=id;await loadJobViews(orderId,id)}page=v;return}page=v;if(v==='orders'&&api.orderWorkspace)ordersWorkspace=await api.orderWorkspace(orderListFilters(options.fresh));if(v==='order-edit'){editConflict=null;editModel=await api.orderEditing(new URLSearchParams(location.search).get('order'));editDraft={...editModel}}if(v==='batch-create')await prepareBatches(new URLSearchParams(location.search).get('order'));if(v==='po-edit'){poDetail=await api.productionOrder(new URLSearchParams(location.search).get('order'));poEditModel={...poDetail,operations:poDetail.route.map(op=>({name:op.name,kind:op.kind,setupMinutes:op.setup_minutes===null?null:Number(op.setup_minutes),cycleMinutes:op.cycle_minutes===null?null:Number(op.cycle_minutes)}))}}if(v==='production-monitor')monitorJobs=(await api.productionMonitor()).jobs;if(v==='overview')daily=await api.workCenter(workspaceFilters(v,options.fresh));if(v==='jobs'){worklistLayout=clarityRead().layout||viewPreferences.jobs?.settings?.layout||'list';worklist=await api.jobWorklist(workspaceFilters(v,options.fresh))}if(v==='machine-planning'){machineBoard=await readMachineBoard();boardUpdated=new Date();}if(v==='production-orders'){const orderId=!options.fresh&&new URLSearchParams(location.search).get('view')===v?new URLSearchParams(location.search).get('order'):null;const filter=!options.fresh&&new URLSearchParams(location.search).get('view')===v?(new URLSearchParams(location.search).get('productionStatus')||'active'):'active';poList={...(await api.productionOrders(orderId,null,filter)),orderId,filter}}if(v==='production-supplier'){const p=new URLSearchParams(location.search);poDetail=await api.productionOrder(p.get('order'));poSupplier=await api.productionSupplier(poDetail.id,p.get('job'))}if(v==='production-order'){poDetail=await api.productionOrder(new URLSearchParams(location.search).get('order'));poFlow=await api.productionOrderFlow(poDetail.id)}if(v==='production-create'){if(!capable('planning.write'))throw Error('Üretim emri oluşturma yetkisi gerekli.');await preparePo(new URLSearchParams(location.search).get('order'))}if(v==='compensations'){compensationFilters=compensationQuery(options.fresh);await loadCompensations()}if(v==='master')await loadMaster();if(v==='outsourcing'){monitorJobs=(await api.productionMonitor()).jobs;outsourcingSuppliers=[];outsourcingView=null;outsourcingOrder='';await reloadOrders();outsourcingSuppliers=(await api.outsourcingSuppliers()).suppliers}if(v==='returns'){rmaView=null;await reloadOrders();await loadShippingChoices();rmaView=selected?await api.rmaRead(selected):null}if(v==='inventory'){await loadInventory();const context=new URLSearchParams(location.search);if(!options.fresh&&context.get('view')==='inventory'&&context.get('order')&&context.get('job'))await p1InventoryContext(context.get('order'),context.get('job'))}if(v==='shipping'){shippingView={lots:[],events:[],shippingOrders:[]};shippingReady=[];await reloadOrders();await loadShippingChoices()}if(v==='operator'){assignedListOpen=true;await refreshAssigned()}if(v==='orders')await reloadOrders();if(v==='rework'){reworkOrderId=!options.fresh?new URLSearchParams(location.search).get('order'):null;repairQuery=options.fresh?'':new URLSearchParams(location.search).get('q')||'';reworkHistory=!options.fresh&&new URLSearchParams(location.search).get('state')==='all';await loadRework()}if(v==='quality-list'){qualityQuery=options.fresh?'':new URLSearchParams(location.search).get('q')||'';await loadQualityPage()}if(v==='planning'&&selected){jobSelected=null;await loadDetail(selected);await loadExtras()}if(['shipping','outsourcing','returns'].includes(v)){await loadLogisticsQueue(v);const routeParams=new URLSearchParams(location.search),orderId=routeParams.get('view')===v?routeParams.get('order'):null;if(orderId){await loadDetail(orderId);if(v==='outsourcing'){outsourcingOrder=orderId;outsourcingView=await api.outsourcingRead(orderId)}else if(v==='returns'){selected=orderId;rmaView=await api.rmaRead(orderId)}else{selected=orderId;shippingView=await api.shippingRead(orderId)}const recordId=routeParams.get('record');if(recordId)setLogisticsRecord(v,orderId,recordId);if(v==='returns')p1ReturnContext={orderId,deliveryId:routeParams.get('delivery')}}}}
 async function enterScope(context){scope=context.scope;caps=context.caps;journal=RitimServerPendingCommands.create({storage:sessionStorage,api,scope});await journal.load();viewPreferences=api.workspacePreferences?Object.fromEntries((await api.workspacePreferences()).views.map(x=>[x.view,x])):{};workflow=capable('orders.write')?RitimServerWizardWorkflow.create({journal,api,scope}):null;if(workflow)await workflow.load();await reloadOrders();const savedBoard=clarityRead().board;if(savedBoard){if(['queue','time'].includes(savedBoard.mode))boardMode=savedBoard.mode;if(['active','favorites','all'].includes(savedBoard.machines))guidedMachineMode=savedBoard.machines}const requested=new URLSearchParams(location.search).get('view')||clarityRead().lastView;if(requested){if(allowedPage(requested))await loadPage(requested);else error='Bu ekran için yetki yok veya bağlantı geçersiz.'}else if(capable('orders.write')&&api.orderWorkspace){await loadPage('orders')}else if(!capable('orders.write')){const landing=isOperator()?'operator':capable('quality.write')?'quality-list':capable('stock.write')?'inventory':capable('shipment.write')?'shipping':'overview';await loadPage(landing)}}
 async function loadDetail(id){detail=await api.order(id);if(!orders.some(x=>x.id===id))orders.unshift(detail);if(!shippingReady.some(x=>x.id===id))shippingReady.unshift(detail);orderEditingView=api.orderEditing?await api.orderEditing(id):null;orderSummary=api.orderSummary?await api.orderSummary(id):null;selected=id;jobs=(await api.workOrders(id)).workOrders;const op=detail.route.find(x=>x.sequence===0);avail=op?await api.availability(id,op.id):null}
 function poStatus(x){return ({unplanned:'İş emri bekliyor',planned:'İş emirleri oluşturuldu',held:'Beklemede',running:'Üretimde',completed:'Tamamlandı',waiting:'Başlamadı',paused:'Duraklatıldı',complete:'Tamamlandı'})[x]||x}
 function capturePo(){if(!poDraft)return;for(const key of ['number','quantity']){const e=el('po-'+key);if(e)poDraft[key]=key==='quantity'?Number(e.value):e.value}poDraft.operations.forEach((op,i)=>{op.name=el('po-name-'+i)?.value??op.name;op.kind=el('po-kind-'+i)?.value??op.kind;for(const [key,suffix]of [['setupMinutes','setup'],['cycleMinutes','cycle']]){const field=el('po-'+suffix+'-'+i);if(field)op[key]=field.value===''?null:Number(field.value)}})}
 async function preparePo(id,reset=false){await loadDetail(id);let result=await api.productionOrders(id),items=result.items;while(result.nextAfter){result=await api.productionOrders(id,result.nextAfter);items.push(...result.items)}const first=detail.route.find(x=>x.sequence===0),legacy=jobs.filter(x=>!x.productionOrderId&&x.operationId===first?.id).reduce((n,x)=>n+x.plannedQuantity,0),remaining=Math.max(0,detail.orderedQuantity-items.filter(x=>!x.compensationId).reduce((n,x)=>n+x.quantity,0)-legacy);if(reset||poDraft?.orderId!==id)poDraft={orderId:id,quantity:remaining,number:'',remaining,operations:detail.route.length?detail.route.map(x=>({name:x.name,kind:x.kind})):[{name:'İmalat',kind:'internal'}]};else poDraft.remaining=remaining;if(!poDraft.number)poDraft.number=await p1Number()}
 function poSupplierContentOriginal(){const v=poSupplier,p=poDetail;if(!v||!p)return '';const j=p.workOrders.find(x=>x.id===v.workOrderId);return `<section class="production-orders-page"><button class="btn" onclick="RitimPremiumAPI.poOpen(${jsArg(p.id)})">← Üretim emrine dön</button><section class="card pad"><h2>${h(j.name)} · Fason iş emri</h2><p>${h(j.number)} · ${j.quantity} adet · ${h(poStatus(v.status))}</p><div class="flow-metrics">${flowMetric('Gönderilen',v.dispatches.reduce((n,x)=>n+x.quantity,0))}${flowMetric('Dönen',v.dispatches.reduce((n,x)=>n+x.returned,0))}${flowMetric('Dışarıda',v.dispatches.reduce((n,x)=>n+x.outstanding,0))}${flowMetric('Kalite bekleyen',j.attention?.qualityPending||0)}</div><p class="order-hint">Gönderim yalnız fiziksel malzeme veya önceki operasyondan kalite onaylı çıktı üzerinden yapılır. Dönen ürünler kalite kararı bekler.</p>${v.status!=='complete'&&capable('stock.write')?`<form class="production-supplier-form" onsubmit="event.preventDefault();RitimPremiumAPI.poSupplierAction('dispatch')"><label class="formfield">Fason firması<select class="select" id="po-supplier" required><option value="">Firma seçin</option>${v.suppliers.map(x=>`<option value="${h(x.id)}">${h(x.name)} · ${h(x.code)}</option>`).join('')}</select></label><label class="formfield">Gönderilecek kaynak<select class="select" id="po-supplier-source" required><option value="">Kaynak seçin</option>${v.sources.map(x=>`<option value="${h(x.type+'|'+x.id)}">${h(x.label||shortReference(x.id))} · ${x.available} adet</option>`).join('')}</select></label><label class="formfield">Adet<input class="input" id="po-supplier-qty" type="number" min="1" step="1" required></label><label class="formfield">Beklenen dönüş tarihi <small>İsteğe bağlı</small><input class="input" id="po-supplier-due" type="date"></label><button class="btn primary" type="submit" ${p.planningState==='planned'?'':'disabled'}>Fasona gönder</button></form><p class="order-hint">${!v.sources.length?'Gönderilebilir kaynak yok. İlk operasyonsa Depo’dan malzeme teslim edin; sonraki adımlarda önceki operasyonun kalite onayını ve tamamlanmasını bekleyin.':''}</p><button class="btn sm" onclick="RitimPremiumAPI.navigate('inventory')">Malzeme ve Depo</button>`:''}</section><section class="card pad"><h3>Gönderimler ve dönüşler</h3>${v.dispatches.map(d=>`<article class="production-supplier-dispatch"><p>${h(v.suppliers.find(x=>x.id===d.supplierId)?.name||'Fason firması')} · Gönderilen ${d.quantity} · Dönen ${d.returned} · Dışarıda ${d.outstanding}</p>${d.outstanding&&capable('stock.write')?`<form onsubmit="event.preventDefault();RitimPremiumAPI.poSupplierAction('return',${jsArg(d.id)})"><label class="formfield">Dönen adet<input class="input" type="number" min="1" max="${d.outstanding}" id="po-return-${h(d.id)}" required></label><button class="btn" type="submit">Fiziksel dönüşü kaydet</button></form>`:''}</article>`).join('')||'<p>Henüz gönderim yok.</p>'}${capable('quality.write')?`<button class="btn" onclick="RitimPremiumAPI.openQualityJob(${jsArg(j.id)},${jsArg(p.orderId)})">Dönen ürünlerin kalite kontrolü</button>${v.status!=='complete'?'<button class="btn primary" onclick="RitimPremiumAPI.poSupplierAction(\'complete\')">Fason operasyonunu tamamla</button>':''}`:''}</section></section>`}

 function poFlowContent(){if(!poFlow)return '';const p=poDetail;if(!poFlow.outputs.length&&!poFlow.dispatches.length)return '<section class="card pad"><h3>Operasyonlar arası akış</h3><p>Kalite onaylı çıktılar oluştukça sonraki iç operasyona ayırma, gönderme ve kabul işlemleri burada görünür.</p></section>';return `<section class="card pad p1-flow-workspace"><h3>Operasyonlar arası akış</h3>${poFlow.truncated?'<p role="alert">İlk 1000 çıktı gösteriliyor.</p>':''}${poFlow.outputs.map(l=>`<article class="production-supplier-dispatch"><h4>${h(l.sourceName)} → ${h(l.destinationName)}</h4><p>Onaylı ve kullanılabilir: ${l.availableApproved} adet</p>${l.availableApproved&&capable('planning.write')?`<form onsubmit="event.preventDefault();RitimPremiumAPI.poFlowAction('reserve',${jsArg(l.lotId)},${jsArg(l.destinationWorkOrderId)})"><label class="formfield">Ayrılacak adet<input class="input" type="number" min="1" max="${l.availableApproved}" id="po-reserve-${h(l.lotId)}" required></label><button class="btn" type="submit">Sonraki iş emrine ayır</button></form>`:''}${l.reservations.map(r=>`<p>Ayrılmış ${r.outstanding} · Gönderilmiş ${r.dispatched} · Kabul edilmiş ${r.received}</p>${r.outstanding>r.dispatched&&capable('stock.write')?`<form onsubmit="event.preventDefault();RitimPremiumAPI.poFlowAction('dispatch',${jsArg(r.id)})"><label class="formfield">Gönderilecek adet<input class="input" type="number" min="1" max="${r.outstanding-r.dispatched}" id="po-dispatch-${h(r.id)}" required></label><button class="btn" type="submit">Fiziksel gönderimi kaydet</button></form>`:''}`).join('')}</article>`).join('')}${poFlow.dispatches.filter(d=>d.inTransit>0).map(d=>`<article class="production-supplier-dispatch"><p>Yolda: ${d.inTransit} adet</p>${capable('stock.write')?`<form onsubmit="event.preventDefault();RitimPremiumAPI.poFlowAction('receive',${jsArg(d.id)})"><label class="formfield">Kabul edilecek adet<input class="input" id="po-receive-${h(d.id)}" type="number" min="1" max="${d.inTransit}" required></label><button class="btn" type="submit">Hedef operasyonda kabul et</button></form>`:''}</article>`).join('')}</section>`}

 function poContent(){
 if(page==='production-orders')return `<section class="production-orders-page"><h2>Üretim emirleri</h2><p>Sipariş → Üretim emri → Operasyon iş emirleri</p><div class="filterbar" aria-label="Üretim emri durumu">${[['active','Açık emirler'],['all','Tümü'],['unplanned','İş emri bekliyor'],['planned','İş emirleri oluşturuldu'],['running','Üretimde'],['waiting','Operasyon bekliyor'],['paused','Duraklatıldı'],['held','Beklemede'],['completed','Tamamlandı']].map(([key,name])=>`<button class="filter-chip ${poList.filter===key?'active':''}" aria-pressed="${poList.filter===key}" onclick="RitimPremiumAPI.poFilter('${key}')">${name}</button>`).join('')}</div><div class="list">${poList.items.map(x=>`<button class="list-card" onclick="RitimPremiumAPI.poOpen(${jsArg(x.id)})"><div class="list-top"><b>${h(x.number)}</b><span class="pill" data-state="${h(x.status)}">${h(poStatus(x.status))}</span></div><h3>${h(x.partName||x.orderNumber)}</h3><p>${h(x.orderNumber)} · ${h(x.customer)}</p><div class="list-bottom"><span>${x.quantity} adet · ${x.workOrders.length} iş emri</span><span>${h(x.plannedDate||'Henüz planlanmadı')}</span></div>${x.holdReason?`<p>${h(x.holdReason)}</p>`:''}</button>`).join('')||'<div class="card pad">Üretim emri bulunamadı. Sipariş detayından oluşturabilirsiniz.</div>'}</div>${poList.nextAfter?'<button class="btn" onclick="RitimPremiumAPI.poMore()">Daha fazla göster</button>':''}</section>`;
 if(page==='production-supplier')return poSupplierContent();
 if(page==='production-create'){const d=poDraft;if(!d)return '';return `<section class="card pad production-create"><button class="btn sm" onclick="RitimPremiumAPI.openOrder(${jsArg(d.orderId)})">← Siparişe dön</button><h2>Üretim Emri Oluştur</h2><p>${h(detail.orderNumber)} · ${h(detail.partName)}</p><form onsubmit="event.preventDefault();RitimPremiumAPI.poSave()"><div class="formgrid"><label class="formfield">Üretilecek adet<input class="input" id="po-quantity" type="number" min="1" max="${d.remaining}" step="1" required value="${d.quantity}"><small>Üretime ayrılabilecek: ${d.remaining} adet</small></label><label class="formfield">Üretim emri numarası<input class="input" id="po-number" maxlength="100" placeholder="Kaydedildiğinde oluşturulur" value="${h(d.number)}"><small>Sistem oluşturur · düzenlenebilir</small></label></div><h3>Operasyon rotası</h3><div class="template-actions"><button class="btn sm" type="button" onclick="RitimPremiumAPI.openTemplates('po')">Şablondan rota seç</button>${capable('planning.write')?'<button class="btn sm" type="button" onclick="RitimPremiumAPI.openTemplates(\'po\',true)">Rotayı şablon olarak kaydet</button>':''}</div><p class="order-hint">İç ve fason adımları istediğiniz sırada ekleyin. Operasyon adları tekrarlanabilir.</p><div class="production-route">${d.operations.map((op,i)=>`<article class="production-route-row"><span class="op-number">${i+1}</span><label class="formfield">Operasyon adı<input class="input" id="po-name-${i}" required maxlength="120" value="${h(op.name)}" placeholder="Örn. Torna veya Isıl işlem"></label><label class="formfield">Tür<select class="select" id="po-kind-${i}"><option value="internal" ${op.kind==='internal'?'selected':''}>İç operasyon</option><option value="external" ${op.kind==='external'?'selected':''}>Fason</option></select></label><div class="production-route-actions"><button class="btn sm" type="button" aria-label="${i+1}. operasyonu yukarı taşı" onclick="RitimPremiumAPI.poMove(${i},-1)" ${i?'':'disabled'}>↑</button><button class="btn sm" type="button" aria-label="${i+1}. operasyonu aşağı taşı" onclick="RitimPremiumAPI.poMove(${i},1)" ${i===d.operations.length-1?'disabled':''}>↓</button><button class="btn sm" type="button" aria-label="${i+1}. operasyonu sil" onclick="RitimPremiumAPI.poRemove(${i})" ${d.operations.length===1?'disabled':''}>×</button></div><details class="po-operation-timing"><summary>Tahmini süreler · isteğe bağlı</summary><div class="formgrid"><label class="formfield">Hazırlık · dakika<input class="input" id="po-setup-${i}" type="number" min="0" max="10080" step="0.001" value="${op.setupMinutes??''}"></label><label class="formfield">Adet başı · dakika<input class="input" id="po-cycle-${i}" type="number" min="0" max="10080" step="0.001" value="${op.cycleMinutes??''}"></label></div></details></article>`).join('')}</div><button class="btn" type="button" onclick="RitimPremiumAPI.poAdd()">＋ Operasyon ekle</button><p class="order-hint">İş emirleri üretim emrini planladığınızda oluşur. Makine ve operatör daha sonra atanabilir.</p><div class="production-create-footer"><span>Başlangıç: <b>Planlama Bekliyor</b></span><button class="btn primary" type="submit" ${d.remaining?'':'disabled'}>Üretim Emrini Oluştur</button></div></form></section>`}
 return productionDetailContent();
 }

 function masterPicker(key,label,placeholder){return `<div class="formfield master-picker"><label for="order-${key}">${label}</label><input class="input" id="order-${key}" data-wiz="${key}" value="${h(wizard[key])}" placeholder="${placeholder}" role="combobox" aria-autocomplete="list" aria-expanded="false" aria-controls="order-${key}-results" aria-describedby="order-${key}-status" autocomplete="off" required><div class="master-picker-results" id="order-${key}-results" role="listbox" aria-label="${label}" hidden></div><span class="master-picker-status" id="order-${key}-status" role="status">${wizard[key+'Id']?'Kayıt seçildi':'Ad veya kod yazarak seçin.'}</span>${capable('master.write')?`<button type="button" class="master-quick-add" onclick="RitimPremiumAPI.quickMaster('${key}','wizard')">+ Yeni ${key==='customer'?'müşteri':'parça'} ekle</button>`:''}</div>`}
 function bindMasterPickers(){for(const key of ['customer','part']){const input=el('order-'+key),list=el('order-'+key+'-results'),status=el('order-'+key+'-status');if(!input||input.disabled)continue;let timer,revision=0,items=[],active=-1;const originScope=scope,originWizard=wizard;const close=()=>{list.hidden=true;input.setAttribute('aria-expanded','false');input.removeAttribute('aria-activedescendant');active=-1};const choose=index=>{const item=items[index];if(!item)return;input.value=item.name;wizard[key]=item.name;wizard[key+'Id']=item.id;if(key==='part'){wizard.partNo=item.code||'';const code=document.querySelector('[data-wiz="partNo"]');if(code)code.value=wizard.partNo}revision++;clearTimeout(timer);status.textContent='Kayıt seçildi'+(item.code?' · '+item.code:'');close()};const search=async()=>{const request=++revision,q=input.value.trim();status.textContent='Aranıyor…';try{const result=await api.masterSearch(key==='customer'?'customers':'parts',q);if(request!==revision||scope!==originScope||wizard!==originWizard||!input.isConnected)return;items=result.items;active=-1;list.innerHTML=items.map((x,i)=>`<div role="option" aria-selected="false" id="order-${key}-option-${i}" data-option="${i}"><b>${h(x.name)}</b><small>${h(x.code||'Kod belirtilmedi')}</small></div>`).join('')||'<div class="master-picker-empty">Kayıt bulunamadı. Ana Veriler bölümünden ekleyebilirsiniz.</div>';list.hidden=false;input.setAttribute('aria-expanded','true');status.textContent=items.length?`${items.length} sonuç${result.nextAfter?' · Daha fazla sonuç için aramayı daraltın.':''}`:'Eşleşen kayıt yok.'}catch(e){if(request!==revision||!input.isConnected||scope!==originScope)return;close();status.textContent='Kayıtlar alınamadı. Yeniden arayın.'}};input.addEventListener('input',()=>{wizard[key+'Id']=null;wizard[key]=input.value;if(key==='part'){wizard.partNo='';const code=document.querySelector('[data-wiz="partNo"]');if(code)code.value=''}revision++;close();status.textContent='Listeden bir kayıt seçin.';clearTimeout(timer);timer=setTimeout(search,220)});input.addEventListener('focus',()=>{clearTimeout(timer);timer=setTimeout(search,0)});input.addEventListener('blur',()=>{revision++;clearTimeout(timer);close()});list.addEventListener('pointerdown',e=>e.preventDefault());list.addEventListener('click',e=>{const option=e.target.closest('[data-option]');if(option)choose(Number(option.dataset.option))});input.addEventListener('keydown',e=>{if(e.key==='Escape'&&!list.hidden){e.preventDefault();e.stopPropagation();close();return}if(e.key==='Enter'&&!list.hidden&&active>=0){e.preventDefault();choose(active);return}if(!['ArrowDown','ArrowUp'].includes(e.key)||list.hidden||!items.length)return;e.preventDefault();active=(active+(e.key==='ArrowDown'?1:-1)+items.length)%items.length;[...list.querySelectorAll('[role=option]')].forEach((x,i)=>x.setAttribute('aria-selected',String(i===active)));input.setAttribute('aria-activedescendant',`order-${key}-option-${active}`);el(`order-${key}-option-${active}`).scrollIntoView({block:'nearest'})})}}
 async function loadMaster(){const version=++masterSearchRevision,originScope=scope;const result=await api.masterPage(masterView.kind,{q:masterView.q,page:masterView.page||1,size:masterView.size||20,sort:masterView.sort||'name',direction:masterView.direction||'asc'});if(version!==masterSearchRevision||scope!==originScope)return false;Object.assign(masterView,result,{nextAfter:null});return true}
 function masterPaging(){const v=masterView;return `<div class="master-paging"><span>${v.total||0} kayıt · Sayfa ${v.page||1} / ${v.pages||1}</span><button class="btn" onclick="RitimPremiumAPI.masterPage(-1)" ${(v.page||1)<=1?'disabled':''}>Önceki</button><button class="btn" onclick="RitimPremiumAPI.masterPage(1)" ${(v.page||1)>=(v.pages||1)?'disabled':''}>Sonraki</button></div>`}

 function masterRows(){return masterView.items.map(x=>`<article class="master-record"><div class="master-identity"><b>${h(x.name)}</b><small>${h(x.code||'—')}</small></div>${capable('master.write')||capable('orders.write')?`<div class="master-record-actions">${capable('orders.write')&&masterView.kind!=='scrap-reasons'?`<button class="btn sm" onclick="RitimPremiumAPI.newOrderFromMaster(${jsArg(x.id)})">Yeni sipariş</button>`:''}${capable('master.write')?`<button class="btn sm" onclick="RitimPremiumAPI.editMaster(${jsArg(x.id)})">Düzenle</button><details><summary aria-label="Diğer kayıt işlemleri">Diğer</summary><button class="btn sm" onclick="RitimPremiumAPI.deleteMaster(${jsArg(x.id)})">Pasifleştir</button></details>`:''}</div>`:''}</article>`).join('')||'<div class="master-empty"><b>Kayıt bulunamadı</b><p>Aramayı değiştirin veya ilk ana kaydınızı ekleyin.</p></div>'}

 function masterContentOriginal(){const v=masterView,customer=v.kind==='customers';return `<section class="master-page"><div class="order-intro"><h2>Ana kayıtlarınız</h2></div><nav class="master-tabs" aria-label="Ana veri türü">${[['customers','Müşteriler'],['parts','Parçalar / Ürünler'],['scrap-reasons','Hurda nedenleri']].map(([kind,label])=>`<button class="btn ${v.kind===kind?'primary':''}" aria-pressed="${v.kind===kind}" onclick="RitimPremiumAPI.masterTab('${kind}')">${label}</button>`).join('')}</nav>${capable('master.write')?`<button class="btn primary master-create" onclick="RitimPremiumAPI.newMaster()">+ ${customer?'Yeni müşteri ekle':v.kind==='scrap-reasons'?'Yeni hurda nedeni':'Yeni parça ekle'}</button>`:''}<p class="master-notice" role="status">${h(v.notice)}</p><div class="card master-list"><label class="formfield" for="master-search">${customer?'Müşteri ara':v.kind==='scrap-reasons'?'Hurda nedeni ara':'Parça ara'}</label><input class="input" type="search" id="master-search" maxlength="120" placeholder="Ad veya kod ile arayın" value="${h(v.q)}"><div class="master-sortbar"><button class="btn" onclick="RitimPremiumAPI.masterSort('name')">Ad ${v.sort==='name'?(v.direction==='desc'?'↓':'↑'):''}</button><button class="btn" onclick="RitimPremiumAPI.masterSort('code')">Kod ${v.sort==='code'?(v.direction==='desc'?'↓':'↑'):''}</button><button class="btn" onclick="RitimPremiumAPI.masterSort('created_at')">Kayıt tarihi</button><label>Sayfa boyutu <select class="select" onchange="RitimPremiumAPI.masterSize(this.value)">${[10,20,50].map(n=>`<option value="${n}" ${(v.size||20)===n?'selected':''}>${n}</option>`).join('')}</select></label></div><div id="master-records">${masterRows()}</div><div id="master-pagination">${masterPaging()}</div></div><details class="card pad flow-details"><summary>Çalışma ayarları</summary><h3>Rota şablonları</h3><p>Tekrarlanan iç ve fason operasyonları bir kez tanımlayın, yeni üretim rotalarına kopyalayın.</p><button class="btn" onclick="RitimPremiumAPI.openTemplates('master')">Rota şablonlarını yönet</button><p>Makine ve takvim ayarlarını planlamada, malzeme ve konumları depoda düzenleyebilirsiniz.</p><button class="btn" onclick="RitimPremiumAPI.navigate('machine-planning')">Makineler ve çalışma takvimi</button><button class="btn" onclick="RitimPremiumAPI.navigate('inventory')">Malzemeler ve depo konumları</button></details><p class="order-hint">Pasifleştirilen kayıtlar yeni siparişlerde listelenmez. Önceki siparişler korunur.</p></section>`}

 function masterContent(){const t=operationsTemplate(masterContentOriginal()),root=t.content.firstElementChild,list=root.querySelector('.master-list'),search=root.querySelector('#master-search'),create=root.querySelector('.master-create'),toolbar=document.createElement('div');toolbar.className='master-toolbar';search.before(toolbar);toolbar.append(search);if(create)toolbar.append(create);const sort=root.querySelector('.master-sortbar');sort.classList.add('master-columns');sort.children[2].setAttribute('aria-label','Kayıt tarihine göre sırala');return t.innerHTML}
 function bindMasterSearch(){const input=el('master-search');if(!input)return;let timer;input.addEventListener('input',()=>{masterSearchRevision++;masterView.q=input.value;masterView.page=1;clearTimeout(timer);timer=setTimeout(async()=>{const originScope=scope,kind=masterView.kind,q=masterView.q;try{const applied=await loadMaster();if(!applied||scope!==originScope||masterView.kind!==kind||el('master-search')?.value!==q)return;el('master-records').innerHTML=masterRows();el('master-pagination').innerHTML=masterPaging()}catch(e){if(input.isConnected)el('api-alert').textContent='Ana veriler alınamadı. Tekrar arayın.'}},220)})}

 function simpleWizardContent(){
 const w=wizard,field=(key,label,type='text',extra='')=>`<label class="formfield"><span>${label}</span><input class="input" data-wiz="${key}" type="${type}" value="${h(w[key])}" ${extra}></label>`;
 const progress=`<ol class="order-steps" aria-label="Sipariş oluşturma adımları" style="grid-template-columns:repeat(${w.step===2?3:2},minmax(0,1fr))">${(w.step===2?[1,2,3]:[1,3]).map((step,i)=>`<li class="${step===w.step?'current':step<w.step?'done':''}" ${step===w.step?'aria-current="step"':''}><span>${step<w.step?'✓':i+1}</span><b>${step===1?'Sipariş bilgileri':step===2?'Operasyon rotası':'Son kontrol'}</b></li>`).join('')}</ol>`;
 const intro=(title,description)=>`<div class="order-intro"><h3>${title}</h3><p>${description}</p></div>`;
 if(w.step===1){return progress+intro('Yeni bir siparişle başlayın','Dört temel bilgi yeterli. Diğer ayrıntıları ihtiyaç duyduğunuzda ekleyebilirsiniz.')+`<div class="order-section"><div class="formgrid">${masterPicker('customer','Müşteri / Firma','Müşteri adı veya kodu yazın')}${masterPicker('part','Parça / Ürün','Parça adı veya kodu yazın')}${field('qty','Sipariş Adedi','number','min="1" step="1" inputmode="numeric" required')}${field('due','İstenen Teslim Tarihi','date','required')}</div></div><details class="order-advanced"><summary><span>İsteğe bağlı ayrıntılar <small>Operasyon rotası ve ek bilgiler</small></span><span aria-hidden="true">＋</span></summary><button type="button" class="btn" onclick="wizardNext(2)">İsteğe bağlı operasyon rotası tanımla</button><p class="order-hint">Rotayı şimdi tanımlayabilir veya üretime ayırırken ekleyebilirsiniz.</p><div class="formgrid">${field('id','Sipariş Numarası')}${field('partNo','Parça Numarası','text','readonly aria-describedby="part-code-help"')}<p class="order-hint" id="part-code-help">Parça kodu seçtiğiniz ana kayıttan gelir.</p></div></details>`}
 if(w.step===2){const ops=w.templateOperations||[];return progress+intro('İsteğe bağlı operasyon rotası','Bu rota üretim emirlerine başlangıç olarak kopyalanır. Fason operasyonları istediğiniz sırada ekleyebilirsiniz.')+'<div class="order-route-list">'+ops.map((op,i)=>'<div class="route-row"><span class="op-number">'+(i+1)+'</span><input class="input" aria-label="Operasyon adı '+(i+1)+'" value="'+h(op.name)+'" onchange="RitimPremiumAPI.templateEdit('+i+',\'name\',this.value)"><select class="select" aria-label="Operasyon türü '+(i+1)+'" onchange="RitimPremiumAPI.templateEdit('+i+',\'kind\',this.value)"><option value="internal" '+(op.kind==='internal'?'selected':'')+'>İç operasyon</option><option value="external" '+(op.kind==='external'?'selected':'')+'>Fason</option></select><button class="btn sm" onclick="RitimPremiumAPI.templateRemove('+i+')">Sil</button></div>').join('')+'</div><button class="btn" onclick="RitimPremiumAPI.templateAdd()">Operasyon ekle</button><button class="btn" onclick="RitimPremiumAPI.templateDefer()">Rotayı daha sonra belirle</button>'}
 const date=w.due?new Intl.DateTimeFormat('tr-TR',{day:'numeric',month:'long',year:'numeric'}).format(new Date(w.due+'T12:00:00')):'—';
 return progress+intro('Her şey hazır mı?','Bilgileri kontrol edin. Siparişi kaydettikten sonra planlamaya geçebilirsiniz.')+`<section class="order-review"><div class="order-review-head"><span>SİPARİŞ ÖZETİ</span>${!resume?'<button class="order-edit" onclick="wizardNext(1)">Bilgileri düzenle</button>':''}</div><h3>${h(w.part)}</h3><p>${h(w.customer)}</p><dl><div><dt>Sipariş adedi</dt><dd>${h(Number(w.qty).toLocaleString('tr-TR'))} <small>adet</small></dd></div><div><dt>Teslim tarihi</dt><dd>${h(date)}</dd></div><div><dt>Sipariş numarası</dt><dd class="order-reference">${h(w.id)}</dd></div>${w.partNo?`<div><dt>Parça numarası</dt><dd class="order-reference">${h(w.partNo)}</dd></div>`:''}</dl><div class="order-review-route"><div><b>Operasyon rotası</b><p>${w.templateOperations?.length?w.templateOperations.map(x=>h(x.name)+(x.kind==='external'?' (Fason)':'')).join(' → '):w.route.length?w.route.map(h).join(' → '):'Üretim emri oluşturulurken tanımlanacak'}</p></div>${!resume&&w.route.length?'<button class="order-edit" onclick="wizardNext(2)">Düzenle</button>':''}</div></section><p class="order-hint">Sipariş kaydedilir. Üretilecek miktarı ve rotayı daha sonra Üretim Emri Oluştur adımında belirleyebilirsiniz.</p>`;
 }
 function displayWizard(){const w=wizard;const stage=resume?.steps;const status=stage?`<div class="ux6-alert">${stage.order==='committed'&&['committed','skipped'].includes(stage.route)?'<b>Sipariş başarıyla oluşturuldu.</b><br>':''}Sipariş: ${h(stageLabel(stage.order))} · Rota: ${h(stageLabel(stage.route))} · İş emri: ${h(stageLabel(stage.plan))}<p>Bu adımlar ayrı sunucu işlemleridir.</p></div>`:'';const locked=!!resume&&!correcting;const failed=stage&&['order','route','plan'].find(x=>stage[x]==='failed');const body=resume?.plan&&typeof legacyWizardContent==='function'?legacyWizardContent():wizardContent();const label=w.step===3?(stage?'Sonraki sunucu adımı':'Siparişi Kaydet'):'Devam Et →';el('overlay').innerHTML=`<div class="modal-back wizard-back"><div class="modal wizard-modal order-compose" role="dialog" aria-modal="true" aria-labelledby="order-compose-title"><div class="modal-head"><h2 id="order-compose-title">${h(['','1 / 2 · Sipariş Bilgileri','2 / 3 · Operasyon Rotası','2 / 2 · Siparişi Gözden Geçir'][w.step])}</h2><button class="btn sm" onclick="closeModal()" aria-label="Kapat">×</button></div><div class="modal-body">${status}${body}${''}${error?`<p class="ux6-alert" role="alert">${h(error)}</p>`:''}</div><div class="modal-foot"><button class="btn" onclick="${w.step===1||locked?'closeModal()':`wizardNext(${w.step===3&&!w.route.length?1:w.step-1})`}">${w.step===1||locked?'Kapat':'← Geri'}</button>${correcting?'<button class="btn primary" onclick="RitimPremiumAPI.saveCorrection()">Düzeltmeyi Kaydet</button>':stage&&stage.order==='committed'&&['committed','skipped'].includes(stage.route)&&['committed','skipped'].includes(stage.plan)?'<button class="btn" onclick="RitimPremiumAPI.finish(true)">Üretim Emri Oluştur</button><button class="btn primary" onclick="RitimPremiumAPI.finish()">Siparişe Git</button>':`<button class="btn primary" onclick="${w.step===3?'RitimPremiumAPI.submitWizard()':`wizardNext(${w.step===1?3:w.step+1})`}" ${busy?'disabled':''}>${h(label)}</button>`}${failed&&!correcting?'<button class="btn" onclick="RitimPremiumAPI.correct()">Başarısız adımı düzelt</button>':''}</div></div></div>`;if(locked)el('overlay').querySelectorAll('[data-wiz],.route-row button,#newRoute').forEach(x=>x.disabled=true);const machine=el('overlay').querySelector('[data-wiz="machine"]');if(machine)machine.disabled=true;for(const key of ['revision','created','material','dimensions']){const field=el('overlay').querySelector(`[data-wiz="${key}"]`);if(field){field.disabled=true;field.closest('.formfield').hidden=true}}const routeSelect=el('newRoute');if(routeSelect)for(const option of [...routeSelect.options])if(!['İmalat','Tesviye','Kaplama'].includes(option.value))option.remove();syncWizardViewport();bindMasterPickers()}
 async function initializeAuth(){authLoading=true;draw();try{authProvider=RitimAuthProvider.createBff();const config=await authProvider.config();devToken=requestedDevToken&&config.manualTokenAllowed===true;if(devToken)return;if(!config.enabled)throw Error('OIDC oturumu bu ortamda yapılandırılmamış.');api=RitimApiAdapter.create({cookieSession:true,refreshEnabled:config.refreshEnabled===true,onUnauthorized:()=>{const hadSession=!!session;clearIdentity();error=hadSession?'Oturum sona erdi; yeniden giriş yapın.':''},onScopeDenied:()=>{clearSite();error='İş yeri yetkisi değişti; erişimi yeniden doğrulayın.'}});session=await api.session()}catch(e){clearIdentity();if(e.status!==401)error=e.message}finally{authLoading=false;draw()}}
 window.addEventListener('popstate',()=>{if(!scope)return;const requested=new URLSearchParams(location.search).get('view')||'orders';if(allowedPage(requested)){saveNavigationDraft();restoreNavigationDraft=true;run(async()=>{await loadPage(requested);if(requested==='orders')requestAnimationFrame(()=>scrollTo(0,ordersScroll))})}else{page='orders';error='Bu ekran için yetki yok veya bağlantı geçersiz.';draw()}});

 function machineBoardContent(){return compactMachineBoardContent()}



 function orderRecoveryPanel(){if(!orderRecovery||!orderClosing||orderClosing.orderId!==detail?.id)return '';return `<details class="card pad" id="order-recovery-panel"><summary>Telafi ve sipariş kapatma</summary><h3>Belgelenmiş kayıplar</h3><p>Kaybın tamamı veya bir bölümü için gerekçeli telafi izni oluşturun. Ardından ayrı üretim emriyle planlayın.</p>${orderRecovery.losses.filter(x=>x.available>0).map(x=>`<article class="card pad"><h4>${h(x.label)} · ${x.available} adet kullanılabilir</h4>${capable('quality.write')?`<form class="formgrid" onsubmit="event.preventDefault();RitimPremiumAPI.approveCompensation(${jsArg(x.id)},${jsArg(x.kind)})"><label class="formfield">Telafi adedi<input class="input" type="number" min="1" max="${x.available}" required id="comp-qty-${x.id}" value="${x.available}"></label><label class="formfield">Telafi gerekçesi<input class="input" maxlength="120" required id="comp-reason-${x.id}" placeholder="Kaybın nedenini açıklayın"></label><button class="btn" type="submit">Telafi izni oluştur</button></form>`:''}</article>`).join('')||'<p>Telafiye ayrılabilecek açık kayıp yok.</p>'}${orderRecovery.approvals.map(x=>`<p>Telafi: ${x.quantity} adet · ${h(x.reason)} · Planlanabilir ${x.available}${x.available>0&&capable('planning.write')?`<button class="btn sm" onclick="RitimPremiumAPI.compensationProduction(${jsArg(x.id)},${x.available})">Telafi üretim emri</button>`:''}</p>`).join('')}<h3>Siparişi kapat</h3><p>Net teslimat ${orderClosing.netDelivered} / ${orderClosing.orderedQuantity}</p>${orderClosing.reasons.map(x=>`<p class="closing-reason"><span>• ${h(x)}</span><button class="btn sm" onclick="RitimPremiumAPI.openClosingBlocker(${jsArg(x.includes('sevkiyat')||x.includes('teslimat')?'shipping':x.includes('iade')||x.includes('karantina')?'returns':x.includes('telafi')?'compensations':'production-orders')})">İlgili kayıtları aç</button></p>`).join('')}${capable('orders.write')&&orderClosing.status==='open'?`<button class="btn primary" onclick="RitimPremiumAPI.closeOrder()" ${orderClosing.canClose?'':'disabled'}>Siparişi kapat</button>`:''}</details>`}

 function flowMetric(label,value,detail=''){return `<div class="flow-metric"><span>${h(label)}</span><strong>${h(value)}</strong>${detail?`<small>${h(detail)}</small>`:''}</div>`}
 function nextActionAllowed(target){const permission={'production-create':'planning.write','quality-list':'quality.write',rework:'quality.write',shipping:'shipment.write',inventory:'stock.write',closing:'orders.write'}[target];return !permission||capable(permission)}
 function orderSummaryContentOriginal(){const v=orderSummary;if(!v||v.orderId!==detail?.id)return '<section class="card pad"><p>Sipariş özeti alınamadı. Sayfayı yenileyin.</p></section>';const closed=v.status==='closed',inactive=v.status!=='open',canAct=nextActionAllowed(v.next.target);return `<section class="card pad flow-order-summary"><div class="flow-heading"><div><span class="flow-eyebrow">SİPARİŞ ÖZETİ</span><h2>${h(detail.orderNumber)} · ${h(detail.partName)}</h2><p>${h(detail.customer)} · Termin ${h(detail.dueDate||'Belirlenmedi')}</p></div><span class="pill ${closed?'flow-complete':''}">${closed?'Kapalı':inactive?'İptal edildi':'Açık'}</span></div><div class="flow-metrics">${flowMetric('Sipariş',v.orderedQuantity,'adet')}${flowMetric('Üretime ayrılmamış',v.unallocatedQuantity,'Normal sipariş miktarı')}${flowMetric('Telafi üretimi',v.compensationQuantity,'Sipariş miktarına eklenmez')}${flowMetric('Sevke uygun',v.shipping.availableToShip,'Kalite onaylı ve kullanılabilir')}${flowMetric('Sevk edilen',v.shipping.dispatched,'Teslimat ayrıca doğrulanır')}${flowMetric('Net teslim',v.shipping.netDelivered+' / '+v.orderedQuantity,'Fiziksel iadeler düşülür')}</div><div class="flow-next"><div><b>${closed?'Sipariş tamamlandı':inactive?'Sipariş iptal edildi':'Sonraki işlem'}</b><p>${h(v.next.label)}</p></div>${!inactive?`<button class="btn primary" onclick="RitimPremiumAPI.orderNext()">${canAct?'İşleme git →':'Üretimi takip et'}</button>`:''}<button class="btn" onclick="RitimPremiumAPI.poListOrder(${jsArg(detail.id)})">Bağlı Üretim Emirleri</button></div><details class="flow-details"><summary>Miktarlar ve üretim akışı</summary><p>Kalite kararı bekleyen: ${v.qualityPending} işlem adedi · Tamir bekleyen: ${v.repairPending} adet · Fiziksel iade: ${v.shipping.returned} adet · Yolda: ${v.shipping.inTransit} adet</p><p class="tiny">Kalite bekleyen işlem adetleri farklı operasyonları kapsayabilir; sipariş ilerlemesi olarak toplanmaz.</p>${v.productionOrders.map(p=>`<button class="flow-parent" onclick="RitimPremiumAPI.poOpen(${jsArg(p.id)})"><b>${h(p.number)}</b><span>${p.quantity} adet · ${p.compensation?'Telafi':'Normal üretim'} · ${h(poStatus(p.planningState))}</span></button>`).join('')||'<p>Henüz üretim emri yok.</p>'}${v.jobs.map(j=>`<div class="flow-operation"><div><b>${j.sequence+1}. ${h(j.operation)}</b><small>${h(j.reason)}</small></div><span>${j.produced} / ${j.quantity} işlem adedi</span><button class="btn sm" onclick="RitimPremiumAPI.openJob(${jsArg(j.id)},${jsArg(j.orderId)})">İşi aç</button></div>`).join('')}</details></section>${orderRecoveryPanel()}`}
 function productionMonitorContent(){const rows=monitorJobs.filter(j=>monitorFilter==='all'||monitorFilter==='running'&&j.status==='running'||monitorFilter==='ready'&&j.ready||monitorFilter==='blocked'&&j.blockers?.length);return `<section class="flow-monitor"><div class="card pad"><div class="flow-heading"><div><h2>Üretim takibi</h2><p>İç ve fason işler · Güncel çalışma ve bekleme nedenleri</p></div><button class="btn" onclick="RitimPremiumAPI.navigate('production-monitor')">Yenile</button></div><div class="flow-metrics">${flowMetric('Çalışan',monitorJobs.filter(j=>j.kind==='internal'&&j.status==='running').length)}${flowMetric('Fasondaki işler',monitorJobs.filter(j=>j.supplierOutstanding>0).length)}${flowMetric('Ön koşulları hazır',monitorJobs.filter(j=>j.ready).length)}${flowMetric('Karar / girdi bekleyen',monitorJobs.filter(j=>j.blockers?.length).length)}</div><nav class="flow-filters" aria-label="Üretim takibi filtresi">${[['all','Tümü'],['running','Çalışan'],['ready','Hazır'],['blocked','Bekleyen']].map(([id,label])=>`<button class="btn" aria-pressed="${monitorFilter===id}" onclick="RitimPremiumAPI.monitorFilter(${jsArg(id)})">${label}</button>`).join('')}</nav></div><div class="flow-job-grid">${rows.map(j=>`<article class="card pad"><span class="pill">${h(j.kind==='external'?'Fason':poStatus(j.status))}</span><h3>${h(j.partName)}</h3><p>${h(j.operation)} · ${h(j.orderNumber)}</p><p>${h(j.machineCode||'Makine atanmamış')} · ${j.produced} / ${j.quantity} işlem adedi</p><p class="flow-reason">${h(j.reason)}</p><button class="btn" onclick="${j.kind==='external'&&j.productionOrderId?`RitimPremiumAPI.openSupplierJob(${jsArg(j.productionOrderId)},${jsArg(j.id)})`:`RitimPremiumAPI.openJob(${jsArg(j.id)},${jsArg(j.orderId)})`}">İşi incele</button></article>`).join('')||'<div class="card pad">Bu filtrede açık iş bulunmuyor.</div>'}</div></section>`}

 function supplierQueueContent(){const rows=monitorJobs.filter(x=>x.kind==='external').sort((a,b)=>Number(b.supplierOutstanding>0)-Number(a.supplierOutstanding>0));return '<section class="card pad operations-workspace operations-suppliers"><div class="flow-heading"><div><span class="flow-eyebrow">FASON TAKİBİ</span><h2>Fason işleri</h2><p>Üretim emirlerindeki dış operasyonlar ve bekleyen dönüşler</p></div><button class="btn" onclick="RitimPremiumAPI.navigate(\'outsourcing\')">Yenile</button></div><div class="flow-job-grid">'+rows.map(j=>'<article class="card pad"><h3>'+h(j.partName)+'</h3><p>'+h(j.operation)+' · '+h(j.orderNumber)+'</p><p>Dışarıda '+j.supplierOutstanding+' adet · Kalite bekleyen '+j.qualityPending+' adet</p><p class="flow-reason">'+h(j.reason)+'</p><button class="btn" onclick="RitimPremiumAPI.openSupplierJob(\''+j.productionOrderId+'\',\''+j.id+'\')">Fason takibini aç</button></article>').join('')+(rows.length?'':'<p>Açık fason işi bulunmuyor.</p>')+'</div></section>'}
 function workspaceFilters(v,fresh=false){const defaults=v==='jobs'?{...(clarityRead().jobFilters||{}),...(viewPreferences.jobs?.settings||{})}:{},p=new URLSearchParams(location.search);if(fresh||p.get('view')!==v)return {...defaults};const keys=v==='overview'?['category','q']:['q','status','machineId','operatorId'];return {...defaults,...Object.fromEntries(keys.filter(k=>p.get(k)).map(k=>[k,p.get(k)]))}}
 function workspaceSearch(){const v=page==='overview'?daily:worklist,f=workspaceFilters(page);return `<form class="worklist-filters" onsubmit="event.preventDefault();RitimPremiumAPI.filterWorkspace()"><label class="formfield">Kayıtlarda ara<input id="workspace-query" class="input" type="search" maxlength="120" value="${h(v.query)}" placeholder="Sipariş, müşteri veya parça"></label>${page==='jobs'?`<label class="formfield">Durum<select class="select" id="workspace-status">${[['active','Açık işler'],['all','Tüm durumlar'],['waiting','Başlamadı'],['running','Çalışıyor'],['paused','Duraklatıldı'],['complete','Tamamlandı'],['cancelled','İptal edildi']].map(([id,t])=>`<option value="${id}" ${v.status===id?'selected':''}>${t}</option>`).join('')}</select></label>${[['machineId','Makine',v.machines],['operatorId','Operatör',v.operators]].map(([k,t,rows])=>`<label class="formfield">${t}<select class="select" id="workspace-${k}"><option value="">Tümü</option>${rows.map(x=>`<option value="${x.id}" ${f[k]===x.id?'selected':''}>${h(x.code||x.name)}</option>`).join('')}</select></label>`).join('')}`:''}<button class="btn primary" type="submit">Filtrele</button><button class="btn" type="button" onclick="RitimPremiumAPI.navigate('${page}')">Temizle</button></form>${preferenceControls(page)}`}
 function dailyContentOriginal(){if(!daily)return '<p>Günlük işler yükleniyor…</p>';return `<section class="daily-workspace"><div class="card pad flow-heading"><div><span class="flow-eyebrow">GÜNLÜK ÇALIŞMA ALANI</span><h2>Bugün neye odaklanmalıyız?</h2><p>${h(daily.today)} · İşlem bekleyen kayıtları doğrudan açın.</p></div><button class="btn" onclick="RitimPremiumAPI.refreshWorkspace()">Yenile</button></div><div class="daily-metrics">${daily.categories.slice().sort((a,b)=>Number(daily.counts[b.id]>0)-Number(daily.counts[a.id]>0)).map(c=>`<button class="card pad daily-metric ${daily.counts[c.id]?'':'daily-metric-zero'}" aria-pressed="${daily.category===c.id}" onclick="RitimPremiumAPI.dailyCategory(${jsArg(c.id)})"><strong>${daily.counts[c.id]}</strong><span>${h(c.label)}</span></button>`).join('')}</div><section class="card pad"><h3>${h(daily.categories.find(c=>c.id===daily.category)?.label)}</h3>${workspaceSearch()}<div class="workspace-list">${daily.items.map(x=>`<article class="workspace-row"><div><h4>${h(x.label)}</h4><p>${h(x.detail)}</p>${x.dueDate?`<small>Tarih: ${h(x.dueDate)}</small>`:''}</div><button class="btn" onclick="RitimPremiumAPI.dailyOpen(${jsArg(x.id)})">İncele →</button></article>`).join('')||'<div class="workspace-empty"><h4>Bu listede bekleyen kayıt yok</h4><p>Diğer iş gruplarını inceleyebilir veya aramayı değiştirebilirsiniz.</p></div>'}</div>${daily.nextAfter?'<button class="btn" onclick="RitimPremiumAPI.moreWorkspace()">Daha fazla göster</button>':''}</section></section>`}
 function worklistContent(){return compactWorklistContent()}
 async function reloadWorkspace(filters,append=false){const target=page,url=new URL(location.href);['category','q','status','machineId','operatorId','after'].forEach(k=>url.searchParams.delete(k));Object.entries(filters).forEach(([k,v])=>{if(v&&k!=='after')url.searchParams.set(k,v)});url.searchParams.set('view',target);const result=target==='overview'?await api.workCenter(filters):await api.jobWorklist(filters);if(append){const old=target==='overview'?daily:worklist;result.items=[...old.items,...result.items]}if(target==='overview')daily=result;else worklist=result;history.replaceState({ritimView:target},'',url)}
 function orderListFilters(fresh=false){const p=new URLSearchParams(location.search),defaults=viewPreferences.orders?.settings||{};if(fresh||p.get('view')!=='orders')return {...defaults};return {...defaults,...Object.fromEntries(['q','status','sort','direction','page','dueFrom','dueTo','allocation'].filter(k=>p.has(k)).map(k=>[k,p.get(k)]))}}
 function orderListContent(){const v=ordersWorkspace;if(!v)return '<section class="card pad">Siparişler yükleniyor…</section>';const f=v.filters,sortLabels={due:'Termin',created:'Kayıt tarihi',customer:'Müşteri',quantity:'Adet',number:'Sipariş numarası',priority:'Öncelik'};return `<section class="workspace-orders"><div class="card pad order-toolbar"><div class="flow-heading"><div><h2>${v.total} sipariş</h2><p>${h(sortLabels[f.sort]||'Termin')} · ${f.direction==='desc'?'azalan':'artan'}<span id="orders-filter-notice" role="status"></span></p></div><button class="btn primary" onclick="openWizard()" ${capable('orders.write')?'':'disabled'}>Yeni Sipariş</button></div><form oninput="RitimPremiumAPI.orderFilterDraft()" onchange="RitimPremiumAPI.orderFilterDraft()" onsubmit="event.preventDefault();RitimPremiumAPI.filterOrders()"><div class="order-workspace-filters"><label class="formfield">Sipariş ara<input class="input" id="orders-query" type="search" maxlength="120" value="${h(f.q)}" placeholder="Sipariş, müşteri, parça veya referans"></label><label class="formfield">Durum<select class="select" id="orders-status">${[['open','Açık siparişler'],['all','Tüm durumlar'],['closed','Kapalı'],['cancelled','İptal edildi']].map(([id,t])=>`<option value="${id}" ${f.status===id?'selected':''}>${t}</option>`).join('')}</select></label><button class="btn" type="submit">Uygula</button></div><details class="flow-details"><summary>Filtre ve sıralama</summary><div class="formgrid"><label class="formfield">Sıralama<select class="select" id="orders-sort">${[['due','Termin'],['created','Kayıt tarihi'],['customer','Müşteri'],['quantity','Adet'],['number','Sipariş numarası'],['priority','Öncelik']].map(([id,t])=>`<option value="${id}" ${f.sort===id?'selected':''}>${t}</option>`).join('')}</select></label><label class="formfield">Yön<select class="select" id="orders-direction"><option value="asc" ${f.direction==='asc'?'selected':''}>Artan / önce</option><option value="desc" ${f.direction==='desc'?'selected':''}>Azalan / sonra</option></select></label><label class="formfield">Termin başlangıcı<input class="input" id="orders-dueFrom" type="date" value="${h(f.dueFrom)}"></label><label class="formfield">Termin sonu<input class="input" id="orders-dueTo" type="date" value="${h(f.dueTo)}"></label><label class="formfield">Üretime ayrılma<select class="select" id="orders-allocation">${[['all','Tümü'],['remaining','Ayrılabilir miktarı var'],['allocated','Tamamı ayrılmış']].map(([id,t])=>`<option value="${id}" ${f.allocation===id?'selected':''}>${t}</option>`).join('')}</select></label></div><button class="btn sm" type="submit">Filtreleri uygula</button><button class="btn sm" type="button" onclick="RitimPremiumAPI.resetOrders()">Temizle</button></details></form>${preferenceControls('orders')}</div><div class="workspace-order-list">${v.items.map(o=>`<article class="card pad workspace-order-row"><button class="workspace-order-title" onclick="RitimPremiumAPI.orderPeek(${jsArg(o.id)})"><strong>${h(o.customer)}</strong><span>${h(o.partName)} · ${h(o.partNumber||'Kod yok')}</span><small>${h(o.orderNumber)}${o.reference?' · '+h(o.reference):''}</small></button><div class="order-quantity-facts"><div><small>Sipariş</small><b>${o.orderedQuantity}</b></div><div><small>Üretime ayrılan</small><b>${o.allocated}</b></div><div class="order-remaining"><small>Üretime ayrılacak</small><b>${Math.max(0,o.orderedQuantity-o.allocated)}</b></div><span>Net teslim: ${o.netDelivered??0} adet</span></div><div><small>Termin</small><b>${h(workspaceDate(o.dueDate))}</b>${o.priority?`<span class="pill">${['','Öncelikli','Yüksek','Acil'][o.priority]}</span>`:''}</div><span class="pill" data-state="${h(o.status)}">${h(displayStatus(o.status))}</span><div class="workspace-order-actions"><button class="btn order-next-action" onclick="${o.unallocated&&o.status==='open'&&capable('planning.write')?`RitimPremiumAPI.openBatches(${jsArg(o.id)})`:o.unplanned&&o.status==='open'?`RitimPremiumAPI.poListOrder(${jsArg(o.id)})`:`RitimPremiumAPI.openOrder(${jsArg(o.id)})`}">${o.unallocated&&o.status==='open'&&capable('planning.write')?'Üretime ayır':o.unplanned&&o.status==='open'?'Planlamayı aç':'İncele'}</button><details><summary aria-label="${h(o.orderNumber)} diğer işlemler">•••</summary>${capable('orders.write')&&o.status==='open'?`<button class="btn sm" onclick="RitimPremiumAPI.editOrder(${jsArg(o.id)})">Düzenle</button>`:''}<button class="btn sm" onclick="RitimPremiumAPI.openOrder(${jsArg(o.id)})">Sipariş detayı</button></details></div></article>`).join('')||'<section class="card pad workspace-empty"><h3>Eşleşen sipariş yok</h3><p>Aramanızı veya filtreleri değiştirin.</p><button class="btn" onclick="RitimPremiumAPI.resetOrders()">Filtreleri temizle</button></section>'}</div><div class="workspace-pagination"><button class="btn" onclick="RitimPremiumAPI.ordersPage(${v.page-1})" ${v.page<=1?'disabled':''}>← Önceki</button><span>Sayfa ${v.page} / ${v.pages} · ${v.total} sipariş</span><button class="btn" onclick="RitimPremiumAPI.ordersPage(${v.page+1})" ${v.page>=v.pages?'disabled':''}>Sonraki →</button></div><p class="tiny">Liste sıralaması üretim önceliğini veya makine kuyruklarını değiştirmez.</p></section>`}
 async function loadOrderWorkspace(filters){ordersWorkspace=await api.orderWorkspace(filters);const u=new URL(routeUrl('orders'),location.href);for(const k of ['page','dueFrom','dueTo','allocation'])u.searchParams.delete(k);for(const [k,v] of Object.entries({...ordersWorkspace.filters,page:ordersWorkspace.page}))if(v)u.searchParams.set(k,v);history.replaceState({},'',u);ordersLocation=u.href}
 function editMasterPicker(key,label){return `<label class="formfield">${label}<input class="input" id="edit-${key}-search" value="${h(key==='customer'?editDraft.customer:editDraft.partName)}" ${editModel.identityLocked?'disabled':''} autocomplete="off" role="combobox" aria-expanded="false" aria-controls="edit-${key}-results" oninput="RitimPremiumAPI.editMasterSearch('${key}',this.value)" onkeydown="if(event.key==='Escape'){document.getElementById('edit-${key}-results').innerHTML='';this.setAttribute('aria-expanded','false')}"></label><div id="edit-${key}-results" class="edit-master-results"></div>${capable('master.write')&&!editModel.identityLocked?`<button type="button" class="master-quick-add" onclick="RitimPremiumAPI.quickMaster('${key}','edit')">+ Yeni ${key==='customer'?'müşteri':'parça'} ekle</button>`:''}`}
 function orderEditContent(){if(!editModel)return '';const d=editDraft,o=editModel;return `<section class="card pad order-edit-panel"><button class="btn sm" onclick="RitimPremiumAPI.openOrder(${jsArg(o.id)})">← Siparişe dön</button><span class="flow-eyebrow">GÜVENLİ DÜZENLEME</span><h2>${h(o.orderNumber)}</h2><p>${o.identityLocked?'Üretim veya teknik çizim bağlantısı var. Müşteri ve parça korunur; miktar ve termin değişikliği gerekçeyle kaydedilir.':'Üretime ayrılmamış siparişin temel bilgilerini düzenleyebilirsiniz.'}</p>${conflictContent()}<form oninput="RitimPremiumAPI.editReview()" onsubmit="event.preventDefault();RitimPremiumAPI.saveOrderEdit()"><fieldset class="edit-fieldset" ${editConflict?'disabled':''}>${editMasterPicker('customer','Müşteri')}${editMasterPicker('part','Parça')}<div class="formgrid"><label class="formfield">Sipariş adedi<input class="input" id="edit-quantity" type="number" min="${o.minimumQuantity||Math.max(1,o.allocated)}" step="1" required value="${d.orderedQuantity}" oninput="RitimPremiumAPI.editPreview()"></label><label class="formfield">Termin<input class="input" type="date" id="edit-due" value="${h(d.dueDate||'')}" onchange="RitimPremiumAPI.editPreview()"></label></div><details class="flow-details"><summary>Ek bilgiler</summary><div class="formgrid"><label class="formfield">Müşteri referansı<input class="input" id="edit-reference" maxlength="120" value="${h(d.reference)}"></label><label class="formfield">Öncelik<select class="select" id="edit-priority">${[['0','Standart'],['1','Öncelikli'],['2','Yüksek'],['3','Acil']].map(([id,t])=>`<option value="${id}" ${Number(id)===d.priority?'selected':''}>${t}</option>`).join('')}</select></label></div><label class="formfield">Açıklama<textarea class="input" id="edit-notes" maxlength="2000">${h(d.notes)}</textarea></label></details><div class="flow-notice" id="edit-impact">Üretime ayrılmış ${o.allocated} adet korunur. Mevcut iş emirlerinin miktarı otomatik değiştirilmez.</div><label class="formfield">Değişiklik gerekçesi ${o.identityLocked?'':'· isteğe bağlı'}<input class="input" id="edit-reason" value="${h(d.reason||'')}" maxlength="120" placeholder="Örn. müşterinin revize termin talebi"></label><div id="edit-review" class="edit-review" role="status"></div><div class="production-create-footer"><button class="btn" type="button" onclick="RitimPremiumAPI.editReload()">Güncel kaydı yükle</button><button class="btn primary" type="submit" ${editConflict||o.status!=='open'?'disabled':''}>Değişiklikleri kaydet</button></div></fieldset></form></section>`}
 async function prepareBatches(id){await loadDetail(id);const info=await api.orderEditing(id);batchModel={orderId:id,version:info.version,remaining:Math.max(0,info.orderedQuantity-info.allocated),operations:detail.route.map(x=>({name:x.name,kind:x.kind,setupMinutes:null,cycleMinutes:null})),batches:[{quantity:Math.max(0,info.orderedQuantity-info.allocated),number:await p1Number(),plannedDate:'',custom:false,operations:[]}],preview:false}}
 function routeEditor(ops,prefix,handler){return `<div class="production-route">${ops.map((op,i)=>`<article class="card pad route-editor-operation"><div class="production-route-row"><span class="op-number">${i+1}</span><label class="formfield">Operasyon adı<input class="input" id="${prefix}-name-${i}" required maxlength="120" value="${h(op.name)}"></label><label class="formfield">Tür<select class="select" id="${prefix}-kind-${i}"><option value="internal" ${op.kind==='internal'?'selected':''}>İç operasyon</option><option value="external" ${op.kind==='external'?'selected':''}>Fason</option></select></label><div class="production-route-actions"><button type="button" class="btn sm" aria-label="${i+1}. operasyonu yukarı taşı" onclick="RitimPremiumAPI.routeChange(${jsArg(handler)},'up',${i})" ${i?'':'disabled'}>↑</button><button type="button" class="btn sm" aria-label="${i+1}. operasyonu aşağı taşı" onclick="RitimPremiumAPI.routeChange(${jsArg(handler)},'down',${i})" ${i===ops.length-1?'disabled':''}>↓</button><button type="button" class="btn sm" aria-label="${i+1}. operasyonu kaldır" onclick="RitimPremiumAPI.routeChange(${jsArg(handler)},'remove',${i})">×</button></div></div><details><summary>Tahmini süreler · isteğe bağlı</summary><div class="formgrid"><label class="formfield">Hazırlık · dakika<input class="input" id="${prefix}-setup-${i}" type="number" min="0" max="10080" step="0.001" value="${op.setupMinutes??''}"></label><label class="formfield">Adet başı · dakika<input class="input" id="${prefix}-cycle-${i}" type="number" min="0" max="10080" step="0.001" value="${op.cycleMinutes??''}"></label></div><p class="tiny">Boş bırakılan süre bilinmiyor kabul edilir. Sıfır, süre gerekmediğini belirtir.</p></details></article>`).join('')||'<p class="order-hint">Rota henüz tanımlanmadı. Üretim emri oluşturulabilir; planlamak için rota ekleyin.</p>'}</div><button class="btn" type="button" onclick="RitimPremiumAPI.routeChange(${jsArg(handler)},'add',0)">＋ Operasyon ekle</button>`}
 function captureRoute(ops,prefix){ops.forEach((op,i)=>{op.name=el(prefix+'-name-'+i)?.value??op.name;op.kind=el(prefix+'-kind-'+i)?.value??op.kind;for(const k of ['setup','cycle']){const value=el(prefix+'-'+k+'-'+i)?.value;if(value!==undefined)op[k+'Minutes']=value===''?null:Number(value)}})}
 function captureBatches(){if(!batchModel)return;const route=document.querySelector('.refine-common-route');if(route)batchModel.routeOpen=route.open;captureRoute(batchModel.operations,'batch-common');batchModel.batches.forEach((b,i)=>{b.quantity=Number(el('batch-qty-'+i)?.value??b.quantity);b.number=el('batch-number-'+i)?.value??b.number;b.plannedDate=el('batch-date-'+i)?.value??b.plannedDate;if(b.custom)captureRoute(b.operations,'batch-'+i)})}
 function batchContent(){
  const d=batchModel;if(!d)return '';if(!d.remaining)return '<section class="card pad workspace-empty">'+refineState('Siparişin tamamı üretime ayrılmış','Mevcut üretim emirlerinden planlamaya devam edebilirsiniz.','complete')+`<button class="btn primary" onclick="RitimPremiumAPI.poListOrder(${jsArg(d.orderId)})">Üretim emirlerini aç</button><button class="btn" onclick="RitimPremiumAPI.openOrder(${jsArg(d.orderId)})">Siparişe dön</button></section>`;
  const sum=d.batches.reduce((n,b)=>n+b.quantity,0);return `<section class="production-orders-page refine-batches"><header class="card pad refine-batch-heading"><button class="btn sm" onclick="RitimPremiumAPI.openOrder(${jsArg(d.orderId)})">← Siparişe dön</button><div><span class="flow-eyebrow">ÜRETİM EMRİ OLUŞTUR</span><h2>${h(detail.partName)}</h2><p>${h(detail.orderNumber)} · <b>${d.remaining} adet</b> üretime ayrılabilir</p></div></header><form class="refine-batch-form" oninput="RitimPremiumAPI.batchBalance()" onsubmit="event.preventDefault();RitimPremiumAPI.batchPreview(false)"><section class="card pad refine-parties"><div class="flow-heading"><div><h3>Üretim partileri</h3><p>Tamamını vermek zorunda değilsiniz. Örneğin 10 adedin 6’sıyla başlayıp kalan 4 adedi sonra oluşturabilirsiniz.</p></div><button class="btn" type="button" onclick="RitimPremiumAPI.batchAdd()">＋ Parti ekle</button></div>${d.batches.map((b,i)=>`<article class="batch-row"><div class="refine-party-id"><span class="op-number">${i+1}</span><h4>Parti ${i+1}</h4></div><label class="formfield">Bu emirde üretilecek adet<input class="input" id="batch-qty-${i}" type="number" min="1" max="${d.remaining}" step="1" required value="${b.quantity}"></label><label class="formfield refine-party-date">Hedef tarih · isteğe bağlı<input class="input" type="date" id="batch-date-${i}" value="${h(b.plannedDate)}"></label><div class="refine-party-actions">${d.batches.length>1?`<button class="btn sm" type="button" aria-label="Parti ${i+1} kaldır" onclick="RitimPremiumAPI.batchRemove(${i})">×</button>`:''}</div><details class="refine-party-more" ${b.custom?'open':''}><summary>Numara ve özel rota${b.custom?' · özelleştirildi':''}</summary><label class="formfield">Üretim emri numarası · düzenlenebilir<input class="input" id="batch-number-${i}" maxlength="100" value="${h(b.number)}"></label><button class="btn sm" type="button" onclick="RitimPremiumAPI.batchCustom(${i})">${b.custom?'Ortak rotayı kullan':'Bu partiye özel rota'}</button>${b.custom?routeEditor(b.operations,'batch-'+i,String(i)):''}</details></article>`).join('')}</section><details class="card pad refine-common-route" ${d.routeOpen||d.operations.some(op=>!op.name.trim())?'open':''}><summary><span><b>Ortak operasyon rotası</b><small>${d.operations.length?d.operations.length+' operasyon · tüm partilere uygulanır':'İsteğe bağlı · rotayı planlarken tanımlayabilirsiniz'}</small></span><span class="refine-disclosure-label">Düzenle</span></summary><div class="template-actions"><button class="btn sm" type="button" onclick="RitimPremiumAPI.openTemplates('batch')">Şablondan rota seç</button><button class="btn sm" type="button" onclick="RitimPremiumAPI.openTemplates('batch',true)">Rotayı şablon olarak kaydet</button></div>${routeEditor(d.operations,'batch-common','common')}</details><footer class="card pad production-create-footer refine-batch-footer"><div id="batch-balance" class="${sum>d.remaining?'batch-over':''}" role="status" aria-live="polite">Partilere ayrılan ${sum} · Ayrılabilir kalan ${d.remaining-sum} adet</div><div><button class="btn" type="submit">Emirleri oluştur · önizle</button><button class="btn primary" type="button" onclick="RitimPremiumAPI.batchPreview(true)">İş emirleriyle oluştur · önizle</button></div></footer></form>${d.preview?`<section class="card pad batch-preview" role="region" aria-label="Üretim önizlemesi"><h3>Kaydetmeden önce</h3><p><b>${d.batches.length} üretim emri</b> oluşturulacak. ${d.preview.planCount} parti için tarih kaydedilecek ve <b>${d.preview.jobCount} iş emri</b> oluşacak.</p>${d.preview.rows.map((b,i)=>`<p>Parti ${i+1}: ${b.quantity} adet · ${b.plan?'İş emirleri oluşacak · '+h(b.plannedDate):'İş emirleri daha sonra oluşturulacak'} · ${b.operations.length} operasyon</p>`).join('')}<p>Kalan ayrılabilir miktar: ${d.remaining-sum} adet. Kaydın tamamı birlikte gerçekleştirilir.</p><button class="btn primary" onclick="RitimPremiumAPI.batchSave()">${d.preview.planCount?'Onayla ve iş emirlerini oluştur':'Onayla ve oluştur'}</button><button class="btn" onclick="RitimPremiumAPI.batchCancelPreview()">Düzenlemeye dön</button></section>`:''}</section>`;
 }
 function poEditContent(){const d=poEditModel;if(!d)return '';return `<section class="card pad po-edit-panel"><button class="btn sm" onclick="RitimPremiumAPI.poOpen(${jsArg(d.id)})">← Üretim emrine dön</button><h2>${h(d.number)} · Düzenle</h2><p>İş emirleri henüz oluşmadığı için miktar ve rota güncellenebilir.</p><form onsubmit="event.preventDefault();RitimPremiumAPI.savePoEdit()"><label class="formfield">Üretilecek adet<input class="input" type="number" min="1" step="1" required id="po-edit-quantity" value="${d.quantity}"></label>${routeEditor(d.operations,'po-edit','po')}<label class="formfield">Değişiklik gerekçesi<input class="input" id="po-edit-reason" maxlength="120" required value="${h(d.reason||'')}"></label><div class="production-create-footer"><button class="btn primary" type="submit">Üretim emrini güncelle</button></div></form></section>`}
 async function experienceCommand(command,orderId,resourceId,payload){const existing=journal.list().find(x=>x.kind==='operation'&&x.body.orderId===orderId&&x.body.command===command);if(existing)throw Error('Önce bu işlemin bekleyen sonucunu doğrulayın.');const row=await journal.begin({...scope,kind:'operation',target:resourceId||orderId,body:{command,orderId,resourceId:resourceId||'',payload}});let result;await journal.execute(row,null,{beforeClear:async x=>{result=x}});return result}
 function orderActionBar(){return `<div class="flow-heading order-actionbar"><button class="btn" onclick="RitimPremiumAPI.backOrders()">← Sipariş listesine dön</button><div>${detail.status==='open'&&capable('orders.write')?`<button class="btn" onclick="RitimPremiumAPI.editOrder(${jsArg(detail.id)})">Siparişi düzenle</button>`:''}${detail.status==='open'&&capable('planning.write')?`<button class="btn primary" onclick="RitimPremiumAPI.openBatches(${jsArg(detail.id)})">Üretim emri oluştur</button>`:''}</div></div>`}
 function orderHistoryContent(){const v=orderEditingView;if(!v)return '';return `<details class="card pad"><summary>Ek bilgiler ve değişiklik geçmişi</summary><p>Referans: ${h(v.reference||'Belirtilmedi')}</p>${v.notes?`<p>${h(v.notes)}</p>`:''}${v.history.map(x=>`<article class="workspace-row"><div><b>${h(new Date(x.occurred_at).toLocaleString('tr-TR'))}</b><p>${h(x.payload.reason||'Sipariş bilgileri güncellendi')}</p><p>Adet: ${h(x.payload.before?.orderedQuantity??'—')} → ${h(x.payload.after?.quantity??'—')} · Termin: ${h(x.payload.before?.dueDate||'Belirlenmedi')} → ${h(x.payload.after?.dueDate||'Belirlenmedi')}</p></div></article>`).join('')||'<p>Henüz düzenleme kaydı yok.</p>'}</details>`}
 function shortTime(value){return value?new Date(value).toLocaleString('tr-TR',{day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit',timeZone:'Europe/Istanbul'}):'Tahmin yok'}
 function boardSchedule(j){const s=j.schedule;return `<div class="capacity-job ${s?.late?'capacity-late':''}"><b>${s?.durationMinutes==null?'Süre bilinmiyor':Math.round(s.durationMinutes*10)/10+' dk kalan iş'}</b>${s?.end?`<span>${h(shortTime(s.start))} → ${h(shortTime(s.end))}</span>${s.late?'<strong>Termin riski</strong>':''}`:`<span>${h(s?.reason||'Süre ve ön koşulları tamamlayın')}</span>`}<small>Vardiya ve molaya göre tahmin · kesin başlama taahhüdü değildir.</small></div>`}
 function timingEditor(j){return `<div class="timing-editor"><h5>Tahmini süre</h5><label class="formfield">Hazırlık · dk<input class="input" id="timing-setup-${j.id}" type="number" min="0" max="10080" step="0.001" value="${j.timing?.setupMinutes??''}"></label><label class="formfield">Adet başı · dk<input class="input" id="timing-cycle-${j.id}" type="number" min="0" max="10080" step="0.001" value="${j.timing?.cycleMinutes??''}"></label><button class="btn sm" onclick="RitimPremiumAPI.saveTiming(${jsArg(j.id)})">Süreyi kaydet</button><small>Boş süreler tahmin edilmez; kuyruk sıralaması kullanılabilir.</small></div>`}
 function minuteTime(n){return String(Math.floor(n/60)).padStart(2,'0')+':'+String(n%60).padStart(2,'0')}
 function machineCapacity(m){const c=m.capacity,cal=m.calendar;if(!c||!cal)return '';return `<div class="capacity-machine">${boardMode==='time'?`<b>${c.availableMinutes>0?'Kalan vardiya doluluğu: %'+c.utilization:'Bugünkü çalışma süresi tamamlandı'}</b><progress max="100" value="${c.utilization}" aria-label="Bugünkü makine doluluğu"></progress><small>${c.availableMinutes>0?c.scheduledMinutes+' / '+c.availableMinutes+' dk':'Tahminler sonraki çalışma dilimine göre hesaplanır'} · ${c.unknownJobs} işin zamanı belirsiz</small>`:''}${capable('planning.write')?`<details><summary>Vardiya ve mola</summary><div class="calendar-days">${['Pzt','Sal','Çar','Per','Cum','Cmt','Paz'].map((day,i)=>`<label><input type="checkbox" id="calendar-day-${m.id}-${i+1}" ${cal.weekdays.includes(i+1)?'checked':''}>${day}</label>`).join('')}</div>${[['startMinute','Başlangıç'],['endMinute','Bitiş'],['breakStartMinute','Mola başlangıcı'],['breakEndMinute','Mola bitişi']].map(([key,label])=>`<label class="formfield">${label}<input class="input" id="calendar-${key}-${m.id}" type="time" value="${minuteTime(cal[key])}"></label>`).join('')}<p class="tiny">Aynı gün içinde tek vardiya. Mola yoksa mola başlangıcı ve bitişini eşit girin.</p><button class="btn sm" onclick="RitimPremiumAPI.saveCalendar(${jsArg(m.id)})">Çalışma takvimini kaydet</button></details>`:''}</div>`}

 let masterEditor=null,editConflict=null,inventoryPinnedMaterial=null;
 let inventoryPages={materials:{q:'',total:0,nextAfter:null},movements:{q:'',kind:'',total:0,nextAfter:null}};
 function followBoardMove(machine){if(matchMedia('(max-width:820px)').matches){mobileMachine=machine||'';boardMachine='all'}else if(boardMachine!=='all')boardMachine=machine||'all'}
 function captureOrderEdit(){if(!editDraft||!el('edit-quantity'))return;Object.assign(editDraft,{orderedQuantity:Number(el('edit-quantity').value),dueDate:el('edit-due').value||null,reference:el('edit-reference').value,notes:el('edit-notes').value,priority:Number(el('edit-priority').value),reason:el('edit-reason').value});if(!editDraft.customerId)editDraft.customer=el('edit-customer-search').value;if(!editDraft.partId)editDraft.partName=el('edit-part-search').value}
 const compareFields=[['customer','Müşteri',['customerId','customer']],['partName','Parça',['partId','partName']],['orderedQuantity','Sipariş adedi',['orderedQuantity']],['dueDate','Termin',['dueDate']],['reference','Müşteri referansı',['reference']],['priority','Öncelik',['priority']],['notes','Açıklama',['notes']]];
 const equalGroup=(a,b,keys)=>keys.every(k=>String(a[k]??'')===String(b[k]??''));
 function conflictRows(){const c=editConflict;return compareFields.map(([key,label,keys])=>({key,label,keys,local:!equalGroup(c.base,c.mine,keys),remote:!equalGroup(c.base,c.latest,keys),same:equalGroup(c.mine,c.latest,keys),locked:c.latest.identityLocked&&['customer','partName'].includes(key)})).filter(r=>r.local||r.remote)}
 function compareValue(record,key){const value=record[key];if(key==='priority')return ['Standart','Öncelikli','Yüksek','Acil'][value]||'Standart';return value==null||value===''?'—':value}
 function conflictContent(){if(!editConflict)return '';const c=editConflict;return `<section class="version-compare" aria-labelledby="version-title"><h3 id="version-title">Kayıt değişti · taslağınız korundu</h3><p>Sürüm ${c.base.version} → ${c.latest.version}. Çakışan alanlarda hangi değerin kullanılacağını seçin. Birleştirdikten sonra kaydetmeden önce gözden geçirin.</p>${c.latest.status!=='open'?'<p role="alert">Sipariş kapatılmış. Bu sürüm üzerinde değişiklik kaydedilemez.</p>':`<p>Güncel alt miktar sınırı: ${c.latest.minimumQuantity||1} adet.${c.latest.identityLocked?' Üretim bağlantısı nedeniyle müşteri ve parça korunur.':''}</p>`}<div class="version-table"><div class="version-heading"><b>Alan</b><b>Önceki kayıt</b><b>Sunucudaki güncel</b><b>Sizin taslağınız</b><b>Kullanılacak değer</b></div>${conflictRows().map(r=>`<div class="version-row"><b>${r.label}</b><span data-label="Önceki">${h(compareValue(c.base,r.key))}</span><span data-label="Güncel">${h(compareValue(c.latest,r.key))}</span><span data-label="Taslak">${h(compareValue(c.mine,r.key))}</span><span>${r.locked?'Üretim bağlantısı · güncel kayıt korunur':r.local&&r.remote&&!r.same?`<label>Seçiminiz<select class="select" data-conflict="${r.key}" onchange="RitimPremiumAPI.conflictChoice('${r.key}',this.value)"><option value="">Seçin</option><option value="mine" ${c.choices[r.key]==='mine'?'selected':''}>Taslağımdaki</option><option value="server" ${c.choices[r.key]==='server'?'selected':''}>Güncel kayıttaki</option></select></label>`:r.local?'Taslağınızdaki korunur':'Güncel kayıttaki korunur'}</span></div>`).join('')}</div><p class="field-error" id="version-error" role="alert"></p><div class="master-editor-actions"><button class="btn" type="button" onclick="RitimPremiumAPI.resolveOrderConflict(true)">Güncel kaydı kullan</button><button class="btn primary" type="button" onclick="RitimPremiumAPI.resolveOrderConflict(false)">Seçimleri taslağa uygula</button></div></section>`}
 function captureMasterEditor(){if(!masterEditor||!el('master-name'))return;masterEditor.draft={name:el('master-name').value,code:el('master-code').value}}
 function openMasterEditor(kind,item,origin,key){if(busy||!capable('master.write'))return;masterEditor={kind,editing:item?{...item}:null,draft:{name:item?.name||'',code:item?.code||''},origin,key,focusId:origin==='wizard'?'order-'+key:origin==='edit'?'edit-'+key+'-search':document.activeElement?.id,scroll:scrollY,error:''};if(!item&&key)masterEditor.draft.name=origin==='wizard'?wizard[key]||'':editDraft[key==='customer'?'customer':'partName']||'';mountMasterEditor()}
 function closeMasterEditor(){if(busy)return;const editor=masterEditor;masterEditor=null;el('master-drawer')?.remove();if(editor?.origin==='wizard')renderModal();if(editor?.focusId)el(editor.focusId)?.focus({preventScroll:true});if(editor)scrollTo(0,editor.scroll)}
 function mountMasterEditor(){if(!masterEditor){el('master-drawer')?.remove();return}const e=masterEditor,customer=e.kind==='customers';let dialog=el('master-drawer');if(!dialog){dialog=document.createElement('dialog');dialog.id='master-drawer';dialog.className='master-drawer';dialog.setAttribute('aria-labelledby','master-drawer-title');document.body.append(dialog);dialog.addEventListener('cancel',event=>{event.preventDefault();closeMasterEditor()})}dialog.innerHTML=`<form onsubmit="event.preventDefault();RitimPremiumAPI.saveMaster()"><header><div><span class="flow-eyebrow">ANA VERİLER · ${customer?'MÜŞTERİ':e.kind==='scrap-reasons'?'HURDA NEDENİ':'PARÇA'}</span><h2 id="master-drawer-title">${e.editing?'Kaydı düzenle':customer?'Yeni müşteri':e.kind==='scrap-reasons'?'Yeni hurda nedeni':'Yeni parça'}</h2></div><button class="btn" type="button" aria-label="Paneli kapat" onclick="RitimPremiumAPI.cancelMasterEdit()" ${busy?'disabled':''}>×</button></header><p>${e.origin==='master'?'Kaydettikten sonra aynı listeye dönersiniz.':'Kaydettikten sonra sipariş taslağınıza seçili olarak eklenir.'}</p><label class="formfield">${customer?'Müşteri / Firma adı':e.kind==='scrap-reasons'?'Hurda nedeni':'Parça / Ürün adı'}<input class="input" id="master-name" required maxlength="120" value="${h(e.draft.name)}" ${e.error&&e.errorField==='name'?'aria-invalid="true" aria-describedby="master-panel-error"':''}></label><label class="formfield">${customer?'Müşteri kodu':e.kind==='scrap-reasons'?'Neden kodu':'Parça kodu'} <small>İsteğe bağlı</small><input class="input" id="master-code" maxlength="120" value="${h(e.draft.code)}" ${e.error&&e.errorField==='code'?'aria-invalid="true" aria-describedby="master-panel-error"':''}></label><p class="field-error" id="master-panel-error" role="alert">${h(e.error)}</p>${e.latest?`<section class="master-version"><b>Güncel kayıt · sürüm ${e.latest.version}</b><p>${h(e.latest.name)} · ${h(e.latest.code||'Kod yok')}</p><p>Taslağınız: ${h(e.draft.name)} · ${h(e.draft.code||'Kod yok')}</p><button type="button" class="btn" onclick="RitimPremiumAPI.masterRebase(false)">Güncel kaydı kullan</button><button type="button" class="btn" onclick="RitimPremiumAPI.masterRebase(true)">Taslağımı koruyarak devam et</button></section>`:''}${journal?.list().filter(x=>x.kind==='masterData').map(x=>`<div class="master-version"><p>İşlemin sonucu henüz doğrulanmadı. Aynı işlem kimliğiyle kontrol edin.</p><button class="btn" type="button" onclick="RitimPremiumAPI.retryMaster('${x.id}')">Sonucu doğrula ve devam et</button></div>`).join('')||''}<footer><button type="button" class="btn" onclick="RitimPremiumAPI.cancelMasterEdit()" ${busy?'disabled':''}>Vazgeç</button><button class="btn primary" type="submit" ${busy||e.latest?'disabled':''}>${busy?'Kaydediliyor…':e.editing?'Değişiklikleri kaydet':'Kaydet ve devam et'}</button></footer></form>`;for(const input of dialog.querySelectorAll('input'))input.addEventListener('input',captureMasterEditor);if(!dialog.open)dialog.showModal();if(e.error)el('master-'+e.errorField)?.focus();else el('master-name')?.focus()}
 function completeMasterEditor(result){const e=masterEditor;if(!e||!result?.id)throw Error('Kaydedilen ana kayıt doğrulanamadı.');if(e.origin==='wizard'){wizard[e.key]=result.name;wizard[e.key+'Id']=result.id;if(e.key==='part')wizard.partNo=result.code||''}else if(e.origin==='edit'){editDraft[e.key+'Id']=result.id;editDraft[e.key==='customer'?'customer':'partName']=result.name}else{const index=masterView.items.findIndex(x=>x.id===result.id);if(index>=0)masterView.items[index]=result;else if((result.name+' '+(result.code||'')).toLocaleLowerCase('tr-TR').includes(masterView.q.toLocaleLowerCase('tr-TR')))masterView.items.unshift(result);masterView.notice=e.editing?'Değişiklikler kaydedildi.':'Yeni kayıt eklendi.'}masterView.editing=null;masterEditor=null;el('master-drawer')?.remove();setTimeout(()=>{if(e.focusId)el(e.focusId)?.focus({preventScroll:true});scrollTo(0,e.scroll)},0)}

 function inventoryMovementRows(){return '<div class="inventory-movements">'+(inventoryView.movements.map(a=>`<article class="inventory-movement"><header><span class="pill" data-state="${a.kind==='scrap'?'rejected':a.kind==='receipt'?'approved':'planned'}">${h(({receipt:'Mal kabul',move:'Taşıma',pick:'İş emrine teslim',scrap:'Hurda'})[a.kind]||a.kind)}</span><time datetime="${h(a.occurredAt)}">${h(new Date(a.occurredAt).toLocaleString('tr-TR'))}</time></header><div class="inventory-movement-main"><div><b>${h(a.materialCode||'Malzeme')}</b><small>Lot · ${h(a.lotCode||inventoryView.balances.find(x=>x.lotId===a.lotId)?.lotCode||shortReference(a.lotId))}</small></div><strong>${a.quantity} <small>adet</small></strong></div><p>${a.sourceLocationId?h(inventoryLocationPath(a.sourceLocationId)):'Dış kaynak'} → ${a.destinationLocationId?h(inventoryLocationPath(a.destinationLocationId)):a.kind==='scrap'?'Hurda':'Üretim'}</p>${a.documentRef?`<small class="inventory-document">${a.kind==='scrap'?'Gerekçe':'Belge'} · ${h(a.documentRef)}</small>`:''}</article>`).join('')||'<p class="inventory-no-results">Eşleşen hareket bulunamadı. Aramayı veya hareket türünü değiştirin.</p>')+'</div>'}
 function inventorySearchContent(kind){const v=inventoryPages[kind],materials=kind==='materials';return `<form ${materials?'data-inventory-panel="receipt stock" '+(['receipt','stock'].includes(inventoryTask)?'':'hidden'):''} class="inventory-discovery context-search" onsubmit="event.preventDefault();RitimPremiumAPI.inventorySearch('${kind}',false)"><label class="formfield">${materials?'Malzeme bul':'Hareket ara'}<input class="input" id="inventory-${kind}-query" type="search" maxlength="120" value="${h(v.q)}" placeholder="${materials?'Kod veya açıklama':'Malzeme, lot veya belge'}"></label>${materials?'':`<label class="formfield">Hareket türü<select class="select" id="inventory-movements-kind">${[['','Tüm hareketler'],['receipt','Mal kabul'],['move','Taşıma'],['pick','İş emrine teslim'],['scrap','Hurda']].map(([key,label])=>`<option value="${key}" ${key===v.kind?'selected':''}>${label}</option>`).join('')}</select></label>`}<button class="btn" type="submit">Ara</button><button class="btn" type="button" onclick="RitimPremiumAPI.inventorySearch('${kind}',false,true)">Temizle</button>${v.nextAfter?`<button class="btn" type="button" onclick="RitimPremiumAPI.inventorySearch('${kind}',true)">Daha fazla göster</button>`:''}<small role="status">${inventoryView[kind].length} / ${v.total} kayıt</small></form>`}

