 function compensationListContent(){const v=compensationQueue,f=compensationFilters,options=(rows,value)=>rows.map(([key,label])=>`<option value="${key}" ${value===key?'selected':''}>${label}</option>`).join('');return `<section class="compensation-workspace"><div class="card pad"><span class="flow-eyebrow">KAYIPTAN TELAFİ ÜRETİMİNE</span><h2>Telafi kayıtları</h2><nav class="flow-filters" aria-label="Telafi görünümü"><button class="btn" aria-pressed="${f.state==='active'}" onclick="RitimPremiumAPI.compensationState('active')">İşlem bekleyenler</button><button class="btn" aria-pressed="${f.state==='all'}" onclick="RitimPremiumAPI.compensationState('all')">Tümü / geçmiş</button></nav><p>Belgelenmiş kayıplara verilen izinleri ve bağlı üretim emirlerini takip edin.</p><form class="compensation-filters" onsubmit="event.preventDefault();RitimPremiumAPI.filterCompensations()"><label class="formfield">Kayıt ara<input class="input" type="search" maxlength="120" id="compensation-query" value="${h(f.q)}" placeholder="Sipariş, müşteri, parça veya gerekçe"></label><label class="formfield">Kayıp kaynağı<select class="select" id="compensation-source">${options(compensationSources,f.source)}</select></label><label class="formfield">Süreç durumu<select class="select" id="compensation-state">${options(compensationStates,f.state)}</select></label><button type="submit" class="btn primary">Filtrele</button><button type="button" class="btn" onclick="RitimPremiumAPI.clearCompensations()">Temizle</button></form>${preferenceControls('compensations')}${v.totals?`<div class="flow-metrics">${flowMetric('Telafi izni',v.totals.quantity)}${flowMetric('Üretime ayrılan',v.totals.allocated)}${flowMetric('Ayrılabilecek',v.totals.remaining)}</div><p class="tiny">Toplamlar ${v.total} eşleşen kaydın tamamını kapsar.</p>`:''}</div><div class="compensation-results">${v.items.map(x=>`<article class="card pad compensation-card"><header><div><small>${h(compensationSources.find(r=>r[0]===x.source)?.[1]||'Belgelenmiş kayıp')}</small><h3>${h(x.partName||x.partNumber||x.orderNumber)}</h3><p>${h(x.orderNumber)}${x.customer?' · '+h(x.customer):''}</p></div><span class="pill" data-state="${['closed','completed'].includes(x.state)?'completed':x.state==='running'?'running':x.state==='legacy'?'paused':'planned'}">${h(compensationStates.find(r=>r[0]===x.state)?.[1]||'Telafi izni')}</span></header><p>${h(x.reason)}</p><div class="compensation-amounts"><span><small>İzin</small><b>${x.quantity} adet</b></span><span><small>Üretime ayrılan</small><b>${x.allocated??0} adet</b></span><span><small>Ayrılabilecek</small><b>${x.source==='legacy'?'İnceleme gerekli':(x.remaining??x.quantity)+' adet'}</b></span></div><progress value="${x.allocated||0}" max="${x.quantity}" aria-label="Telafi üretimine ayrılan oran"></progress><footer><button class="btn sm" onclick="RitimPremiumAPI.openOrder(${jsArg(x.orderId)})">Siparişi aç</button><button class="btn ${x.remaining>0&&!['closed','legacy'].includes(x.state)?'primary':''}" onclick="RitimPremiumAPI.openRecovery(${jsArg(x.orderId)})">${x.source==='legacy'?'Kaybı incele':x.remaining>0&&x.state!=='closed'?'Telafi üretimine devam et':'Üretim bağlantılarını incele'}</button></footer></article>`).join('')||'<section class="card pad workspace-empty"><h3>Eşleşen telafi kaydı yok</h3><p>Aramayı veya filtreleri değiştirin. Telafi izinleri siparişin kayıp ve telafi bölümünden oluşturulur.</p></section>'}</div>${v.nextAfter?'<button class="btn" onclick="RitimPremiumAPI.moreCompensations()">Daha fazla göster</button>':''}<p class="order-hint">Telafi izni sipariş adedini değiştirmez. Üretim tamamlandı durumu, bağlı işlerin tamamlandığını belirtir; müşteriye teslim ayrıca izlenir.</p></section>`}
 function compensationQuery(fresh=false){const p=new URLSearchParams(location.search),defaults={q:'',source:'all',state:'active',...(viewPreferences.compensations?.settings||{})};if(fresh||p.get('view')!=='compensations')return defaults;return {...defaults,...Object.fromEntries(['q','source','state'].filter(k=>p.has(k)).map(k=>[k,p.get(k)]))}}
