 function mountTemplateLibrary(){if(!templateLibrary){el('route-library')?.remove();return}const v=templateLibrary,d=v.editing;let dialog=el('route-library');if(!dialog){dialog=document.createElement('dialog');dialog.id='route-library';dialog.className='route-library';dialog.setAttribute('aria-labelledby','route-library-title');document.body.append(dialog);dialog.addEventListener('cancel',event=>{event.preventDefault();closeTemplateLibrary()})}dialog.innerHTML=`<header class="flow-heading"><div><span class="flow-eyebrow">TEKRAR KULLANILABİLİR ROTALAR</span><h2 id="route-library-title">${d?d.id?'Şablonu düzenle':'Yeni rota şablonu':'Rota şablonları'}</h2></div><button class="btn sm" type="button" aria-label="Şablon panelini kapat" onclick="RitimPremiumAPI.closeTemplates()">×</button></header><p>Şablonun bir kopyası yeni rotaya aktarılır. Sonraki şablon değişiklikleri mevcut üretim emirlerini etkilemez.</p><p class="field-error" id="template-error" role="alert">${h(v.error||'')}</p>${journal?.list().filter(x=>x.kind==='routeTemplate').map(x=>`<div class="master-version"><p>Şablon işleminin sonucu doğrulanmalı.</p><button class="btn" onclick="RitimPremiumAPI.retryWorkspaceTool(${jsArg(x.id)})">Aynı işlemi doğrula</button></div>`).join('')||''}${d?`<form onsubmit="event.preventDefault();RitimPremiumAPI.saveTemplate()"><label class="formfield">Şablon adı<input class="input" id="template-name" maxlength="120" required value="${h(d.name)}" placeholder="Örn. Standart işleme ve kaplama"></label><div class="template-operations">${d.operations.map((op,i)=>`<article class="template-operation"><div class="production-route-row"><span class="op-number">${i+1}</span><label class="formfield">Operasyon<input class="input" id="template-op-name-${i}" maxlength="120" value="${h(op.name)}" required></label><label class="formfield">Tür<select class="select" id="template-op-kind-${i}"><option value="internal" ${op.kind==='internal'?'selected':''}>İç operasyon</option><option value="external" ${op.kind==='external'?'selected':''}>Fason</option></select></label><div class="production-route-actions"><button class="btn sm" type="button" aria-label="${i+1}. adımı yukarı taşı" onclick="RitimPremiumAPI.templateLibraryChange('up',${i})" ${i?'':'disabled'}>↑</button><button class="btn sm" type="button" aria-label="${i+1}. adımı kaldır" onclick="RitimPremiumAPI.templateLibraryChange('remove',${i})" ${d.operations.length===1?'disabled':''}>×</button></div></div><details><summary>Tahmini süreler · isteğe bağlı</summary><div class="formgrid">${[['setupMinutes','Hazırlık · dk'],['cycleMinutes','Adet başı · dk']].map(([key,label])=>`<label class="formfield">${label}<input class="input" id="template-op-${key}-${i}" type="number" min="0" max="10080" step="0.001" value="${op[key]??''}"></label>`).join('')}</div></details></article>`).join('')}</div><button class="btn" type="button" onclick="RitimPremiumAPI.templateLibraryChange('add',0)" ${d.operations.length>=100?'disabled':''}>＋ Operasyon ekle</button><footer><button class="btn" type="button" onclick="RitimPremiumAPI.templateLibraryEdit(null)">Listeye dön</button><button class="btn primary" type="submit" ${busy?'disabled':''}>Şablonu kaydet</button></footer></form>`:`<form class="context-search" onsubmit="event.preventDefault();RitimPremiumAPI.searchTemplates(false)"><label class="formfield">Şablon ara<input class="input" id="template-query" type="search" maxlength="120" value="${h(v.q)}" placeholder="Şablon adı"></label><button class="btn" type="submit">Ara</button>${capable('planning.write')?'<button class="btn primary" type="button" onclick="RitimPremiumAPI.templateLibraryEdit(\'new\')">Yeni şablon</button>':''}</form><p class="tiny">${v.items.length} / ${v.total} şablon</p><div class="template-cards">${v.items.map(x=>`<article class="template-card"><h3>${h(x.name)}</h3><p>${x.operations.length} adım · ${x.operations.filter(op=>op.kind==='external').length} fason</p><ol>${x.operations.map(op=>`<li>${h(op.name)} <small>${op.kind==='external'?'Fason':'İç operasyon'}${op.setupMinutes!=null?' · hazırlık '+op.setupMinutes+' dk':''}${op.cycleMinutes!=null?' · adet başı '+op.cycleMinutes+' dk':''}</small></li>`).join('')}</ol><footer>${v.origin!=='master'?`<button class="btn primary" onclick="RitimPremiumAPI.useTemplate(${jsArg(x.id)})">Bu rotayı kullan</button>`:''}${capable('planning.write')?`<button class="btn sm" onclick="RitimPremiumAPI.templateLibraryEdit(${jsArg(x.id)})">Düzenle</button><details><summary>Diğer</summary><button class="btn sm" onclick="RitimPremiumAPI.deleteTemplate(${jsArg(x.id)})">Pasifleştir</button></details>`:''}</footer></article>`).join('')||'<p class="workspace-empty">Eşleşen şablon yok. Aramayı değiştirin veya ilk rotayı kaydedin.</p>'}</div>${v.nextAfter?'<button class="btn" onclick="RitimPremiumAPI.searchTemplates(true)">Daha fazla göster</button>':''}`}`;dialog.querySelector('form')?.addEventListener('input',captureTemplateEditor);if(!dialog.open)dialog.showModal()}
 let boardPicked=new Set(),boardBulk=null,boardHealth={state:'fresh',message:''},boardDay='';
 function boardStale(){return boardHealth.state!=='fresh'||!boardUpdated||Date.now()-boardUpdated.getTime()>90000}
 async function readMachineBoard(){const context=scope;try{const next=await api.machinePlanning();if(boardOperators===null&&next.jobs.some(j=>j.status==='running'&&j.operatorId)&&capable('orders.read')&&api.jobWorklist){try{const directory=await api.jobWorklist({limit:1});if(context===scope)boardOperators=directory.operators||[]}catch{}}if(context!==scope)throw Error('İş yeri değişti.');boardHealth={state:'fresh',message:''};boardUpdated=new Date();const valid=new Set(next.jobs.filter(j=>['waiting','paused'].includes(j.status)).map(j=>j.id));boardPicked=new Set([...boardPicked].filter(id=>valid.has(id)));if(boardBulk?.preview&&boardBulk.preview.revision!==next.revision){boardBulk.preview=null;boardBulk.error='Pano değişti. Hedefi kontrol edip önizlemeyi yeniden alın.'}return next}catch(e){if(scope===context)boardHealth={state:'stale',message:'Sunucuya ulaşılamadı. Son alınan kayıtlar gösteriliyor; taşıma için önce panoyu yenileyin.'};throw e}}
