 function mountBoardBulk(){if(!boardBulk){el('board-bulk-dialog')?.remove();return}const v=boardBulk,b=machineBoard;if(!b)return;let d=el('board-bulk-dialog');if(!d){d=document.createElement('dialog');d.id='board-bulk-dialog';d.className='route-library board-bulk-dialog';d.setAttribute('aria-labelledby','board-bulk-title');d.addEventListener('keydown',event=>{if(event.key!=='Tab')return;const items=[...d.querySelectorAll('button:not([disabled]),input:not([disabled]),select:not([disabled]),textarea:not([disabled]),summary,a[href],[tabindex]')].filter(x=>x.tabIndex>=0&&x.getClientRects().length);if(!items.length){event.preventDefault();d.focus();return}const first=items[0],last=items.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus()}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus()}});document.body.append(d);d.addEventListener('cancel',event=>{event.preventDefault();closeBoardBulk()})}const target=b.jobs.filter(j=>(j.machineId||'')===v.machine&&!boardPicked.has(j.id)&&j.status!=='running'),rows=v.preview?.changes||[],selected=rows.filter(x=>x.selected),affected=rows.filter(x=>!x.selected&&(x.before?.end!==x.after?.end||x.before?.position!==x.after?.position));d.innerHTML=`<header><div><span class="flow-eyebrow">ÖNİZLEMELİ TOPLU TAŞIMA</span><h2 id="board-bulk-title">${boardPicked.size} işi başka kuyruğa taşı</h2></div><button class="btn sm" aria-label="Taşıma panelini kapat" onclick="RitimPremiumAPI.boardCloseBulk()">×</button></header><p>İşler tek işlemde taşınır. Adetleri, operatör atamaları ve üretim kayıtları korunur. Hedef kuyruğa seçim sıranızla yerleşir.</p><form onsubmit="event.preventDefault();RitimPremiumAPI.boardPreviewBulk()"><div class="formgrid"><label class="formfield">Hedef kuyruk<select class="select" id="bulk-machine" onchange="RitimPremiumAPI.boardBulkTarget(this.value)">${[{id:'',code:'Atanmamış işler'},...b.machines].map(m=>`<option value="${m.id}" ${m.id===v.machine?'selected':''}>${h(m.code)}</option>`).join('')}</select></label><label class="formfield">Önüne yerleştir<select class="select" id="bulk-before" onchange="RitimPremiumAPI.boardBulkBefore(this.value)"><option value="">Kuyruğun sonu</option>${target.map(j=>`<option value="${j.id}" ${j.id===v.before?'selected':''}>${h(j.number+' · '+j.operation)}</option>`).join('')}</select></label></div><details><summary>Seçilen işler · hedef sıra</summary><ol>${[...boardPicked].map(id=>{const j=b.jobs.find(j=>j.id===id);return `<li>${h(j?.partName)} · ${h(j?.number)}</li>`}).join('')}</ol></details><p class="field-error" id="bulk-error" role="alert">${h(v.error||'')}</p>${journal.list().filter(x=>x.kind==='machineBatch').map(x=>`<div class="master-version"><p>İşlemin sonucu belirsiz. Yeni bir taşıma başlatmadan aynı işlemi doğrulayın.</p><button class="btn" type="button" onclick="RitimPremiumAPI.boardRetry(${jsArg(x.id)})">Aynı işlemi doğrula</button></div>`).join('')}<button class="btn" type="submit" ${busy||boardStale()?'disabled':''}>${v.preview?'Önizlemeyi yenile':'Taşımayı önizle'}</button></form>${v.preview?`<section class="bulk-preview" aria-labelledby="bulk-preview-title"><h3 id="bulk-preview-title">Kaydetmeden önce kontrol edin</h3><p>${h(boardDate(v.preview.estimatedAt))} tarihli önizleme · ${selected.length} seçili iş · ${affected.length} diğer işin sırası veya tahmini bitişi etkileniyor.</p><div class="bulk-preview-rows">${selected.concat(affected).slice(0,50).map(x=>`<article><div><b>${h(x.partName||x.number)}</b><small>${h(x.number)} · ${x.selected?'Taşınacak':'Kuyruk etkisi'}</small></div><span><small>Önceki bitiş</small>${h(boardDate(x.before?.end))}</span><span><small>Yeni tahmin</small>${h(boardDate(x.after?.end))}${x.after?.late?'<strong>Termin riski</strong>':''}</span></article>`).join('')}</div>${selected.length+affected.length>50?'<p>İlk 50 etki gösteriliyor; toplam etki sayısı yukarıdadır.</p>':''}<details><summary>Hedefte oluşacak kuyruk · ${v.preview.destinationQueue.length} iş</summary><ol>${v.preview.destinationQueue.map(x=>`<li>${x.selected?'→ ':''}${h(x.number)} · ${h(x.partName)}</li>`).join('')}</ol></details><p class="tiny">Belirsiz bitişler, eksik süre veya ön koşulları gösterir. Taşıma üretimi otomatik başlatmaz.</p><footer><button class="btn" onclick="RitimPremiumAPI.boardCloseBulk()">Vazgeç</button><button class="btn primary" id="bulk-apply" onclick="RitimPremiumAPI.boardApplyBulk()" ${busy||boardStale()||journal.list().some(x=>x.kind==='machineBatch')?'disabled':''}>Onayla ve taşı</button></footer></section>`:''}`;if(!d.open)d.showModal()}
