 function planningDayPicker(dates){const dateLabel=d=>new Date(d+'T12:00:00+03:00').toLocaleDateString('tr-TR',{day:'numeric',month:'short',weekday:'short'});return `<div class="compact-day-picker"><button class="btn" aria-label="Önceki gün" onclick="RitimPremiumAPI.boardDayStep(-1)" ${boardDay===dates[0]?'disabled':''}>‹</button><label><span class="sr-only">Gün</span><select class="select" id="timeline-day" onchange="RitimPremiumAPI.boardDay(this.value)">${dates.map(d=>`<option value="${d}" ${d===boardDay?'selected':''}>${dateLabel(d)}</option>`).join('')}</select></label><button class="btn" aria-label="Sonraki gün" onclick="RitimPremiumAPI.boardDayStep(1)" ${boardDay===dates.at(-1)?'disabled':''}>›</button></div>`}
 function compactBoardTimeline(){
  const b=machineBoard,dates=b.horizon?.dates||[],mobile=narrowWorkspace.matches,active=boardActiveMachine();if(!dates.length)return '<p class="compact-empty">Zaman görünümü için panoyu yenileyin.</p>';if(!dates.includes(boardDay))boardDay=dates[0];if(active==='')return `<p class="compact-time-hint">Atanmamış işler için başlangıç saati hesaplanmaz.</p>${compactBoardQueue()}`;
  const daily=mobile||boardScale==='day',days=daily?[boardDay]:dates,dateLabel=d=>new Date(d+'T12:00:00+03:00').toLocaleDateString('tr-TR',{day:'numeric',month:'short',weekday:'short'}),overlaps=(j,date)=>(j.schedule?.segments||[]).some(s=>Date.parse(s.start)<Date.parse(date+'T00:00:00+03:00')+86400000&&Date.parse(s.end)>Date.parse(date+'T00:00:00+03:00'));
  return `<section class="board-timeline compact-timeline planning-timeline"><div class="planning-time-toolbar"><span>${daily?'Günlük iş akışı':'Haftalık zaman çizelgesi'}</span>${!mobile?`<div class="board-view-toggle"><button class="btn" aria-pressed="${boardScale==='day'}" onclick="RitimPremiumAPI.boardScale('day')">Gün</button><button class="btn" aria-pressed="${boardScale==='week'}" onclick="RitimPremiumAPI.boardScale('week')">Hafta</button></div>`:''}<button class="btn sm" onclick="RitimPremiumAPI.boardSheet('options')" aria-label="Zaman tahmini hakkında">ⓘ</button></div>${daily?planningDayPicker(dates):''}${b.machines.filter(m=>active==='all'?guidedMachines().some(x=>x.id===m.id):m.id===active).map(m=>{const all=b.jobs.filter(j=>j.machineId===m.id&&boardVisibleJob(j)).sort((a,b)=>(a.schedule?.position||0)-(b.schedule?.position||0)),unknown=all.filter(j=>!j.schedule?.end),known=all.filter(j=>j.schedule?.end&&(!daily||overlaps(j,boardDay))),limit=boardVisibleCounts.get(m.id)||10,c=m.capacity;return `<section class="timeline-machine card"><header><h3 title="${h(m.code)}">${h(m.code)}</h3><small>${known.length} zamanlı iş${unknown.length?' · '+unknown.length+' belirsiz':''}</small></header><div class="capacity-week" style="--days:${days.length}">${days.map(date=>{const d=c?.days?.find(x=>x.date===date);return `<div><small>${dateLabel(date)}</small><b>${d?.scheduledMinutes||0} / ${d?.availableMinutes||0} dk</b><progress value="${d?.scheduledMinutes||0}" max="${Math.max(1,d?.scheduledMinutes||0,d?.availableMinutes||0)}" aria-label="${h(m.code+' '+dateLabel(date)+' bilinen doluluk')}"></progress></div>`}).join('')}</div><div class="timeline-scroll" role="region" tabindex="0" aria-label="${h(m.code)} zaman çizelgesi"><div class="timeline-table" style="--days:${days.length}"><div class="timeline-axis"><b>İş / operasyon</b><div class="timeline-tracks">${days.map(date=>`<div><b>${dateLabel(date)}</b><small>00 · 06 · 12 · 18 · 24</small></div>`).join('')}</div></div>${known.slice(0,limit).map(j=>`<div class="timeline-row ${h(j.status)}" data-timeline-job="${j.id}"><div class="timeline-job"><span class="planning-status ${h(j.status)}">${planningStatus(j)}${j.schedule.late?' · Termin riski':''}</span><button class="timeline-job-open" title="${h(j.partName)}" onclick="RitimPremiumAPI.boardJob(${jsArg(j.id)})">${h(j.partName||j.number)}</button><small>${h(j.operation)} · ${j.quantity} adet</small>${capable('planning.write')&&['waiting','paused'].includes(j.status)?`<button class="planning-time-edit" data-time-edit="${j.id}" aria-label="${h(j.number)} süre düzenle" onclick="RitimPremiumAPI.boardEditTime(${jsArg(j.id)})"><span aria-hidden="true">✎</span> ${h(new Intl.NumberFormat('tr-TR',{maximumFractionDigits:1}).format(planningDuration(j)))} dk</button>`:''}${mobile?`<span class="planning-time-range">${h(boardDate(j.schedule.start))} → ${h(boardDate(j.schedule.end))}</span>`:''}${boardSelecting?boardPickControl(j):''}</div><div class="timeline-tracks">${days.map(date=>{const base=Date.parse(date+'T00:00:00+03:00'),end=base+86400000;return `<div class="timeline-day">${(c?.days?.find(x=>x.date===date)?.windows||[]).map(w=>`<i class="timeline-work-window" style="left:${(Date.parse(w.start)-base)/864000}%;width:${(Date.parse(w.end)-Date.parse(w.start))/864000}%" aria-hidden="true"></i>`).join('')}${(j.schedule.segments||[]).filter(s=>Date.parse(s.start)<end&&Date.parse(s.end)>base).map(s=>`<button class="timeline-segment ${h(j.status)} ${j.schedule.late?'late':''}" style="left:${(Math.max(base,Date.parse(s.start))-base)/864000}%;width:max(6px,${(Math.min(end,Date.parse(s.end))-Math.max(base,Date.parse(s.start)))/864000}%)" aria-label="${h(j.operation+' '+boardDate(s.start)+' → '+boardDate(s.end))}" title="${h(boardDate(s.start)+' → '+boardDate(s.end))}" onclick="RitimPremiumAPI.boardJob(${jsArg(j.id)})"></button>`).join('')}</div>`}).join('')}</div>${inlineTimingContent(j)}</div>`).join('')||'<p class="compact-empty">Bu dönemde zamanı hesaplanmış iş yok.</p>'}</div></div>${known.length>limit?`<button class="btn compact-more" onclick="RitimPremiumAPI.boardMore(${jsArg(m.id)})">Daha fazla göster · ${limit} / ${known.length}</button>`:''}${unknown.length?`<details class="planning-unknown" ${unknown.some(x=>x.id===boardTimeEdit?.id)?'open':''}><summary>Zamanı belirsiz <b>${unknown.length}</b><span>Süre veya ön koşul eksik</span></summary><div class="planning-unknown-list">${unknown.slice(0,limit).map(compactBoardJob).join('')}${unknown.length>limit?`<button class="btn compact-more" onclick="RitimPremiumAPI.boardMore(${jsArg(m.id)})">Daha fazla göster</button>`:''}</div></details>`:''}</section>`}).join('')}</section>`;
 }

 function captureBoardDrawer(){if(!boardDrawer)return;if(boardDrawer.kind==='filters'){boardDrawer.query=el('board-search')?.value??boardDrawer.query;boardDrawer.filter=el('board-filter')?.value??boardDrawer.filter}if(boardDrawer.kind==='job'){for(const [key,id]of [['machine','board-machine-'],['before','board-before-'],['setup','timing-setup-'],['cycle','timing-cycle-']])boardDrawer[key]=el(id+boardDrawer.id)?.value??boardDrawer[key]}}
 function boardDrawerContent(){const d=boardDrawer,b=machineBoard;if(d.kind==='filters')return `<h2 id="board-drawer-title">İş ara ve filtrele</h2><form oninput="RitimPremiumAPI.boardCaptureDrawer()" onsubmit="event.preventDefault();RitimPremiumAPI.boardApplyFilters()"><label class="formfield">İş ara<input class="input" id="board-search" maxlength="120" type="search" value="${h(d.query)}" placeholder="Parça, müşteri veya sipariş"></label><label class="formfield">Durum<select class="select" id="board-filter">${[['all','Tüm açık işler'],['running','Çalışan işler'],['ready','Ön koşulları hazır'],['blocked','Bekleyen işler'],['late','Termini geçenler']].map(([id,label])=>`<option value="${id}" ${d.filter===id?'selected':''}>${label}</option>`).join('')}</select></label><footer><button class="btn" type="button" onclick="RitimPremiumAPI.boardResetFilters()">Temizle</button><button class="btn primary" type="submit">Uygula</button></footer></form>`;
 if(d.kind==='job'){const j=b.jobs.find(x=>x.id===d.id);if(!j)return '<h2 id="board-drawer-title">İş artık bu panoda değil</h2>';const movable=capable('planning.write')&&['waiting','paused'].includes(j.status),targets=b.jobs.filter(x=>(x.machineId||'')===d.machine&&x.id!==j.id&&x.status!=='running');return `<h2 id="board-drawer-title">${h(j.partName||j.number)}</h2><p>${h(j.operation)} · ${h(displayStatus(j.status))}</p><dl class="board-job-facts"><div><dt>Sipariş</dt><dd>${h(j.orderNumber)}</dd></div><div><dt>Müşteri</dt><dd>${h(j.customer)}</dd></div><div><dt>İş emri</dt><dd>${h(j.number)}</dd></div><div><dt>Miktar</dt><dd>${j.produced} / ${j.quantity} adet</dd></div><div><dt>Termin</dt><dd>${h(j.dueDate||'Belirlenmedi')}</dd></div><div><dt>Tahmini bitiş</dt><dd>${h(boardDate(j.schedule?.end))}</dd></div></dl><p>${h(j.schedule?.reason||j.attention?.reason||'Ön koşulları iş emrinde inceleyin.')}</p><button class="btn" onclick="RitimPremiumAPI.boardOpenJobDetail(${jsArg(j.id)},${jsArg(j.orderId)})">İş emrini aç</button>${movable?`<section class="board-job-transfer"><h3>Taşı / sırala</h3><label class="formfield">Hedef kuyruk<select class="select" id="board-machine-${j.id}" onchange="RitimPremiumAPI.boardDrawerTarget(this.value)">${[{id:'',code:'Atanmamış işler'},...b.machines].map(m=>`<option value="${m.id}" ${m.id===d.machine?'selected':''}>${h(m.code)}</option>`).join('')}</select></label><label class="formfield">Önüne yerleştir<select class="select" id="board-before-${j.id}" onchange="RitimPremiumAPI.boardCaptureDrawer()"><option value="">Kuyruğun sonu</option>${targets.map(x=>`<option value="${x.id}" ${x.id===d.before?'selected':''}>${h(x.number+' · '+x.operation)}</option>`).join('')}</select></label><button class="btn primary" onclick="RitimPremiumAPI.boardMoveFromDrawer()" ${boardStale()?'disabled':''}>Taşı</button><details><summary>Tahmini süreyi düzenle</summary><div oninput="RitimPremiumAPI.boardCaptureDrawer()">${timingEditor({...j,timing:{...j.timing,setupMinutes:d.setup,cycleMinutes:d.cycle}})}</div></details></section>`:'<p>Çalışan işi taşımadan önce operatör ekranından duraklatın.</p>'}`}
 const active=boardActiveMachine(),m=b.machines.find(x=>x.id===active)||b.machines[0];return `<h2 id="board-drawer-title">Planlama seçenekleri</h2><p>Son doğrulama: ${h(boardUpdated?.toLocaleTimeString('tr-TR')||'Henüz alınmadı')}</p><div class="board-option-actions"><button class="btn" onclick="RitimPremiumAPI.boardRefresh()">Panoyu yenile</button><button class="btn" onclick="RitimPremiumAPI.boardFocus()">${boardFocus?'Odak modunu kapat':'Odak modu'}</button><button class="btn" onclick="RitimPremiumAPI.boardNavigate('production-orders')">Üretim emirleri</button><button class="btn" onclick="RitimPremiumAPI.boardNavigate('jobs')">İş emirleri</button></div><details><summary>Zaman tahmini hakkında</summary><p>İstanbul saati kullanılır. Mola, gece ve hafta sonu üretim süresine eklenmez. Eksik süre ve ön koşullarda kesin saat gösterilmez. Doluluk yalnız bilinen işleri kapsar.</p></details>${m?`<details><summary>Makine ve vardiya · ${h(m.code)}</summary>${machineCapacity(m)}</details>`:''}${capable('master.write')?'<details><summary>Yeni makine ekle</summary><form onsubmit="event.preventDefault();RitimPremiumAPI.boardCreateMachine()"><label class="formfield">Makine kodu<input class="input" id="board-new-machine" maxlength="120" required></label><button class="btn primary" type="submit">Makineyi ekle</button></form></details>':''}<details><summary>Oturum ve iş yeri</summary><p>${h(session?.identity?.displayName||'')}</p><button class="btn" onclick="RitimPremiumAPI.boardChangeSite()">İş yeri değiştir</button><button class="btn" onclick="RitimPremiumAPI.logout()">Oturumu kapat</button></details>`}
 function closeBoardDrawer(){if(busy)return;const id=boardDrawer?.id,kind=boardDrawer?.kind;boardDrawer=null;el('board-detail-dialog')?.remove();if(id)document.querySelector('[data-job="'+id+'"],[data-timeline-job="'+id+'"] .timeline-job-open')?.focus({preventScroll:true});else document.querySelector(kind==='filters'?'[aria-label="İş ara ve filtrele"]':'[aria-label="Planlama seçenekleri"]')?.focus({preventScroll:true})}
 function mountBoardDrawer(){if(!boardDrawer||page!=='machine-planning'){el('board-detail-dialog')?.remove();return}let d=el('board-detail-dialog');if(!d){d=document.createElement('dialog');d.id='board-detail-dialog';d.className='route-library board-detail-dialog';d.setAttribute('aria-labelledby','board-drawer-title');document.body.append(d);d.addEventListener('cancel',e=>{e.preventDefault();closeBoardDrawer()});d.addEventListener('keydown',e=>{if(e.key!=='Tab')return;const f=[...d.querySelectorAll('button:not([disabled]),input:not([disabled]),select:not([disabled]),summary,a[href]')].filter(x=>x.getClientRects().length&&![...d.querySelectorAll('details:not([open])')].some(v=>v.contains(x)&&x!==v.querySelector(':scope > summary')));if(e.shiftKey&&document.activeElement===f[0]){e.preventDefault();f.at(-1)?.focus()}else if(!e.shiftKey&&document.activeElement===f.at(-1)){e.preventDefault();f[0]?.focus()}})}const drawerKey=boardDrawer.kind+':'+(boardDrawer.id||''),same=d.dataset.drawerKey===drawerKey,opened=same?[...d.querySelectorAll('details')].map(x=>x.open):[],fields=same&&boardDrawer.kind==='options'?[...d.querySelectorAll('input[id],select[id]')].map(x=>({id:x.id,value:x.value,checked:x.checked})):[],top=d.scrollTop;d.dataset.drawerKey=drawerKey;d.innerHTML=`<button class="btn board-drawer-close" aria-label="Paneli kapat" onclick="RitimPremiumAPI.boardCloseDrawer()">×</button>${boardDrawerContent()}${error?`<p class="field-error" role="alert">${h(error)}</p>`:''}`;[...d.querySelectorAll('details')].forEach((x,i)=>{x.open=opened[i]||false});for(const f of fields){const x=el(f.id);if(x){x.value=f.value;x.checked=f.checked}}if(!d.open)d.showModal();if(same)d.scrollTop=top;guidedMountMoveButton()}
 function workspaceDate(value){return value?new Date(value+'T12:00:00+03:00').toLocaleDateString('tr-TR',{day:'numeric',month:'short',year:'numeric'}):'Belirlenmedi'}
 function workspaceHeader(title){const site=scope&&session?.memberships.find(m=>m.tenantId===scope.tenantId&&m.siteId===scope.siteId);return `<header class="header workspace-header"><h1>${h(title)}</h1>${scope?`<div class="workspace-header-tools"><details class="api-search-disclosure workspace-search" ${globalSearchOpen?'open':''} ontoggle="RitimPremiumAPI.searchToggle(this.open)"><summary aria-label="Kayıtlarda ara" title="Kayıtlarda ara"><svg class="planning-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/></svg><span>Kayıtlarda ara</span></summary><form class="api-global-search" role="search" onsubmit="event.preventDefault();RitimPremiumAPI.search()" onkeydown="if(event.key==='Escape'){event.preventDefault();this.parentElement.open=false;this.parentElement.querySelector('summary').focus()}"><label for="global-search-input">Tüm kayıtlarda ara</label><div><input id="global-search-input" class="input" minlength="2" maxlength="120" value="${h(searchTerm)}" placeholder="Sipariş, parça veya iş emri"><button class="btn primary" type="submit">Ara</button></div></form></details><details class="api-mobile-menu"><summary aria-label="Ana menüyü aç">☰ <span>Menü</span></summary><div class="workspace-mobile-popover"><nav class="api-mobile-nav" aria-label="Ana mobil gezinme">${mainNavigation()}</nav><div class="workspace-mobile-account"><strong>${h(session?.identity?.displayName||'')}</strong><small>${h(site?.tenantName||'')} / ${h(site?.siteName||'')}</small><button class="btn" onclick="RitimPremiumAPI.changeSite()">İş yeri değiştir</button><button class="btn" onclick="RitimPremiumAPI.logout()">Oturumu kapat</button></div></div></details></div>`:''}</header>${scope?secondaryNavigation():''}`}
 function productionDetailContent(){const p=poDetail;if(!p)return '';const editable=capable('planning.write')&&p.status!=='completed'&&detail?.status!=='closed';return `<section class="production-orders-page refreshed-production"><div class="po-back-row"><button class="btn sm" onclick="RitimPremiumAPI.returnProductionList()">← Üretim emirleri</button>${p.planningState==='unplanned'&&!p.workOrders.length&&capable('planning.write')?`<button class="btn sm" onclick="RitimPremiumAPI.editPo(${jsArg(p.id)})">Miktar ve rotayı düzenle</button>`:''}</div><section class="card pad po-summary"><div class="po-summary-title"><div><span class="workspace-eyebrow">ÜRETİM EMRİ</span><h2>${h(p.partName||p.orderNumber)}</h2><p>${h(p.customer)} · <button class="workspace-text-link" onclick="RitimPremiumAPI.openOrder(${jsArg(p.orderId)})">${h(p.orderNumber)}</button></p></div><span class="pill" data-state="${h(p.status)}">${h(poStatus(p.status))}</span></div><div class="po-summary-facts"><div><small>Üretilecek</small><strong>${p.quantity} <span>adet</span></strong></div><div><small>Operasyon</small><strong>${p.route?.length||p.workOrders.length} <span>adım</span></strong></div><div><small>Emir numarası</small><details class="po-reference"><summary title="${h(p.number)}">${h(recordReference(p.number))}</summary><code>${h(p.number)}</code></details></div><div><small>Hedef tarih</small>${editable&&p.planningState!=='held'?`<details class="po-date-editor" ${p.planningState==='unplanned'?'open':''}><summary>✎ ${h(p.plannedDate?workspaceDate(p.plannedDate):'Tarih seç ve iş emirlerini oluştur')}</summary><form onsubmit="event.preventDefault();RitimPremiumAPI.poState('plan')"><label class="formfield">Hedef tarih<input class="input" id="po-plan-date" type="date" required value="${h(p.plannedDate||'')}"></label><button class="btn primary" type="submit" ${p.route?.length?'':'disabled'}>${p.planningState==='unplanned'?'İş emirlerini oluştur':'Hedef tarihi güncelle'}</button></form></details>`:`<b>${h(workspaceDate(p.plannedDate))}</b>`}</div></div>${p.holdReason?`<p class="flow-notice">Bekleme nedeni: ${h(p.holdReason)}</p>`:''}${editable?`<div class="po-more-actions">${p.planningState==='held'?'<button class="btn primary" onclick="RitimPremiumAPI.poState(\'resume\')">Beklemeyi kaldır</button>':`<details><summary>Beklemeye al</summary><form onsubmit="event.preventDefault();RitimPremiumAPI.poState('hold')"><label class="formfield">Bekleme nedeni<input class="input" id="po-hold-reason" maxlength="120" required placeholder="Örn. Malzeme bekleniyor"></label><button class="btn" type="submit">Beklemeye al</button></form></details>`}</div>`:''}</section><section class="card pad po-work-orders"><div class="workspace-section-heading"><h3>Bağlı iş emirleri</h3><span>${p.workOrders.length} iş emri</span></div>${!p.route?.length?'<p class="flow-notice">Planlamak için önce Miktar ve rotayı düzenle adımından operasyon ekleyin.</p>':''}${!p.workOrders.length?`<p class="po-empty-description">${p.route?.length||0} operasyon hazır. Hedef tarihni belirleyip Planla dediğinizde iş emirleri oluşur.</p><ol class="po-route-preview">${(p.route||[]).map(x=>`<li><b>${h(x.name)}</b><span>${x.kind==='external'?'Fason':'İç operasyon'}</span></li>`).join('')}</ol>`:''}${p.workOrders.map(x=>`<article class="production-child"><span class="op-number">${x.sequence+1}</span><div><b>${h(x.name)}</b><small title="${h(x.number)}">${h(recordReference(x.number))} · ${x.quantity} adet · ${x.kind==='external'?'Fason':'İç operasyon'}</small><small class="flow-reason">${h(x.attention?.reason||poStatus(x.status))}</small></div><span class="pill" data-state="${h(x.status)}">${h(poStatus(x.status))}</span>${x.kind==='internal'?`<button class="btn sm" onclick="RitimPremiumAPI.openJob(${jsArg(x.id)},${jsArg(p.orderId)})">İş emrini aç</button>`:`<button class="btn sm" onclick="RitimPremiumAPI.poSupplierOpen(${jsArg(x.id)})">Fason takibi</button>`}</article>`).join('')}</section>${poFlow?.outputs.length||poFlow?.dispatches.length?poFlowContent():'<details class="card pad po-flow-empty"><summary>Operasyonlar arası akış</summary><p>Kalite onaylı çıktılar oluştuğunda ayırma, gönderme ve kabul işlemleri burada görünür.</p></details>'}</section>`}
 let inventoryStockMaterial='',inventoryStockLocation='',inventoryBalanceQuery='',inventoryMaterialLabels=new Map();
 function stockFiltersContent(){const x=inventoryView,materials=[...new Map(x.balances.map(b=>[b.materialId,{id:b.materialId,code:b.materialCode}])).values()],locations=[...new Set(x.balances.map(b=>b.locationId))];return `<div class="stock-filter-row"><label class="formfield" data-inventory-panel="stock" ${inventoryTask==='stock'?'':'hidden'}>Malzeme<select class="select" id="stock-material-filter" onchange="RitimPremiumAPI.stockFilter('material',this.value)"><option value="">Tüm malzemeler</option>${materials.map(m=>`<option value="${h(m.id)}" ${inventoryStockMaterial===m.id?'selected':''}>${h(m.code)}</option>`).join('')}</select></label><label class="formfield" data-inventory-panel="stock" ${inventoryTask==='stock'?'':'hidden'}>Konum<select class="select" id="stock-location-filter" onchange="RitimPremiumAPI.stockFilter('location',this.value)"><option value="">Tüm konumlar</option>${locations.map(id=>`<option value="${h(id)}" ${inventoryStockLocation===id?'selected':''}>${h(x.locations.find(l=>l.id===id)?.code||shortReference(id))}</option>`).join('')}</select></label><label class="formfield">Lot veya konum ara<input class="input" type="search" id="inventory-balance-query" value="${h(inventoryBalanceQuery)}" oninput="RitimPremiumAPI.inventoryFilterBalance(this.value)" placeholder="Lot kodu, malzeme veya konum"></label><span id="stock-visible-count" role="status"></span></div>`}
 function stockBalanceRows(){const x=inventoryView;return `<div class="inventory-balances refreshed-stock"><div class="stock-table-heading"><span>Malzeme</span><span>Lot</span><span>Konum</span><span>Depodaki miktar</span></div>${x.balances.map(a=>{const material=x.materials.find(m=>m.id===a.materialId),location=x.locations.find(l=>l.id===a.locationId),path=inventoryLocationPath(a.locationId);return `<article data-material="${h(a.materialId)}" data-location="${h(a.locationId)}" data-stock-quantity="${a.quantity}" data-balance-search="${h([a.materialCode,material?.description,a.lotCode,path].join(' ').toLocaleLowerCase('tr-TR'))}"><div><strong>${h(material?.description||inventoryMaterialLabels.get(a.materialId)||a.materialCode)}</strong><small>${h(a.materialCode)}</small></div><div><small class="stock-mobile-label">Lot</small><b>${h(a.lotCode)}</b></div><div title="${h(path)}"><small class="stock-mobile-label">Konum</small><b>${h(location?.code||shortReference(a.locationId))}</b><small class="stock-path">${h(path)}</small></div><strong class="stock-quantity">${a.quantity} <small>adet</small></strong></article>`}).join('')||'<p>Stok yok.</p>'}<p id="stock-no-match" class="inventory-no-results" hidden>Seçili malzeme, lot ve konum için bakiye bulunamadı.</p></div>`}
 function layoutInventoryPanels(){const panel=document.querySelector('.refreshed-stock')?.closest('section');if(inventoryTask==='stock'&&panel){let anchor=panel;for(const node of document.querySelectorAll('.inventory-settings')){anchor.after(node);anchor=node}}else if(inventoryTask==='receipt'){const receipt=document.querySelector('section[data-inventory-panel="receipt"]'),catalog=document.querySelector('.inventory-catalog');if(receipt&&catalog)receipt.before(catalog)}}
 function applyStockFilters(){let visible=0;for(const row of document.querySelectorAll('[data-balance-search]')){row.hidden=!((inventoryTask==='pick'?Number(row.dataset.stockQuantity)>0:row.dataset.balanceSearch.includes(inventoryBalanceQuery.toLocaleLowerCase('tr-TR')))&&(inventoryTask!=='stock'||(!inventoryStockMaterial||row.dataset.material===inventoryStockMaterial)&&(!inventoryStockLocation||row.dataset.location===inventoryStockLocation)));if(!row.hidden)visible++}if(el('stock-visible-count'))el('stock-visible-count').textContent=visible+' / '+inventoryView.balances.length+' lot / konum';if(el('stock-no-match'))el('stock-no-match').hidden=visible>0||!inventoryView.balances.length}

  // Operations workspace: retain command forms and guards; organize their presentation.
 const operationsLimits={quality:20,rework:20};
 function operationsTemplate(markup){const t=document.createElement('template');t.innerHTML=markup;return t}
 function operationsEmpty(title,text){return `<div class="operations-empty"><strong>${h(title)}</strong><p>${h(text)}</p></div>`}
 function operationsQualityQueue(){const limit=operationsLimits.quality,rows=qualityQueue.slice(0,limit);return `<section class="card pad operations-workspace"><header class="flow-heading"><div><span class="flow-eyebrow">KALİTE KUYRUĞU</span><h2>Kalite</h2><p>${qualityTotal} işte karar bekleniyor · ${jobs.length} iş yüklendi</p></div><button class="btn" onclick="RitimPremiumAPI.navigate('quality-list')">Kontrolleri yenile</button></header><h3>Karar bekleyen çıktılar</h3><div class="operations-queue">${rows.map(x=>`<article class="operations-row"><div><button class="operations-title" onclick="RitimPremiumAPI.openQualityJob(${jsArg(x.job.id)},${jsArg(x.job.orderId)})">${h(x.job.partName||x.job.workOrderNumber)} · ${h(x.job.operation||'')}</button><p><button class="guided-order-link" onclick="RitimPremiumAPI.orderPeek(${jsArg(x.job.orderId)})">${h(x.job.orderNumber||'Sipariş akışı')}</button> · ${h(x.job.workOrderNumber||'')}</p><small title="${h(x.output.outputLotId||x.output.eventId)}">Çıktı ${h(shortReference(x.output.outputLotId||x.output.eventId))}${x.output.provenanceStatus==='historical_unreconciled'?' · Tarihsel iz doğrulanamadı':''}</small></div><div class="operations-count"><b>${h(x.output.unresolved)}</b><small>karar bekleyen adet</small></div><button class="btn primary" onclick="RitimPremiumAPI.openQualityJob(${jsArg(x.job.id)},${jsArg(x.job.orderId)})">Kontrolü aç</button></article>`).join('')||operationsEmpty('Doğrulanabilen işlerde karar bekleyen çıktı bulunamadı.','Yeni üretim çıktıları kontrol beklediğinde burada görünür.')}</div>${qualityQueue.length>limit?`<button class="btn" onclick="RitimPremiumAPI.operationsMore('quality')">${qualityQueue.length-limit} çıktı daha göster</button>`:''}${qualityCursor?'<button class="btn" onclick="RitimPremiumAPI.moreQuality()">Daha fazla bekleyen iş</button>':''}${qualityQueueErrors.length?`<div class="operations-warning" role="alert"><p>Bazı iş emirlerinin kalite durumu alınamadı; bekleyenler listesi eksik olabilir.</p>${qualityQueueErrors.map(x=>`<p>${h(x.job.workOrderNumber)} · ${h(x.message)} <button class="btn" onclick="RitimPremiumAPI.openQualityJob(${jsArg(x.job.id)},${jsArg(x.job.orderId)})">İşi aç</button></p>`).join('')}</div>`:''}</section>`}
 function operationsReworkRows(){return reworkDecisions.filter(d=>reworkHistory||d.available>0||d.allocations.some(a=>a.outstanding>0&&!['complete','cancelled'].includes(a.status)))}
 function operationsRework(markup){const t=operationsTemplate(markup),root=t.content.firstElementChild;root.classList.add('operations-workspace','operations-rework');const rows=[...root.children].filter(e=>e.tagName==='ARTICLE');for(const [i,row]of rows.entries()){row.classList.add('operations-rework-row');if(i>=operationsLimits.rework)row.remove();const p=row.querySelector('p');if(p){p.title=p.textContent;p.textContent=p.textContent.replace(/Çıktı lotu .+$/, 'Çıktı lotu '+shortReference(row.querySelector('[onclick*="openLotTrace"]')?.getAttribute('onclick')?.match(/\('([^']+)/)?.[1]||'İz bilgisi'));}const fields=[...row.querySelectorAll(':scope > .formfield, :scope > .btn.primary')];if(fields.length){const form=document.createElement('div');form.className='operations-inline';fields[0].before(form);fields.forEach(e=>form.append(e));}}
 if(operationsReworkRows().length>operationsLimits.rework)root.insertAdjacentHTML('beforeend',`<button class="btn" onclick="RitimPremiumAPI.operationsMore('rework')">${operationsReworkRows().length-operationsLimits.rework} tamir kaydı daha göster</button>`);return t.innerHTML}
 function qualityScreen(){const t=operationsTemplate(qualityScreenOriginal()),root=t.content.firstElementChild;if(!root)return t.innerHTML;root.classList.add('operations-workspace','operations-quality');const heading=root.querySelector('h2'),job=jobs.find(j=>j.id===jobSelected);heading.textContent=detail?.partName||job?.workOrderNumber||'Kalite kontrol';heading.insertAdjacentHTML('afterend',`<p class="operations-context">Kalite kontrol · ${h(job?.workOrderNumber||'İş emri')} · <b>${qualityView.outputs.reduce((n,o)=>n+Number(o.unresolved||0),0)} adet karar bekliyor</b></p>`);for(const row of root.querySelectorAll(':scope > article')){row.classList.add('operations-quality-output');const p=row.querySelector('p');if(p){const full=p.textContent;p.title=full;p.textContent='Üretim çıktısı · '+shortReference(qualityView.outputs.find(o=>full.includes(o.eventId))?.outputLotId||'Lot bilgisi');}}return t.innerHTML}
