 function operationsShippingQuantity(){if(shippingTask==='allocate')return shippingView.totals?.availableToShip;const list=logisticsRecord?.kind==='shipping'?shippingView.shippingOrders.filter(x=>x.id===logisticsRecord.id):shippingView.shippingOrders,active=list.find(x=>x.id===shippingSelectedId)||list[0],events=shippingView.events.filter(x=>x.shippingOrderId===active?.id),source=shippingTask==='dispatch'?'allocate':'dispatch',target=shippingTask==='dispatch'?'dispatch':'deliver',key=shippingTask==='dispatch'?'allocationId':'dispatchId';return events.filter(x=>x.type===source).reduce((n,x)=>n+Math.max(0,x.quantity-events.filter(e=>e.type===target&&e[key]===x.id).reduce((sum,e)=>sum+e.quantity,0)),0)}
