 function captureWarehouseDraft(){if(el('inv-job'))warehouseDraft.job=el('inv-job').value;if(el('inv-balance'))warehouseDraft.balance=el('inv-balance').value;if(el('inv-quantity'))warehouseDraft.quantity=el('inv-quantity').value}
