 function warehouseAvailability(){if(inventoryTask!=='pick')return;const job=warehouseSelectedJob(),input=el('inv-quantity'),max=warehouseMaximum(),[lot,location]=(el('inv-balance')?.value||'').split('|'),balance=inventoryView.balances.find(b=>b.lotId===lot&&b.locationId===location),remaining=job&&Number.isSafeInteger(job.received)?Math.max(0,job.quantity-job.received):null;if(input)input.max=String(max);const context=el('warehouse-job-context');if(context)context.textContent=job?job.workOrderNumber+' · Hedef '+job.quantity+' adet'+(remaining===null?'':' · Kabul bekleyen '+remaining+' adet'):'Önce teslim yapılacak işi seçin.';const info=el('inventory-available');if(info)info.textContent=balance?'Kaynak bakiyesi '+balance.quantity+' adet · Bu işe teslim edilebilecek '+max+' adet':job?'Bakiyesi olan kaynak lotu seçin.':'';const value=Number(input?.value),valid=Number.isSafeInteger(value)&&value>0&&value<=max,button=document.querySelector('.warehouse-pick-submit');if(button)button.disabled=busy||!capable('stock.write')||!valid||!job;const result=el('warehouse-pick-result');if(result)result.textContent=job&&remaining===0?'Bu işin plan miktarı kadar girdi kabul edilmiş.':input?.value&&!valid?(max>0?'1–'+max+' arasında tam adet girin.':'Önce iş emri ve kullanılabilir kaynak seçin.'):valid?'Teslim sonrası kaynakta '+(balance.quantity-value)+' adet'+(remaining===null?'':', işte kabul bekleyen '+(remaining-value)+' adet kalır.') :''}

