 async boardMove(id,machine,before){if(busy||!capable('planning.write'))return;if(boardStale()){boardNotice='Pano güncel değil. Önce bağlantıyı doğrulayın.';draw();return}if(journal.list().some(x=>['machinePlanning','machineBatch'].includes(x.kind))){boardNotice='Önce bekleyen taşıma işlemini doğrulayın.';draw();return}const left=document.querySelector('.machine-board')?.scrollLeft||0;await run(async()=>{const row=await journal.begin({...scope,kind:'machinePlanning',target:'',body:{payload:{workOrderId:id,machineId:machine||null,beforeId:before||null,revision:machineBoard.revision,reason:'Makine planlama panosundan kuyruk düzenlendi'}}});try{await journal.execute(row);followBoardMove(machine);boardNotice='İşin makine kuyruğu ve sırası kaydedildi.'}catch(e){if(journal.list().some(x=>x.id===row.id))boardHealth={state:'stale',message:'Taşıma sonucu henüz doğrulanmadı. Son pano gösteriliyor; aynı işlemi doğrulayın.'};if(e.code==='VERSION_CONFLICT'){machineBoard=await readMachineBoard();boardUpdated=new Date();boardNotice='Pano başka bir kullanıcı tarafından değiştirildi. Güncel sıra gösteriliyor; taşıma işlemini tekrar yapın.'}throw e}machineBoard=await readMachineBoard();boardUpdated=new Date();if(!error){const moved=machineBoard.jobs.filter(x=>(x.machineId||'')===(machine||'')).sort((a,b)=>(a.schedule?.position||0)-(b.schedule?.position||0)),position=moved.findIndex(x=>x.id===id)+1,name=machineBoard.machines.find(m=>m.id===machine)?.code||'Atanmamış işler';boardNotice=name+' · '+position+'. sıraya taşındı.'}});const board=document.querySelector('.machine-board');if(board)board.scrollLeft=left;const target=document.querySelector('[data-job="'+id+'"]');if(target){target.focus({preventScroll:true});target.scrollIntoView({block:'nearest',inline:'nearest'})}},

